alter table public.exams disable trigger trg_exams_sync_bank;
do $do$ declare r jsonb; e jsonb; h text; begin
  for r in select * from jsonb_array_elements($j$[{"id":457372,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Có thể sử dụng bộ thí nghiệm (hình bên) để tìm hiểu về mối liên hệ giữa áp suất và thể tích của một lượng khí xác định ở nhiệt độ không đổi.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790391254602-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Trình tự thí nghiệm: Nén (giữ nguyên nhiệt độ) khí trong xilanh; Ghi giá trị thể tích và giá trị áp suất khí; Lặp lại các thao tác.","answer":true},{"text":"Với kết quả thu được ở bảng bên, công thức liên hệ áp suất theo thể tích là  $p=\\frac{23}{V}$ ,  $p$  đo bằng bar (1 bar = 105 Pa), V đo bằng cm3.","answer":true},{"text":"Lượng khí đã dùng trong thí nghiệm là 8.10<sup>−4</sup> mol.","answer":false},{"text":"Thí nghiệm này đã chứng minh được định luật Boyle.","answer":false}],"explanation":"Bổ sung ý c): pV ≈ 23 bar·cm³ = 23×10⁵×10⁻⁶ = 2,3 J (đổi 1 bar = 10⁵ Pa, 1 cm³ = 10⁻⁶ m³). Áp dụng pV = nRT với T = 23,5 + 273 = 296,5 K: n = 2,3 / (8,31×296,5) ≈ 9,33×10⁻⁴ mol, khác với giá trị 8×10⁻⁴ mol đề nêu → ý c) sai.<br>Phương pháp:<br>Phân tích thí nghiệm.<br>a) đúng<br>+ Trình tự thí nghiệm: Nén (giữ nguyên nhiệt độ) khí trong xilanh; Ghi giá trị thể tích và giá trị áp suất khí;<br>Lặp lại các thao tác<br>b) đúng<br>+ Từ bảng kết quả ta có:<br>Lần 1: p1V1 = 22.1,04 = 22,88<br>Lần 2: p2V2 = 1,14.20 = 22,8<br>Lần 3: p2V3 = 1,29.18 = 23,22<br>Lần 4: p4V4 = 1,43.16 = 22,88<br>Lần 5: p5V5 = 1,64.14 = 22,96<br>$\\begin{aligned}\\end{aligned}\\Rightarrow pV=\\frac{22,88+22,8+23,22+22,88+22,96}{5}=22,948\\approx 23$<br>$\\Rightarrow p=\\frac{23}{V}$  với p đo bằng bar (1bar = 105 Pa); V đo bằng cm3.<br>c) sai<br>+ Lượng khí đã dùng trong thí nghiệm:<br>$pV=nRT\\Rightarrow n=\\frac{pV}{RT}=\\frac{23.10^5.10^{−6}}{8,31.\\left(23,5+273\\right)}=9,33.10^{−4}\\left(mol\\right)$<br>d) sai<br>Thí nghiệm này để kiểm chứng định luật Boyle.","difficultySource":"ai"},"ex":[{"exam":214,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Có thể sử dụng bộ thí nghiệm (hình bên) để tìm hiểu về mối liên hệ giữa áp suất và thể tích của một lượng khí xác định ở nhiệt độ không đổi.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790391254602-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Trình tự thí nghiệm: Nén (giữ nguyên nhiệt độ) khí trong xilanh; Ghi giá trị thể tích và giá trị áp suất khí; Lặp lại các thao tác.","answer":true},{"text":"Với kết quả thu được ở bảng bên, công thức liên hệ áp suất theo thể tích là  $p=\\frac{23}{V}$ ,  $p$  đo bằng bar (1 bar = 105 Pa), V đo bằng cm3.","answer":true},{"text":"Lượng khí đã dùng trong thí nghiệm là 8.10<sup>−4</sup> mol.","answer":false},{"text":"Thí nghiệm này đã chứng minh được định luật Boyle.","answer":false}],"explanation":"Bổ sung ý c): pV ≈ 23 bar·cm³ = 23×10⁵×10⁻⁶ = 2,3 J (đổi 1 bar = 10⁵ Pa, 1 cm³ = 10⁻⁶ m³). Áp dụng pV = nRT với T = 23,5 + 273 = 296,5 K: n = 2,3 / (8,31×296,5) ≈ 9,33×10⁻⁴ mol, khác với giá trị 8×10⁻⁴ mol đề nêu → ý c) sai.<br>Phương pháp:<br>Phân tích thí nghiệm.<br>a) đúng<br>+ Trình tự thí nghiệm: Nén (giữ nguyên nhiệt độ) khí trong xilanh; Ghi giá trị thể tích và giá trị áp suất khí;<br>Lặp lại các thao tác<br>b) đúng<br>+ Từ bảng kết quả ta có:<br>Lần 1: p1V1 = 22.1,04 = 22,88<br>Lần 2: p2V2 = 1,14.20 = 22,8<br>Lần 3: p2V3 = 1,29.18 = 23,22<br>Lần 4: p4V4 = 1,43.16 = 22,88<br>Lần 5: p5V5 = 1,64.14 = 22,96<br>$\\begin{aligned}\\end{aligned}\\Rightarrow pV=\\frac{22,88+22,8+23,22+22,88+22,96}{5}=22,948\\approx 23$<br>$\\Rightarrow p=\\frac{23}{V}$  với p đo bằng bar (1bar = 105 Pa); V đo bằng cm3.<br>c) sai<br>+ Lượng khí đã dùng trong thí nghiệm:<br>$pV=nRT\\Rightarrow n=\\frac{pV}{RT}=\\frac{23.10^5.10^{−6}}{8,31.\\left(23,5+273\\right)}=9,33.10^{−4}\\left(mol\\right)$<br>d) sai<br>Thí nghiệm này để kiểm chứng định luật Boyle.","difficultySource":"ai"}}]},{"id":457455,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":0,"options":["150 mm.","55,5 mm .","37,5 mm.","75 mm."],"question":"Uranium trong tự nhiên có 2 đồng vị chính là   ${}_{92}^{235}U$ và   ${}_{92}^{238}U$ . Trong đó  ${}_{92}^{235}U$ chiếm một phần rất nhỏ nhưng lại là nhiên liệu của các nhà máy điện hạt nhân. Một trong những cách làm giàu   ${}_{92}^{235}U$ mà các nhà khoa học sử dụng là tách   ${}_{92}^{235}U$ ra khỏi   ${}_{92}^{238}U$ như sau: cho các ion chứa hạt nhân là   ${}_{92}^{235}U$ và   ${}_{92}^{238}U$  (có cùng điện tích q = 1,6.10<sup>−19</sup>C) tăng tốc đến cùng tốc độ v = 3.10<sup>5</sup> m/s , sau đó cho chúng chuyển động vào từ trường có cảm ứng từ B = 125mT theo phương vuông góc với đường sức từ. Khi đó, lực từ tác dụng lên các ion có độ lớn F = Bv|q|, có phương vuông góc với vận tốc của các ion làm chúng chuyển động theo những nửa đường tròn có bán kính khác nhau và được thu bởi các đầu dò như hình bên. Bỏ qua tác dụng của trọng lực. Biết các ion chứa hạt nhân   ${}_{92}^{235}U$ và   ${}_{92}^{238}U$ có khối lượng lần lượt là 3,9.10<sup>−25</sup> kg và 3,95.10<sup>−25</sup> kg . Khoảng cách giữa các đầu dò là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259812813-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Chọn đáp án A<br>Lực từ F đóng vai trò là lực hướng tâm  $\\Rightarrow F=ma_{ht}\\Rightarrow qBv=m.\\frac{v^2}{R}\\Rightarrow R=\\frac{mv}{qB}$<br>$d=2\\left(R_2−R_1\\right)=\\frac{2\\left(m_2−m_1\\right)v}{qB}=\\frac{2.\\left(3,95−3,9\\right).10^{−25}.3.10^5}{1,6.10^{−19}.0,125}=0,15m=150\\left(mm\\right)$","difficultySource":"ai"},"ex":[{"exam":147,"idx":17,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":0,"options":["150 mm.","55,5 mm .","37,5 mm.","75 mm."],"question":"Uranium trong tự nhiên có 2 đồng vị chính là   ${}_{92}^{235}U$ và   ${}_{92}^{238}U$ . Trong đó  ${}_{92}^{235}U$ chiếm một phần rất nhỏ nhưng lại là nhiên liệu của các nhà máy điện hạt nhân. Một trong những cách làm giàu   ${}_{92}^{235}U$ mà các nhà khoa học sử dụng là tách   ${}_{92}^{235}U$ ra khỏi   ${}_{92}^{238}U$ như sau: cho các ion chứa hạt nhân là   ${}_{92}^{235}U$ và   ${}_{92}^{238}U$  (có cùng điện tích q = 1,6.10<sup>−19</sup>C) tăng tốc đến cùng tốc độ v = 3.10<sup>5</sup> m/s , sau đó cho chúng chuyển động vào từ trường có cảm ứng từ B = 125mT theo phương vuông góc với đường sức từ. Khi đó, lực từ tác dụng lên các ion có độ lớn F = Bv|q|, có phương vuông góc với vận tốc của các ion làm chúng chuyển động theo những nửa đường tròn có bán kính khác nhau và được thu bởi các đầu dò như hình bên. Bỏ qua tác dụng của trọng lực. Biết các ion chứa hạt nhân   ${}_{92}^{235}U$ và   ${}_{92}^{238}U$ có khối lượng lần lượt là 3,9.10<sup>−25</sup> kg và 3,95.10<sup>−25</sup> kg . Khoảng cách giữa các đầu dò là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259812813-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Chọn đáp án A<br>Lực từ F đóng vai trò là lực hướng tâm  $\\Rightarrow F=ma_{ht}\\Rightarrow qBv=m.\\frac{v^2}{R}\\Rightarrow R=\\frac{mv}{qB}$<br>$d=2\\left(R_2−R_1\\right)=\\frac{2\\left(m_2−m_1\\right)v}{qB}=\\frac{2.\\left(3,95−3,9\\right).10^{−25}.3.10^5}{1,6.10^{−19}.0,125}=0,15m=150\\left(mm\\right)$","difficultySource":"ai"}}]},{"id":457579,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":"19","question":"Khi khung dây quay thì xuất hiện suất điện động cảm ứng gọi là suất phản điện. Biết khung gồm 20,0 vòng dây. Lấy π = 3,14 . Khi tốc độ quay của khung là 6,0 vòng/s thì suất phản điện có giá trị hiệu dụng là bao nhiêu Vôn (làm tròn kết quả đến chữ số hàng phần đơn vị)? Sử dụng các thông tin sau cho Câu 3 và Câu 4. Chất rắn Sodium azide (NaN3) được sử dụng trong túi khí ô tô như một nguồn cung cấp khí Nitơ để bơm căng túi khí nhanh chóng khi xảy ra va chạm. Khi ô tô va chạm mạnh vào vật cản, cảm biến va chạm sẽ kích hoạt làm chất rắn này phân hủy tạo ra khí N2 theo phương trình 2NaN3 → 2Na + N3. Khí N2 làm túi khí phồng lên, giúp người lái xe không va chạm trực tiếp với hệ thống lái. Trong một đợt thử nghiệm, thể tích túi khí khi có và không có người đè lên lần lượt là 64 lít và 67 lít. Biết nhiệt độ túi khí là 30°C không đổi. Hằng số Bolzmann k = 1,38.10<sup>−23</sup> J/K. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259925901-hinh-18.jpg\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Diện tích của khung dây chữ nhật là:<br>S = AB.BC = 0,3.0,2 = 0,06m2<br>Tốc độ góc của khung dây là:<br>ω = 2πf = 2.3,14.6 = 37,68rad / s<br>Suất phản điện (suất điện động cảm ứng) cực đại là:<br>E0 = NBS = 20.0,6.0,06.37,68 = 27,1296 V<br>Giá trị hiệu dụng của suất phản điện là:<br>$E=\\frac{E_0}{\\sqrt2}=\\frac{27,1296}{\\sqrt2}\\approx 19V$","difficultySource":"ai"},"ex":[{"exam":158,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":"19","question":"Khi khung dây quay thì xuất hiện suất điện động cảm ứng gọi là suất phản điện. Biết khung gồm 20,0 vòng dây. Lấy π = 3,14 . Khi tốc độ quay của khung là 6,0 vòng/s thì suất phản điện có giá trị hiệu dụng là bao nhiêu Vôn (làm tròn kết quả đến chữ số hàng phần đơn vị)? Sử dụng các thông tin sau cho Câu 3 và Câu 4. Chất rắn Sodium azide (NaN3) được sử dụng trong túi khí ô tô như một nguồn cung cấp khí Nitơ để bơm căng túi khí nhanh chóng khi xảy ra va chạm. Khi ô tô va chạm mạnh vào vật cản, cảm biến va chạm sẽ kích hoạt làm chất rắn này phân hủy tạo ra khí N2 theo phương trình 2NaN3 → 2Na + N3. Khí N2 làm túi khí phồng lên, giúp người lái xe không va chạm trực tiếp với hệ thống lái. Trong một đợt thử nghiệm, thể tích túi khí khi có và không có người đè lên lần lượt là 64 lít và 67 lít. Biết nhiệt độ túi khí là 30°C không đổi. Hằng số Bolzmann k = 1,38.10<sup>−23</sup> J/K. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259925901-hinh-18.jpg\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Diện tích của khung dây chữ nhật là:<br>S = AB.BC = 0,3.0,2 = 0,06m2<br>Tốc độ góc của khung dây là:<br>ω = 2πf = 2.3,14.6 = 37,68rad / s<br>Suất phản điện (suất điện động cảm ứng) cực đại là:<br>E0 = NBS = 20.0,6.0,06.37,68 = 27,1296 V<br>Giá trị hiệu dụng của suất phản điện là:<br>$E=\\frac{E_0}{\\sqrt2}=\\frac{27,1296}{\\sqrt2}\\approx 19V$","difficultySource":"ai"}}]},{"id":457714,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Một bộ thiết bị bao gồm một sợi dây dẫn điện đồng chất, tiết diện đều, một nam châm, một chiếc cân, một bộ nguồn điện có suất điện động không đổi (có gắn sẵn các đầu và một công tắc điện K điện trở không đáng kể). Sợi dây có tiết diện S = 3,5.10<sup>−9</sup> m2, chiều dài L = 72,0 cm và điện trở được xác định bằng công thức R = 1,7.10<sup>−8</sup> $\\frac{L}{S}$ , trong do L tính bằng m, S tính bằng m2 và R tính bằng Ω. Bộ nguồn điện có suất điện động E = 12,0 V và điện trở trong r = 0,5 Ω. Nối sợi dây vào bộ nguồn điện qua công tắc K. Để xác định cảm ứng từ giữa hai cực của nam châm, một học sinh đã uốn sợi dây dẫn điện thành khung dây và bố trí thí nghiệm như hình vẽ bên (khung dây được giữ bởi hai chốt A, B). Biết phần nằm ngang của sợi dây nằm giữa hai cực nam châm có chiều dài là 10,0 cm. Khi bật công tắc cho dòng điện chạy trong mạch điện thì thấy số chỉ của cân thay đổi 4,0 g. Lấy gia tốc trọng trường g = 9,8 $m/s^2$. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260143556-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Điện trở của sợi dây dẫn là 3,5 Ω (làm tròn kết quả đến chữ số hàng phần mười).","answer":true},{"text":"Khi bật công tắc K để dòng diện chạy trong sợi dây dẫn điện thì cường độ dòng điện chạy trong mạch điện là 3 V.","answer":false},{"text":"Lực từ tác dụng vào đoạn dây dẫn nằm giữa hai cực nam châm hướng thẳng đứng lên trên.","answer":false},{"text":"Độ lớn cảm ứng từ giữa hai cực của nam châm xác định được từ thí nghiệm trên là 98 mT","answer":false}],"explanation":"a) đúng<br>$R=1,7.10^{−8}.\\frac{0,72}{3,5.10^{−9}}=3,5\\left(\\Omega \\right)$<br>b) sai<br>$I=\\frac{E}{R+r}=\\frac{12}{3,5+0,5}=3A$  (sai đơn vị)<br>c) sai<br>Áp dụng quy tắc bàn tay trái, chiều lực từ hướng xuống<br>d) sai<br>$F=BIL=\\Delta mg\\Rightarrow B=\\frac{\\Delta mg}{IL}=\\frac{4.10^{−3}.10}{3.0,1}=0,133T$","difficultySource":"ai"},"ex":[{"exam":189,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Một bộ thiết bị bao gồm một sợi dây dẫn điện đồng chất, tiết diện đều, một nam châm, một chiếc cân, một bộ nguồn điện có suất điện động không đổi (có gắn sẵn các đầu và một công tắc điện K điện trở không đáng kể). Sợi dây có tiết diện S = 3,5.10<sup>−9</sup> m2, chiều dài L = 72,0 cm và điện trở được xác định bằng công thức R = 1,7.10<sup>−8</sup> $\\frac{L}{S}$ , trong do L tính bằng m, S tính bằng m2 và R tính bằng Ω. Bộ nguồn điện có suất điện động E = 12,0 V và điện trở trong r = 0,5 Ω. Nối sợi dây vào bộ nguồn điện qua công tắc K. Để xác định cảm ứng từ giữa hai cực của nam châm, một học sinh đã uốn sợi dây dẫn điện thành khung dây và bố trí thí nghiệm như hình vẽ bên (khung dây được giữ bởi hai chốt A, B). Biết phần nằm ngang của sợi dây nằm giữa hai cực nam châm có chiều dài là 10,0 cm. Khi bật công tắc cho dòng điện chạy trong mạch điện thì thấy số chỉ của cân thay đổi 4,0 g. Lấy gia tốc trọng trường g = 9,8 m/s2. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260143556-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Điện trở của sợi dây dẫn là 3,5 Ω (làm tròn kết quả đến chữ số hàng phần mười).","answer":true},{"text":"Khi bật công tắc K để dòng diện chạy trong sợi dây dẫn điện thì cường độ dòng điện chạy trong mạch điện là 3 V.","answer":false},{"text":"Lực từ tác dụng vào đoạn dây dẫn nằm giữa hai cực nam châm hướng thẳng đứng lên trên.","answer":false},{"text":"Độ lớn cảm ứng từ giữa hai cực của nam châm xác định được từ thí nghiệm trên là 98 mT","answer":false}],"explanation":"a) đúng<br>$R=1,7.10^{−8}.\\frac{0,72}{3,5.10^{−9}}=3,5\\left(\\Omega \\right)$<br>b) sai<br>$I=\\frac{E}{R+r}=\\frac{12}{3,5+0,5}=3A$  (sai đơn vị)<br>c) sai<br>Áp dụng quy tắc bàn tay trái, chiều lực từ hướng xuống<br>d) sai<br>$F=BIL=\\Delta mg\\Rightarrow B=\\frac{\\Delta mg}{IL}=\\frac{4.10^{−3}.10}{3.0,1}=0,133T$","difficultySource":"ai"}}]},{"id":457717,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính nhiệt lượng theo nhiệt dung riêng","question":"Một bạn học sinh dùng một ấm điện có thông số như hình 1 để đun 1,2 lít nước ở nhiệt độ phòng. Ấm được nối với nguồn điện xoay chiều có điện áp 220 V − 50 Hz. Học sinh này dùng nhiệt kế và đồng hồ để nghiên cứu sự thay đổi nhiệt độ của nước theo thời gian và thu được đồ thị như hình 2. Biết nhiệt dung riêng của nước là 4200 J/(kg.K); nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> J/kg; khối lượng riêng của nước là 1,0 kg/lít. Vỏ ấm làm bằng inox có khối lượng 800 g và nhiệt dung riêng là 500 J/(kg.K). Cho rằng tỉ lệ nhiệt lượng tỏa ra môi trường so với điện năng tiêu thụ là không đổi trong quá trình đun nước. Biết ấm điện chỉ ngắt điện khi cạn nước. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260144921-hinh-19.jpg\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260145350-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt độ phòng là 298 K.","answer":true},{"text":"Nhiệt lượng nước thu vào để tăng đến nhiệt độ sôi là 3,87.10<sup>5</sup> J.","answer":false},{"text":"Trong quá trình đun cho đến khi nước bắt đầu sôi thì hiệu suất làm nóng nước là 92%.","answer":false},{"text":"Kể từ khi nước bắt đầu sôi, nếu tiếp tục đun nước thì sau khoảng thời gian 1,8 giờ ấm sẽ tự ngắt điện.","answer":false}],"explanation":"a) đúng<br>$T=t+273=25+273=298K$<br>b) sai<br>$m_n=D.V=1,0.1,2=1,2kg$<br>$Q_1=m_nc_n\\Delta T=1,2.4200.\\left(100−25\\right)=378000J=3,78.10^5J$<br>c) sai<br>$A_1=P_1t_1=1850.240=444000J$<br>$H=\\frac{Q_1}{A_1}=\\frac{378000}{444000}=0,8513=85,13%$<br>d) sai<br>* Tỉ lệ nhiệt lượng toả ra ngoài môi trường là<br>$\\Delta H_1=1−\\frac{\\left(m_nc_n+m_ic_i\\right)\\Delta T}{A_1}=0,081=8,1%$<br>* Ấm ngắt điện khi cạn nước tức là toàn bộ1,2 kg nước bay hơi hoàn toàn, khi đó:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260145791-hinh-21.png\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" />giờ","difficultySource":"ai"},"ex":[{"exam":189,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Tính nhiệt lượng theo nhiệt dung riêng","question":"Một bạn học sinh dùng một ấm điện có thông số như hình 1 để đun 1,2 lít nước ở nhiệt độ phòng. Ấm được nối với nguồn điện xoay chiều có điện áp 220 V − 50 Hz. Học sinh này dùng nhiệt kế và đồng hồ để nghiên cứu sự thay đổi nhiệt độ của nước theo thời gian và thu được đồ thị như hình 2. Biết nhiệt dung riêng của nước là 4200 J/(kg.K); nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> J/kg; khối lượng riêng của nước là 1,0 kg/lít. Vỏ ấm làm bằng inox có khối lượng 800 g và nhiệt dung riêng là 500 J/(kg.K). Cho rằng tỉ lệ nhiệt lượng tỏa ra môi trường so với điện năng tiêu thụ là không đổi trong quá trình đun nước. Biết ấm điện chỉ ngắt điện khi cạn nước. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260144921-hinh-19.jpg\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260145350-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt độ phòng là 298 K.","answer":true},{"text":"Nhiệt lượng nước thu vào để tăng đến nhiệt độ sôi là 3,87.10<sup>5</sup> J.","answer":false},{"text":"Trong quá trình đun cho đến khi nước bắt đầu sôi thì hiệu suất làm nóng nước là 92%.","answer":false},{"text":"Kể từ khi nước bắt đầu sôi, nếu tiếp tục đun nước thì sau khoảng thời gian 1,8 giờ ấm sẽ tự ngắt điện.","answer":false}],"explanation":"a) đúng<br>$T=t+273=25+273=298K$<br>b) sai<br>$m_n=D.V=1,0.1,2=1,2kg$<br>$Q_1=m_nc_n\\Delta T=1,2.4200.\\left(100−25\\right)=378000J=3,78.10^5J$<br>c) sai<br>$A_1=P_1t_1=1850.240=444000J$<br>$H=\\frac{Q_1}{A_1}=\\frac{378000}{444000}=0,8513=85,13%$<br>d) sai<br>* Tỉ lệ nhiệt lượng toả ra ngoài môi trường là<br>$\\Delta H_1=1−\\frac{\\left(m_nc_n+m_ic_i\\right)\\Delta T}{A_1}=0,081=8,1%$<br>* Ấm ngắt điện khi cạn nước tức là toàn bộ1,2 kg nước bay hơi hoàn toàn, khi đó:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260145791-hinh-21.png\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" />giờ","difficultySource":"ai"}}]},{"id":457767,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Xử lí số liệu thí nghiệm đo nhiệt","answer":0,"options":["3,4.10<sup>5</sup> J/kg.","3,1.10<sup>5</sup> J/kg.","3,6.10<sup>5</sup> J/kg.","3,8.10<sup>5</sup> J/kg."],"question":"Để xác định nhiệt nóng chảy riêng của nước đá, một học sinh đã bố trí thí nghiệm theo sơ đồ như hình vẽ. Các bước tiến hành và kết quả thí nghiệm như sau: − Các cốc A và B được đặt lên cân điện tử tương ứng. − Ban đầu, các phễu lọc không được đặt lên các cốc − Bật máy đun trong bộ thí nghiệm (1). Khi nước nhỏ giọt ra khỏi các phễu lọc với tốc độ đều đặn, các phễu lọc được đặt lên cốc A và cốc B tương ứng và bật đồng hồ bấm giờ. Sơ đồ bố trí thí nghiệm đo nhiệt nóng chảy −  Sau 10 phút, khối lượng nước thu được riêng của nước đá trong cốc A và cốc B được đo bằng cân điện tử tương ứng là m1 = 97,0 g và m2 =12,0 g .Biết máy đun nhúng sử dụng trong thí nghiệm có công suất 48 W. Nhiệt nóng chảy riêng của nước đá được xác định từ thí nghiệm trên bằng <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260038765-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Chọn đáp án A<br>Gọi Q/ là nhiệt lượng của môi trường bên ngoài (môi trường không khí) cung cấp cho hệ.<br>Ta có:  $\\left\\{\\begin{aligned}m_1\\lambda =P.t+Q^/ <br>m_2\\lambda =Q^/\\end{aligned}\\right.\\Rightarrow \\lambda =\\frac{P.t}{m_1−m_2}=\\frac{48.10.60}{\\left(97−12\\right).10^{−3}}\\approx 338824\\approx 3,4.10^5\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":174,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Xử lí số liệu thí nghiệm đo nhiệt","answer":0,"options":["3,4.10<sup>5</sup> J/kg.","3,1.10<sup>5</sup> J/kg.","3,6.10<sup>5</sup> J/kg.","3,8.10<sup>5</sup> J/kg."],"question":"Để xác định nhiệt nóng chảy riêng của nước đá, một học sinh đã bố trí thí nghiệm theo sơ đồ như hình vẽ. Các bước tiến hành và kết quả thí nghiệm như sau: − Các cốc A và B được đặt lên cân điện tử tương ứng. − Ban đầu, các phễu lọc không được đặt lên các cốc − Bật máy đun trong bộ thí nghiệm (1). Khi nước nhỏ giọt ra khỏi các phễu lọc với tốc độ đều đặn, các phễu lọc được đặt lên cốc A và cốc B tương ứng và bật đồng hồ bấm giờ. Sơ đồ bố trí thí nghiệm đo nhiệt nóng chảy −  Sau 10 phút, khối lượng nước thu được riêng của nước đá trong cốc A và cốc B được đo bằng cân điện tử tương ứng là m1 = 97,0 g và m2 =12,0 g .Biết máy đun nhúng sử dụng trong thí nghiệm có công suất 48 W. Nhiệt nóng chảy riêng của nước đá được xác định từ thí nghiệm trên bằng <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260038765-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Chọn đáp án A<br>Gọi Q/ là nhiệt lượng của môi trường bên ngoài (môi trường không khí) cung cấp cho hệ.<br>Ta có:  $\\left\\{\\begin{aligned}m_1\\lambda =P.t+Q^/ <br>m_2\\lambda =Q^/\\end{aligned}\\right.\\Rightarrow \\lambda =\\frac{P.t}{m_1−m_2}=\\frac{48.10.60}{\\left(97−12\\right).10^{−3}}\\approx 338824\\approx 3,4.10^5\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":457772,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một khung dây hình tròn có diện tích 50 cm2 gồm 1000 vòng dây. Khung dây được đặt trong một từ trường đều có vectơ cảm ứng từ B vuông góc với mặt phẳng khung dây và hướng từ sau ra trước (hình vẽ), có độ lớn B = 10-4 T . Cho B tăng đều lên 3.10<sup>−4</sup> T trong thời gian 0,2s. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260039990-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Trong thời gian B tăng, trong khung dây xảy ra hiện tượng cảm ứng điện từ.","answer":true},{"text":"Nhìn vào mặt phẳng hình vẽ, dòng điện cảm ứng có chiều ngược chiều kim đồng hồ.","answer":false},{"text":"Độ lớn độ biến thiên từ thông qua khung dây trong 0,2s trên là 10-3 Wb.","answer":true},{"text":"Độ lớn suất điện động cảm ứng sinh ra trong khung dây trong thời gian B tăng là 5 mV.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Dữ liệu: $S=50\\ cm^2=5\\cdot10^{-3}\\ m^2$, $N=1000$, $B$ tăng từ $10^{-4}$ T lên $3\\cdot10^{-4}$ T nên $\\Delta B=2\\cdot10^{-4}$ T, $\\Delta t=0{,}2$ s.</p><p class=\"text-base leading-relaxed my-2\">a) Đúng. Cảm ứng từ thay đổi làm từ thông qua khung biến thiên, trong khung xuất hiện hiện tượng cảm ứng điện từ.</p><p class=\"text-base leading-relaxed my-2\">b) Sai. $\\vec B$ hướng ra phía người nhìn và đang tăng, theo định luật Lenz từ trường cảm ứng ngược chiều, hướng vào mặt phẳng, nên dòng cảm ứng cùng chiều kim đồng hồ.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. Độ biến thiên từ thông toàn phần qua khung $N$ vòng: $\\Delta\\Phi=N\\Delta B\\,S=1000\\cdot2\\cdot10^{-4}\\cdot5\\cdot10^{-3}=10^{-3}$ Wb.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. $|e|=\\dfrac{\\Delta\\Phi}{\\Delta t}=\\dfrac{10^{-3}}{0{,}2}=5\\cdot10^{-3}$ V $=5$ mV.</p>","difficultySource":"ai"},"ex":[{"exam":174,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một khung dây hình tròn có diện tích 50 cm2 gồm 1000 vòng dây. Khung dây được đặt trong một từ trường đều có vectơ cảm ứng từ B vuông góc với mặt phẳng khung dây và hướng từ sau ra trước (hình vẽ), có độ lớn B = 10-4 T . Cho B tăng đều lên 3.10<sup>−4</sup> T trong thời gian 0,2s. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260039990-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Trong thời gian B tăng, trong khung dây xảy ra hiện tượng cảm ứng điện từ.","answer":true},{"text":"Nhìn vào mặt phẳng hình vẽ, dòng điện cảm ứng có chiều ngược chiều kim đồng hồ.","answer":false},{"text":"Độ lớn độ biến thiên từ thông qua khung dây trong 0,2s trên là 10-3 Wb.","answer":true},{"text":"Độ lớn suất điện động cảm ứng sinh ra trong khung dây trong thời gian B tăng là 5 mV.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":457917,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một ly nước đá đặt trong không khí, sau một thời gian, ta thấy bên ngoài ly xuất hiện các giọt nước nhỏ (gọi là mồ hôi cốc). Biết rằng nhiệt đông đặc riêng của hơi nước trong không khí là L = 2,26.10<sup>6</sup> J/kg và nhiệt nóng chảy riêng của nước đá là λ = 3,34.10<sup>5</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790401121535-hinh-20.jpg\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Sờ vào thành cốc, ta thấy “có nước bám vào thành cốc”. Đây là do nước trong cốc bay hơi rồi bám vào thành cốc.","answer":false},{"text":"Các giọt nước ngưng tụ trên thành ly truyền nhiệt lượng vào trong ly làm nước đá tan nhanh hơn.","answer":true},{"text":"Khi số lượng nước đá trong ly tan hết, sau một khoảng thời gian thì lượng mồ hôi trên ly nước đá giảm.","answer":true},{"text":"Cốc thủy tinh chứa nước và 250 gam nước đá ở 0 (0C). Nếu làm ngưng tụ 10 gam hơi nước trên thành thì có khoảng 6,77 gam nước đá trong ly bị tan thành nước. Giả sử không có sự truyền nhiệt nào khác xảy ra.","answer":false}],"explanation":"a) sai<br>Hiện tượng ngưng đọng nước ở những vật lạnh là do trong không khí có hơi nước và khi không khí gặp lạnh nó sẽ truyền nhiệt cho vật lạnh ấy. Khi truyền nhiệt vào vật lạnh hơi nước sẽ ngưng tụ lại, quá trình ngưng tụ là quá trình toả nhiệt <br>b) đúng<br>Vì quá trình ngưng tụ là quá trình toả nhiệt. Khi nước ngưng tụ toả nhiệt vào trong cốc để cốc tan đá nhanh hơn<br>c) đúng<br>Khi đá tan hết rồi nước trong cốc tiếp tục tăng nhiệt độ đến khi bằng với nhiệt độ môi trường → lúc đó sẽ không ngưng tụ nước nữa, nước trên thành cốc sẽ bay hơi dần, gọt mồ hôi sẽ ít đi<br>d) sai<br>Nhiệt lượng do 10 g hơi nước ngưng tụ tỏa ra: Q = m·L = 0,010 × 2,26×10⁶ = 22600 J. Nhiệt lượng này làm tan đá: m' = Q/λ = 22600 / (3,34×10⁵) ≈ 0,0677 kg = 67,7 g (không phải 6,77 g như đề nêu) → phát biểu sai.<br>$m_d\\lambda =m.L$<br>$\\Rightarrow m_d.3,34.10^5=10.10^{−3}.2,26.10^6$<br>$\\Rightarrow m_d=0,06766\\left(kg\\right)=67,66g$","difficultySource":"ai"},"ex":[{"exam":215,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một ly nước đá đặt trong không khí, sau một thời gian, ta thấy bên ngoài ly xuất hiện các giọt nước nhỏ (gọi là mồ hôi cốc). Biết rằng nhiệt đông đặc riêng của hơi nước trong không khí là L = 2,26.10<sup>6</sup> J/kg và nhiệt nóng chảy riêng của nước đá là λ = 3,34.10<sup>5</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790401121535-hinh-20.jpg\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Sờ vào thành cốc, ta thấy “có nước bám vào thành cốc”. Đây là do nước trong cốc bay hơi rồi bám vào thành cốc.","answer":false},{"text":"Các giọt nước ngưng tụ trên thành ly truyền nhiệt lượng vào trong ly làm nước đá tan nhanh hơn.","answer":true},{"text":"Khi số lượng nước đá trong ly tan hết, sau một khoảng thời gian thì lượng mồ hôi trên ly nước đá giảm.","answer":true},{"text":"Cốc thủy tinh chứa nước và 250 gam nước đá ở 0 (0C). Nếu làm ngưng tụ 10 gam hơi nước trên thành thì có khoảng 6,77 gam nước đá trong ly bị tan thành nước. Giả sử không có sự truyền nhiệt nào khác xảy ra.","answer":false}],"explanation":"a) sai<br>Hiện tượng ngưng đọng nước ở những vật lạnh là do trong không khí có hơi nước và khi không khí gặp lạnh nó sẽ truyền nhiệt cho vật lạnh ấy. Khi truyền nhiệt vào vật lạnh hơi nước sẽ ngưng tụ lại, quá trình ngưng tụ là quá trình toả nhiệt <br>b) đúng<br>Vì quá trình ngưng tụ là quá trình toả nhiệt. Khi nước ngưng tụ toả nhiệt vào trong cốc để cốc tan đá nhanh hơn<br>c) đúng<br>Khi đá tan hết rồi nước trong cốc tiếp tục tăng nhiệt độ đến khi bằng với nhiệt độ môi trường → lúc đó sẽ không ngưng tụ nước nữa, nước trên thành cốc sẽ bay hơi dần, gọt mồ hôi sẽ ít đi<br>d) sai<br>Nhiệt lượng do 10 g hơi nước ngưng tụ tỏa ra: Q = m·L = 0,010 × 2,26×10⁶ = 22600 J. Nhiệt lượng này làm tan đá: m' = Q/λ = 22600 / (3,34×10⁵) ≈ 0,0677 kg = 67,7 g (không phải 6,77 g như đề nêu) → phát biểu sai.<br>$m_d\\lambda =m.L$<br>$\\Rightarrow m_d.3,34.10^5=10.10^{−3}.2,26.10^6$<br>$\\Rightarrow m_d=0,06766\\left(kg\\right)=67,66g$","difficultySource":"ai"}}]},{"id":457920,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Bơm tay xe đạp hoạt động nhờ pít-tông và van một chiều. Khi kéo lên, van đầu vào mở, hút không khí (có thể coi là khí lý tưởng) vào ống. Khi đẩy xuống, không khí bị nén, van đầu ra mở, đẩy khí vào lốp. Quá trình lặp lại đến khi đạt áp suất mong muốn.  Giả sử ống bơm có dạng hình trụ thành mỏng, cách nhiệt, với bán kính đáy r và chiều cao 50 cm. Khi tay bơm lên cao nhất,<br>áp suất khí bên trong ống là 105 Pa, nhiệt độ 270C. Khi pit-tông di chuyển xuống một đoạn 35 cm, van đầu ra mở, lúc này nhiệt độ của khí trong ống là 450C. Coi quá trình trong xi-lanh là đẳng nhiệt và bỏ qua kích thước của van và pit-tông, lấy T(K) = t0C + 273.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790401124679-hinh-26.jpg\" alt=\"Hình 26\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Van đầu vào mở khi kéo pít-tông lên là do áp suất khí quyển lớn hơn áp suất bên trong ống bơm.","answer":true},{"text":"Ta có thể bơm cho khí trong lốp xe đạt áp suất cao tùy thích.","answer":false},{"text":"Quá trình nén pít-tông xuống sẽ làm tăng áp suất khí trong ống bơm.","answer":true},{"text":"Áp suất của khối khí khi van đầu ra mở bằng 3,2.10<sup>5</sup> Pa","answer":false}],"explanation":"Khi pistog được kéo lên  $V↑;p↓$  ; áp suất giảm đến khỉ nhỏ hơn áp suất khí quyển  $p_0$ . Áp suất khí quyển sẽ đẩy khí vào khí sẽ lọt vào trong  $\\Rightarrow$  Van đóng<br>Khi pistog được đẩy xuống  $V↓;p↑$  khi đó  $p>p_0$  van sẽ bị đóng lại<br>a) đúng<br>Van đầu vào mở khi kéo pít-tông lên là do áp suất khí quyển lớn hơn áp suất bên trong ống bơm.<br>b) sai<br>Chỉ đạt đến 1 áp suất giới hạn, khi áp suất quá lớn không đẩy khí lên được nữa (không sẽ bị nổ)<br>c) đúng<br>Quá trình nén pít-tông xuống sẽ làm tăng áp suất khí trong ống bơm.<br>d) sai<br>van đầu ra mở → piston đi xuống 35cm<br>$\\left\\{\\begin{aligned}V_0=S.50;T_0=\\left(27+273\\right);p_0=10^5Pa <br>V_s=S.\\left(50−35\\right)=S.15;T_S=\\left(45+273\\right);p_s=?\\end{aligned}\\right.$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790401125366-hinh-27.jpg\" alt=\"Hình 27\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":215,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Bơm tay xe đạp hoạt động nhờ pít-tông và van một chiều. Khi kéo lên, van đầu vào mở, hút không khí (có thể coi là khí lý tưởng) vào ống. Khi đẩy xuống, không khí bị nén, van đầu ra mở, đẩy khí vào lốp. Quá trình lặp lại đến khi đạt áp suất mong muốn.  Giả sử ống bơm có dạng hình trụ thành mỏng, cách nhiệt, với bán kính đáy r và chiều cao 50 cm. Khi tay bơm lên cao nhất,<br>áp suất khí bên trong ống là 105 Pa, nhiệt độ 270C. Khi pit-tông di chuyển xuống một đoạn 35 cm, van đầu ra mở, lúc này nhiệt độ của khí trong ống là 450C. Coi quá trình trong xi-lanh là đẳng nhiệt và bỏ qua kích thước của van và pit-tông, lấy T(K) = t0C + 273.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790401124679-hinh-26.jpg\" alt=\"Hình 26\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Van đầu vào mở khi kéo pít-tông lên là do áp suất khí quyển lớn hơn áp suất bên trong ống bơm.","answer":true},{"text":"Ta có thể bơm cho khí trong lốp xe đạt áp suất cao tùy thích.","answer":false},{"text":"Quá trình nén pít-tông xuống sẽ làm tăng áp suất khí trong ống bơm.","answer":true},{"text":"Áp suất của khối khí khi van đầu ra mở bằng 3,2.10<sup>5</sup> Pa","answer":false}],"explanation":"Khi pistog được kéo lên  $V↑;p↓$  ; áp suất giảm đến khỉ nhỏ hơn áp suất khí quyển  $p_0$ . Áp suất khí quyển sẽ đẩy khí vào khí sẽ lọt vào trong  $\\Rightarrow$  Van đóng<br>Khi pistog được đẩy xuống  $V↓;p↑$  khi đó  $p>p_0$  van sẽ bị đóng lại<br>a) đúng<br>Van đầu vào mở khi kéo pít-tông lên là do áp suất khí quyển lớn hơn áp suất bên trong ống bơm.<br>b) sai<br>Chỉ đạt đến 1 áp suất giới hạn, khi áp suất quá lớn không đẩy khí lên được nữa (không sẽ bị nổ)<br>c) đúng<br>Quá trình nén pít-tông xuống sẽ làm tăng áp suất khí trong ống bơm.<br>d) sai<br>van đầu ra mở → piston đi xuống 35cm<br>$\\left\\{\\begin{aligned}V_0=S.50;T_0=\\left(27+273\\right);p_0=10^5Pa <br>V_s=S.\\left(50−35\\right)=S.15;T_S=\\left(45+273\\right);p_s=?\\end{aligned}\\right.$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790401125366-hinh-27.jpg\" alt=\"Hình 27\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":457974,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình Clapeyron – Mendeleev","question":"Đồ thị hình bên miêu tả quá trình biến đổi trạng thái của một lượng khí lí tưởng. Trạng thái (1) khối khí có nhiệt độ 270C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790422806659-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối khí tỏa nhiệt trong quá trình biến đổi từ (1) đến (2).","answer":true},{"text":"Áp suất khí ở trạng thái (2) bằng 6 Pa.","answer":false},{"text":"Khối khí có n = 2,4 mol (lấy 2 chữ số có nghĩa).","answer":true},{"text":"Cả chu trình biến đổi (1) → (2) → (3) →(1) khối khí nhận công.","answer":false}],"explanation":"a) đúng<br>(1) → (2) là hypebol  $\\Rightarrow$  Đẳng nhiệt<br>+  $\\left(1\\right)\\rightarrow \\left(2\\right):T=const\\Rightarrow \\Delta T=0$   $\\Rightarrow \\Delta U=0$  (1)<br>+ Từ (1) → (2):  $V↓\\Rightarrow$  Khí nhận công  $\\Rightarrow A>0$  (2)<br>$\\overset{\\left(1\\right);\\left(2\\right)}\\rightarrow\\Delta U=Q+A=0\\Rightarrow Q=−A<0$<br>b) sai<br>Áp suất khí ở trạng thái (2) bằng 6.10<sup>5</sup> Pa (Trên trục toạ độ  $p(10^5)Pa$<br>c) đúng<br>$n=\\frac{p_1V_1}{RT_1}=\\frac{2.10^5.\\left(30.10^{−3}\\right)}{8,31.300}\\approx 2,4\\left(moℓ\\right)$<br>d) sai<br>Chu trình (1) → (2) → (3) →(1) là chiều thuận kim đồng hồ → Chu trình này là chu trình khối khí sinh công (thực hiện công)<br>Ngược lại chu trình (1) → (3) → (2) → (1) ngược kim đồng hồ → Chu trình này là chu trình khối khí nhận công","difficultySource":"ai"},"ex":[{"exam":223,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình Clapeyron – Mendeleev","question":"Đồ thị hình bên miêu tả quá trình biến đổi trạng thái của một lượng khí lí tưởng. Trạng thái (1) khối khí có nhiệt độ 270C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790422806659-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối khí tỏa nhiệt trong quá trình biến đổi từ (1) đến (2).","answer":true},{"text":"Áp suất khí ở trạng thái (2) bằng 6 Pa.","answer":false},{"text":"Khối khí có n = 2,4 mol (lấy 2 chữ số có nghĩa).","answer":true},{"text":"Cả chu trình biến đổi (1) → (2) → (3) →(1) khối khí nhận công.","answer":false}],"explanation":"a) đúng<br>(1) → (2) là hypebol  $\\Rightarrow$  Đẳng nhiệt<br>+  $\\left(1\\right)\\rightarrow \\left(2\\right):T=const\\Rightarrow \\Delta T=0$   $\\Rightarrow \\Delta U=0$  (1)<br>+ Từ (1) → (2):  $V↓\\Rightarrow$  Khí nhận công  $\\Rightarrow A>0$  (2)<br>$\\overset{\\left(1\\right);\\left(2\\right)}\\rightarrow\\Delta U=Q+A=0\\Rightarrow Q=−A<0$<br>b) sai<br>Áp suất khí ở trạng thái (2) bằng 6.10<sup>5</sup> Pa (Trên trục toạ độ  $p(10^5)Pa$<br>c) đúng<br>$n=\\frac{p_1V_1}{RT_1}=\\frac{2.10^5.\\left(30.10^{−3}\\right)}{8,31.300}\\approx 2,4\\left(moℓ\\right)$<br>d) sai<br>Chu trình (1) → (2) → (3) →(1) là chiều thuận kim đồng hồ → Chu trình này là chu trình khối khí sinh công (thực hiện công)<br>Ngược lại chu trình (1) → (3) → (2) → (1) ngược kim đồng hồ → Chu trình này là chu trình khối khí nhận công","difficultySource":"ai"}}]},{"id":458028,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh làm thí nghiệm xác định nhiệt nóng chảy riêng của nước đá với bộ dụng cụ gồm: Nhiệt lượng kế có nắp kín và đáy có lỗ hở, biến áp nguồn, dây nung công suất P = 12 W; cân điện tử; cốc hứng nước; giá đỡ. Bố trí thí nghiệm như hình vẽ, tiến hành và quan sát thí nghiệm qua hai giai đoạn liên tiếp: Giai đoạn 1: Cho khối nước đá đang tan vào nhiệt lượng kế, bật nguồn điện để dây nung nóng lên làm nước đá nóng chảy, cốc hứng nước đặt trên cân điện tử hứng nước chảy ra từ nhiệt lượng kế và quan sát số chỉ của cân. Sau một thời gian kể từ khi cấp điện cho dây nung, tại thời điểm t1, thấy số chỉ của cân là 40 g. Giai đoạn 2: Tiếp tục quan sát thì nhận thấy, sau thời gian 10 phút kế tiếp kể từ thời điểm t1, số chỉ của cân tăng đến 60 g. Coi rằng toàn bộ nhiệt lượng tỏa ra từ dây nung đều truyền cho nước đá và toàn bộ nước đá tan ra đều chảy vào cốc, bỏ qua sự trao đổi nhiệt với nhiệt lượng kế và môi trường, bỏ qua các ảnh hưởng khác (bay hơi, ngưng tụ của nước,...) <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260101560-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Theo phương án thí nghiệm, nhiệt nóng chảy riêng của nước đá ở nhiệt độ nóng chảy là 3,6.10<sup>5</sup> J/kg.","answer":true},{"text":"Quá trình nước đá nóng chảy là quá trình tỏa nhiệt.","answer":false},{"text":"Phương án thí nghiệm này là một trong những phương án có thể loại bỏ ảnh hưởng của sự trao đổi nhiệt với môi trường đến kết quả thí nghiệm.","answer":false},{"text":"Số chỉ của cân là khối lượng của nước đá đã nóng chảy và chảy vào cốc hứng.","answer":false}],"explanation":"a) đúng<br>Giai đoạn 1:  $40g=m_0+m_{coc}$<br>Giai đoạn 2:  $60g=m_0^/+m_{coc}$<br>$\\Rightarrow$  Khối lượng nước đá chảy trong 10 phút:  $m_0^/−m_0=20g$<br>$P.t=12.600=\\frac{20}{1000}.\\lambda \\Rightarrow \\lambda =3,6.10^5\\left(J/kg\\right)$<br>b) sai<br>Nước đá nóng chảy là quá tình thu nhiệt<br>c) sai<br>Nước đá không cần bật dây nung nó có thể tự tan chảy được<br>Phương án thí nghiệm này là một trong những phương án không thể loại bỏ.<br>Phải quan sát giai đoạn 1 để đá tự chảy ra khi nó trao đổi nhiệt với môi trường<br>d) sai<br>Số chỉ của cân bao gồm khối lượng của cốc và khối lượng của phần nước đá đã nóng chảy, chảy vào cốc<br>(Chú ý câu d) này đề bài lừa thí sinh)<br>$\\Rightarrow$  Số chỉ của cân là khối lượng của nước đá đã nóng chảy và chảy vào cốc + mcốc","difficultySource":"ai"},"ex":[{"exam":140,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh làm thí nghiệm xác định nhiệt nóng chảy riêng của nước đá với bộ dụng cụ gồm: Nhiệt lượng kế có nắp kín và đáy có lỗ hở, biến áp nguồn, dây nung công suất P = 12 W; cân điện tử; cốc hứng nước; giá đỡ. Bố trí thí nghiệm như hình vẽ, tiến hành và quan sát thí nghiệm qua hai giai đoạn liên tiếp: Giai đoạn 1: Cho khối nước đá đang tan vào nhiệt lượng kế, bật nguồn điện để dây nung nóng lên làm nước đá nóng chảy, cốc hứng nước đặt trên cân điện tử hứng nước chảy ra từ nhiệt lượng kế và quan sát số chỉ của cân. Sau một thời gian kể từ khi cấp điện cho dây nung, tại thời điểm t1, thấy số chỉ của cân là 40 g. Giai đoạn 2: Tiếp tục quan sát thì nhận thấy, sau thời gian 10 phút kế tiếp kể từ thời điểm t1, số chỉ của cân tăng đến 60 g. Coi rằng toàn bộ nhiệt lượng tỏa ra từ dây nung đều truyền cho nước đá và toàn bộ nước đá tan ra đều chảy vào cốc, bỏ qua sự trao đổi nhiệt với nhiệt lượng kế và môi trường, bỏ qua các ảnh hưởng khác (bay hơi, ngưng tụ của nước,...) <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259747956-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Theo phương án thí nghiệm, nhiệt nóng chảy riêng của nước đá ở nhiệt độ nóng chảy là 3,6.10<sup>5</sup> J/kg.","answer":true},{"text":"Quá trình nước đá nóng chảy là quá trình tỏa nhiệt.","answer":false},{"text":"Phương án thí nghiệm này là một trong những phương án có thể loại bỏ ảnh hưởng của sự trao đổi nhiệt với môi trường đến kết quả thí nghiệm.","answer":false},{"text":"Số chỉ của cân là khối lượng của nước đá đã nóng chảy và chảy vào cốc hứng.","answer":false}],"explanation":"a) đúng<br>Giai đoạn 1:  $40g=m_0+m_{coc}$<br>Giai đoạn 2:  $60g=m_0^/+m_{coc}$<br>$\\Rightarrow$  Khối lượng nước đá chảy trong 10 phút:  $m_0^/−m_0=20g$<br>$P.t=12.600=\\frac{20}{1000}.\\lambda \\Rightarrow \\lambda =3,6.10^5\\left(J/kg\\right)$<br>b) sai<br>Nước đá nóng chảy là quá tình thu nhiệt<br>c) sai<br>Nước đá không cần bật dây nung nó có thể tự tan chảy được<br>Phương án thí nghiệm này là một trong những phương án không thể loại bỏ.<br>Phải quan sát giai đoạn 1 để đá tự chảy ra khi nó trao đổi nhiệt với môi trường<br>d) sai<br>Số chỉ của cân bao gồm khối lượng của cốc và khối lượng của phần nước đá đã nóng chảy, chảy vào cốc<br>(Chú ý câu d) này đề bài lừa thí sinh)<br>$\\Rightarrow$  Số chỉ của cân là khối lượng của nước đá đã nóng chảy và chảy vào cốc + mcốc","difficultySource":"ai"}},{"exam":182,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh làm thí nghiệm xác định nhiệt nóng chảy riêng của nước đá với bộ dụng cụ gồm: Nhiệt lượng kế có nắp kín và đáy có lỗ hở, biến áp nguồn, dây nung công suất P = 12 W; cân điện tử; cốc hứng nước; giá đỡ. Bố trí thí nghiệm như hình vẽ, tiến hành và quan sát thí nghiệm qua hai giai đoạn liên tiếp: Giai đoạn 1: Cho khối nước đá đang tan vào nhiệt lượng kế, bật nguồn điện để dây nung nóng lên làm nước đá nóng chảy, cốc hứng nước đặt trên cân điện tử hứng nước chảy ra từ nhiệt lượng kế và quan sát số chỉ của cân. Sau một thời gian kể từ khi cấp điện cho dây nung, tại thời điểm t1, thấy số chỉ của cân là 40 g. Giai đoạn 2: Tiếp tục quan sát thì nhận thấy, sau thời gian 10 phút kế tiếp kể từ thời điểm t1, số chỉ của cân tăng đến 60 g. Coi rằng toàn bộ nhiệt lượng tỏa ra từ dây nung đều truyền cho nước đá và toàn bộ nước đá tan ra đều chảy vào cốc, bỏ qua sự trao đổi nhiệt với nhiệt lượng kế và môi trường, bỏ qua các ảnh hưởng khác (bay hơi, ngưng tụ của nước,...) <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260101560-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Theo phương án thí nghiệm, nhiệt nóng chảy riêng của nước đá ở nhiệt độ nóng chảy là 3,6.10<sup>5</sup> J/kg.","answer":true},{"text":"Quá trình nước đá nóng chảy là quá trình tỏa nhiệt.","answer":false},{"text":"Phương án thí nghiệm này là một trong những phương án có thể loại bỏ ảnh hưởng của sự trao đổi nhiệt với môi trường đến kết quả thí nghiệm.","answer":false},{"text":"Số chỉ của cân là khối lượng của nước đá đã nóng chảy và chảy vào cốc hứng.","answer":false}],"explanation":"a) đúng<br>Giai đoạn 1:  $40g=m_0+m_{coc}$<br>Giai đoạn 2:  $60g=m_0^/+m_{coc}$<br>$\\Rightarrow$  Khối lượng nước đá chảy trong 10 phút:  $m_0^/−m_0=20g$<br>$P.t=12.600=\\frac{20}{1000}.\\lambda \\Rightarrow \\lambda =3,6.10^5\\left(J/kg\\right)$<br>b) sai<br>Nước đá nóng chảy là quá tình thu nhiệt<br>c) sai<br>Nước đá không cần bật dây nung nó có thể tự tan chảy được<br>Phương án thí nghiệm này là một trong những phương án không thể loại bỏ.<br>Phải quan sát giai đoạn 1 để đá tự chảy ra khi nó trao đổi nhiệt với môi trường<br>d) sai<br>Số chỉ của cân bao gồm khối lượng của cốc và khối lượng của phần nước đá đã nóng chảy, chảy vào cốc<br>(Chú ý câu d) này đề bài lừa thí sinh)<br>$\\Rightarrow$  Số chỉ của cân là khối lượng của nước đá đã nóng chảy và chảy vào cốc + mcốc","difficultySource":"ai"}}]},{"id":458086,"nq":{"form":"bai_tap","type":"true_false","topic":"Mol, số Avogadro và lượng chất khí","question":"Để khảo sát mối liên hệ giữa áp suất và nhiệt độ của một lượng khí xác định, một nhóm học sinh tiến hành thí nghiệm bố trí như hình bên. Đối tượng khảo sát là một quả cầu kim loại chứa không khí, được nhúng ngập hoàn toàn trong bình chứa nước. Quả cầu khí được nối với một khí áp kế để đo áp suất, đồng thời có gắn một van (nằm che khuất sau khí áp kế) có thể đóng – mở nhằm kết nối hoặc cô lập khí trong quả cầu với khí quyển bên ngoài. Nhiệt độ của hệ được theo dõi bằng nhiệt nguồn nhiệt (bếp điện), nhiệt độ của khí trong quả cầu được điều khiển thông qua quá trình cân bằng nhiệt. Trong suốt quá trình thí nghiệm, bỏ qua sự co giãn không đáng kể của bình khí. Ban đầu, mở van để khí trong bình cân bằng áp suất với khí quyển, sau đó đóng van để cô lập khối khí trong bình. Ghi lại các giá trị nhiệt độ và áp suất ban đầu của khí vào bảng số liệu (nhiệt độ của khí được xác định theo nhiệt độ của nước trong bình). Tiếp theo, bật bếp điện và điều chỉnh công suất ở mức phù hợp để nhiệt độ của nước tăng chậm; đồng thời thường xuyên khuấy nước để đảm bảo nhiệt độ nước trong bình đồng đều, giúp khí trong quả cầu nhanh đạt cân bằng nhiệt với nước. Cứ mỗi khi nhiệt độ tăng thêm 10°C, nhóm học sinh tiến hành ghi lại đồng thời nhiệt độ và áp suất tương ứng của khí vào bảng số liệu. Kết quả thí nghiệm được trình bày trong bảng sau: Nhiệt độ t (°C)\t25,0\t35,0\t45,0\t55,0\t65,0 Áp suất p (105 Pa)\t1,01\t1,04\t1,08\t1,11\t1,15 <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259972129-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quả cầu chứa khí được làm bằng kim loại và nhúng ngập hoàn toàn trong nước nhằm tăng cường trao đổi nhiệt, giúp khí bên trong quả cầu nhanh chóng đạt cân bằng nhiệt với nước, qua đó giảm sai số trong phép đo.","answer":true},{"text":"Áp suất khí trong quả cầu tăng tỉ lệ thuận với nhiệt độ.","answer":false},{"text":"Quá trình biến đổi khí trong thí nghiệm là quá trình đẳng tích.","answer":true},{"text":"Mật độ phân tử trung bình của lượng khí đã sử dụng trong thí nghiệm là 2,46.10<sup>25</sup> phân tử/m3.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Quả cầu kín, thể tích gần như không đổi nên quá trình là đẳng tích; định luật Charles: $\\dfrac pT=\\text{hằng số}$ với $T$ là nhiệt độ tuyệt đối.</p><p class=\"text-base leading-relaxed my-2\">a) Đúng. Kim loại dẫn nhiệt tốt và ngập hoàn toàn trong nước nên khí nhanh cân bằng nhiệt với nước, nhiệt độ đo được chính xác hơn.</p><p class=\"text-base leading-relaxed my-2\">b) Sai. Bảng cho $t$ theo độ C: $\\dfrac pt$ không đổi không đúng ($\\dfrac{1{,}01}{25}\\ne\\dfrac{1{,}04}{35}$). Áp suất chỉ tỉ lệ thuận với nhiệt độ tuyệt đối $T$ (K), không tỉ lệ thuận với $t$ (°C).</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. Thể tích khí trong quả cầu không đổi nên là quá trình đẳng tích.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. $n=\\dfrac{p}{kT}=\\dfrac{1{,}01\\cdot10^5}{1{,}38\\cdot10^{-23}\\cdot298}\\approx2{,}46\\cdot10^{25}$ phân tử/m$^3$.</p>","difficultySource":"ai"},"ex":[{"exam":164,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Mol, số Avogadro và lượng chất khí","question":"Để khảo sát mối liên hệ giữa áp suất và nhiệt độ của một lượng khí xác định, một nhóm học sinh tiến hành thí nghiệm bố trí như hình bên. Đối tượng khảo sát là một quả cầu kim loại chứa không khí, được nhúng ngập hoàn toàn trong bình chứa nước. Quả cầu khí được nối với một khí áp kế để đo áp suất, đồng thời có gắn một van (nằm che khuất sau khí áp kế) có thể đóng – mở nhằm kết nối hoặc cô lập khí trong quả cầu với khí quyển bên ngoài. Nhiệt độ của hệ được theo dõi bằng nhiệt nguồn nhiệt (bếp điện), nhiệt độ của khí trong quả cầu được điều khiển thông qua quá trình cân bằng nhiệt. Trong suốt quá trình thí nghiệm, bỏ qua sự co giãn không đáng kể của bình khí. Ban đầu, mở van để khí trong bình cân bằng áp suất với khí quyển, sau đó đóng van để cô lập khối khí trong bình. Ghi lại các giá trị nhiệt độ và áp suất ban đầu của khí vào bảng số liệu (nhiệt độ của khí được xác định theo nhiệt độ của nước trong bình). Tiếp theo, bật bếp điện và điều chỉnh công suất ở mức phù hợp để nhiệt độ của nước tăng chậm; đồng thời thường xuyên khuấy nước để đảm bảo nhiệt độ nước trong bình đồng đều, giúp khí trong quả cầu nhanh đạt cân bằng nhiệt với nước. Cứ mỗi khi nhiệt độ tăng thêm 10°C, nhóm học sinh tiến hành ghi lại đồng thời nhiệt độ và áp suất tương ứng của khí vào bảng số liệu. Kết quả thí nghiệm được trình bày trong bảng sau: Nhiệt độ t (°C)\t25,0\t35,0\t45,0\t55,0\t65,0 Áp suất p (105 Pa)\t1,01\t1,04\t1,08\t1,11\t1,15 <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259972129-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quả cầu chứa khí được làm bằng kim loại và nhúng ngập hoàn toàn trong nước nhằm tăng cường trao đổi nhiệt, giúp khí bên trong quả cầu nhanh chóng đạt cân bằng nhiệt với nước, qua đó giảm sai số trong phép đo.","answer":true},{"text":"Áp suất khí trong quả cầu tăng tỉ lệ thuận với nhiệt độ.","answer":false},{"text":"Quá trình biến đổi khí trong thí nghiệm là quá trình đẳng tích.","answer":true},{"text":"Mật độ phân tử trung bình của lượng khí đã sử dụng trong thí nghiệm là 2,46.10<sup>25</sup> phân tử/m3.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":458209,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":1,"options":["6,0.10<sup>23</sup>.","3,1.10<sup>23</sup>.","2,9.10<sup>23</sup>.","9,6.10<sup>24</sup>."],"question":"${}_{15}^{31}P$ là một đồng vị phóng xạ của nguyên tố phosphorus. Khối lượng mol nguyên tử của  ${}_{15}^{31}P$  bằng 30,974 g. Mỗi gam chất phosphorus  ${}_{15}^{31}P$  có chứa bao nhiêu neutron (làm tròn và viết kết quả đến hai chữ số có nghĩa)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260019443-hinh-1.jpg\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Chọn đáp án B<br>Ta có:  $n=\\frac{m}{M}=\\frac{1}{30,974}mol$<br>Số nguyên tử là  $N=nN_A=\\frac{1}{30,974}.6,02.10^{23}\\approx 1,944.10^{22}$<br>Số neutron là  $N_n=N\\left(A−Z\\right)=1,944.10^{22}\\left(31−15\\right)\\approx 3,1.10^{23}$","difficultySource":"ai"},"ex":[{"exam":172,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":1,"options":["6,0.10<sup>23</sup>.","3,1.10<sup>23</sup>.","2,9.10<sup>23</sup>.","9,6.10<sup>24</sup>."],"question":"${}_{15}^{31}P$ là một đồng vị phóng xạ của nguyên tố phosphorus. Khối lượng mol nguyên tử của  ${}_{15}^{31}P$  bằng 30,974 g. Mỗi gam chất phosphorus  ${}_{15}^{31}P$  có chứa bao nhiêu neutron (làm tròn và viết kết quả đến hai chữ số có nghĩa)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260019443-hinh-1.jpg\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Chọn đáp án B<br>Ta có:  $n=\\frac{m}{M}=\\frac{1}{30,974}mol$<br>Số nguyên tử là  $N=nN_A=\\frac{1}{30,974}.6,02.10^{23}\\approx 1,944.10^{22}$<br>Số neutron là  $N_n=N\\left(A−Z\\right)=1,944.10^{22}\\left(31−15\\right)\\approx 3,1.10^{23}$","difficultySource":"ai"}}]},{"id":458222,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["62.","72.","41.","13."],"question":"Người ta cần đúc một chuông đồng có khối lượng 300 kg bằng phương pháp nấu chảy đồng và đổ vào khuôn cho đồng ở thể lỏng bị đông đặc. Cho nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kg, nhiệt dung riêng của đồng bằng 380 (J/kg.K). Giả sử xưởng đúc đồng sử dụng 85 kg khí đốt để làm tăng nhiệt độ của 300 kg đồng từ 30°C đến khi nóng chảy hoàn toàn ở 1085°C. Biết rằng, khi đốt cháy hoàn toàn 1 kg khí đốt thì nhiệt lượng toả ra là 5.10<sup>6</sup> J. Hiệu suất để đúc chuông đồng của xưởng đúc này bằng bao nhiêu phần trăm (làm tròn kết quả đến chữ số hàng đơn vị)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260022175-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Chọn đáp án C<br>Nhiệt lượng có ích:  $Q=mc\\Delta t+m\\lambda =300.380.\\left(1085−30\\right)+300.1,8.10^5=174,27.10^6J$<br>Nhiệt lượng do đốt 85 kg khí đốt cung cấp: Qtp = qm = 5.106.85 = 425.106J<br>Hiệu suất:  $H=\\frac{Q}{Q_{tp}}=\\frac{174,27.10^6}{425.10^6}\\approx 0,41−41%$","difficultySource":"ai"},"ex":[{"exam":172,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["62.","72.","41.","13."],"question":"Người ta cần đúc một chuông đồng có khối lượng 300 kg bằng phương pháp nấu chảy đồng và đổ vào khuôn cho đồng ở thể lỏng bị đông đặc. Cho nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kg, nhiệt dung riêng của đồng bằng 380 (J/kg.K). Giả sử xưởng đúc đồng sử dụng 85 kg khí đốt để làm tăng nhiệt độ của 300 kg đồng từ 30°C đến khi nóng chảy hoàn toàn ở 1085°C. Biết rằng, khi đốt cháy hoàn toàn 1 kg khí đốt thì nhiệt lượng toả ra là 5.10<sup>6</sup> J. Hiệu suất để đúc chuông đồng của xưởng đúc này bằng bao nhiêu phần trăm (làm tròn kết quả đến chữ số hàng đơn vị)? <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260022175-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Chọn đáp án C<br>Nhiệt lượng có ích:  $Q=mc\\Delta t+m\\lambda =300.380.\\left(1085−30\\right)+300.1,8.10^5=174,27.10^6J$<br>Nhiệt lượng do đốt 85 kg khí đốt cung cấp: Qtp = qm = 5.106.85 = 425.106J<br>Hiệu suất:  $H=\\frac{Q}{Q_{tp}}=\\frac{174,27.10^6}{425.10^6}\\approx 0,41−41%$","difficultySource":"ai"}}]},{"id":458283,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Để tìm hiểu mối liên hệ giữa áp suất và nhiệt độ của một khối lượng khí xác định khi thể tích không đổi, một nhóm học sinh tiến hành thí nghiệm như sau: Gắn chặt một cảm biến áp suất vào miệng một bình cầu thủy tinh kín có dung tích V0 thông qua một ống nhựa nhỏ. Nhúng chìm phần bình cầu vào một chậu nước, để phần ống nhựa và cảm biến ở ngoài không khí. Sử dụng nhiệt kế để đo nhiệt độ của nước (coi nhiệt độ của khí trong bình cầu bằng nhiệt độ của nước). Tiến hành đun nóng từ từ chậu nước, đợi hệ cân bằng sau mỗi lần đun và ghi lại các giá trị áp suất p tương ứng với nhiệt độ t (°C). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259930415-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong tiến trình thí nghiệm này, nhiệt độ của nước là biến độc lập và áp suất của khối khí là biến phụ thuộc.","answer":true},{"text":"Từ đồ thị thực nghiệm biểu diễn sự phụ thuộc của p theo t (°C), nhóm học sinh có thể rút ra kết luận: Áp suất của lượng khí tỉ lệ thuận với nhiệt độ bách phân (Celsius) của nó.","answer":false},{"text":"Trong thực tế, do phần ống nhựa nằm ngoài chậu nước luôn giữ ở nhiệt độ phòng (không được đun nóng), sai số hệ thống này sẽ làm cho giá trị áp suất đo được ở các nhiệt độ cao luôn lớn hơn so với giá trị lí thuyết (nếu coi toàn bộ lượng khí đều được đun nóng).","answer":false},{"text":"Giả sử ban đầu hệ ở 27°C, áp suất đo được là 1,00×10<sup>5</sup> Pa. Khi đun nước đến 87°C (coi toàn bộ lượng khí được đun nóng đều và bỏ qua qua thể tích ống nhựa), cảm biến chỉ đo được áp suất là 1,15×10<sup>5</sup> Pa. Bỏ qua sự rò rỉ khí, nhóm học sinh suy luận nguyên nhân sự sai lệch này là do bình thủy tinh đã giãn nở nhiệt. Dựa vào số liệu thực nghiệm này, thể tích của bình thủy tinh ở 87°C đã tăng xấp xỉ 4,35% so với ban đầu.","answer":true}],"explanation":"a) đúng<br>Người làm thí nghiệm chủ động thay đổi nhiệt độ bằng cách đun nóng (đây là biến độc lập) để quan sát sự thay đổi tương ứng của áp suất (đây là biến phụ thuộc).<br>b) sai<br>Áp suất của khối khí tỉ lệ thuận với nhiệt độ tuyệt đối T (đơn vị Kelvin), chứ không tỉ lệ thuận với nhiệt độ bách phân $t(^0C)$ . Đồ thị biểu diễn p theo  $t(^0C)$ là một đường thẳng bậc nhất nhưng không đi qua gốc tọa độ.<br>c) sai<br>Giả sử bình có thể tích V1 ở nhiệt độ cao T , phần ống nhựa có thể tích V2 ở nhiệt độ phòng T0 (T0 < T).<br>Áp suất thực tế đo được là pdo, ta có lượng khí bảo toàn:  $n=\\frac{p_{do}V_1}{RT}+\\frac{p_{do}V_2}{RT_0}=\\frac{p_{do}}{R}\\left(\\frac{V_1}{T}+\\frac{V_2}{T_0}\\right)$<br>Nếu toàn bộ khí được đun nóng đến nhiệt độ T , áp suất lí thuyết là plt , ta có:<br>$n=\\frac{p_{lt}\\left(V_1+V_2\\right)}{RT}=\\frac{p_{lt}}{R}\\left(\\frac{V_1}{T}+\\frac{V_2}{T}\\right)$<br>Vì  $T_0<T$  nên  $\\frac{V_2}{T_0}>\\frac{V_2}{T}$ . Từ đó suy ra cụm $\\left(\\frac{V_1}{T}+\\frac{V_2}{T_0}\\right)>\\left(\\frac{V_1}{T}+\\frac{V_2}{T}\\right)$ . Do lượng khí n không đổi, suy ra  $p_{do}<p_{lt}$  . Vậy giá trị đo được phải nhỏ hơn giá trị lí thuyết.<br>d) đúng<br>Trạng thái 1: T1 = 27 + 273 = 300K; p1 = 1,00.10<sup>5</sup> Pa ; thể tích V1.<br>Trạng thái 2: T2 = 87 +  273 = 360K; p2 = 1,15.10<sup>5</sup> Pa ; thể tích V2.<br>Áp dụng phương trình trạng thái khí lí tưởng vì khối lượng lượng khí không đổi:<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}\\Rightarrow V_2=V_1.\\frac{p_1T_2}{p_2T_1}$<br>Thay số:  $V_2=V_1.\\frac{1,00.10^5.360}{1,15.10^5.300}=V_1.\\frac{360}{345}=\\frac{24}{23}V_1\\approx 1,04348V_1$<br>Độ tăng phần trăm của thể tích bình là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259931667-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":159,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Để tìm hiểu mối liên hệ giữa áp suất và nhiệt độ của một khối lượng khí xác định khi thể tích không đổi, một nhóm học sinh tiến hành thí nghiệm như sau: Gắn chặt một cảm biến áp suất vào miệng một bình cầu thủy tinh kín có dung tích V0 thông qua một ống nhựa nhỏ. Nhúng chìm phần bình cầu vào một chậu nước, để phần ống nhựa và cảm biến ở ngoài không khí. Sử dụng nhiệt kế để đo nhiệt độ của nước (coi nhiệt độ của khí trong bình cầu bằng nhiệt độ của nước). Tiến hành đun nóng từ từ chậu nước, đợi hệ cân bằng sau mỗi lần đun và ghi lại các giá trị áp suất p tương ứng với nhiệt độ t (°C). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259930415-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong tiến trình thí nghiệm này, nhiệt độ của nước là biến độc lập và áp suất của khối khí là biến phụ thuộc.","answer":true},{"text":"Từ đồ thị thực nghiệm biểu diễn sự phụ thuộc của p theo t (°C), nhóm học sinh có thể rút ra kết luận: Áp suất của lượng khí tỉ lệ thuận với nhiệt độ bách phân (Celsius) của nó.","answer":false},{"text":"Trong thực tế, do phần ống nhựa nằm ngoài chậu nước luôn giữ ở nhiệt độ phòng (không được đun nóng), sai số hệ thống này sẽ làm cho giá trị áp suất đo được ở các nhiệt độ cao luôn lớn hơn so với giá trị lí thuyết (nếu coi toàn bộ lượng khí đều được đun nóng).","answer":false},{"text":"Giả sử ban đầu hệ ở 27°C, áp suất đo được là 1,00×10<sup>5</sup> Pa. Khi đun nước đến 87°C (coi toàn bộ lượng khí được đun nóng đều và bỏ qua qua thể tích ống nhựa), cảm biến chỉ đo được áp suất là 1,15×10<sup>5</sup> Pa. Bỏ qua sự rò rỉ khí, nhóm học sinh suy luận nguyên nhân sự sai lệch này là do bình thủy tinh đã giãn nở nhiệt. Dựa vào số liệu thực nghiệm này, thể tích của bình thủy tinh ở 87°C đã tăng xấp xỉ 4,35% so với ban đầu.","answer":true}],"explanation":"a) đúng<br>Người làm thí nghiệm chủ động thay đổi nhiệt độ bằng cách đun nóng (đây là biến độc lập) để quan sát sự thay đổi tương ứng của áp suất (đây là biến phụ thuộc).<br>b) sai<br>Áp suất của khối khí tỉ lệ thuận với nhiệt độ tuyệt đối T (đơn vị Kelvin), chứ không tỉ lệ thuận với nhiệt độ bách phân $t(^0C)$ . Đồ thị biểu diễn p theo  $t(^0C)$ là một đường thẳng bậc nhất nhưng không đi qua gốc tọa độ.<br>c) sai<br>Giả sử bình có thể tích V1 ở nhiệt độ cao T , phần ống nhựa có thể tích V2 ở nhiệt độ phòng T0 (T0 < T).<br>Áp suất thực tế đo được là pdo, ta có lượng khí bảo toàn:  $n=\\frac{p_{do}V_1}{RT}+\\frac{p_{do}V_2}{RT_0}=\\frac{p_{do}}{R}\\left(\\frac{V_1}{T}+\\frac{V_2}{T_0}\\right)$<br>Nếu toàn bộ khí được đun nóng đến nhiệt độ T , áp suất lí thuyết là plt , ta có:<br>$n=\\frac{p_{lt}\\left(V_1+V_2\\right)}{RT}=\\frac{p_{lt}}{R}\\left(\\frac{V_1}{T}+\\frac{V_2}{T}\\right)$<br>Vì  $T_0<T$  nên  $\\frac{V_2}{T_0}>\\frac{V_2}{T}$ . Từ đó suy ra cụm $\\left(\\frac{V_1}{T}+\\frac{V_2}{T_0}\\right)>\\left(\\frac{V_1}{T}+\\frac{V_2}{T}\\right)$ . Do lượng khí n không đổi, suy ra  $p_{do}<p_{lt}$  . Vậy giá trị đo được phải nhỏ hơn giá trị lí thuyết.<br>d) đúng<br>Trạng thái 1: T1 = 27 + 273 = 300K; p1 = 1,00.10<sup>5</sup> Pa ; thể tích V1.<br>Trạng thái 2: T2 = 87 +  273 = 360K; p2 = 1,15.10<sup>5</sup> Pa ; thể tích V2.<br>Áp dụng phương trình trạng thái khí lí tưởng vì khối lượng lượng khí không đổi:<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}\\Rightarrow V_2=V_1.\\frac{p_1T_2}{p_2T_1}$<br>Thay số:  $V_2=V_1.\\frac{1,00.10^5.360}{1,15.10^5.300}=V_1.\\frac{360}{345}=\\frac{24}{23}V_1\\approx 1,04348V_1$<br>Độ tăng phần trăm của thể tích bình là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259931667-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":458316,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"2","question":"Một ống dây dẫn hình trụ dài gồm 1000 vòng dây, mỗi vòng có đường kính 10 cm, được đặt trong từ trường có các đường sức từ song song với trục ống dây. Cảm ứng từ của từ trường biến thiên với tốc độ không đổi. Dây dẫn có tiết diện 0,4mm2 và điện trở suất  $\\rho$ = 1,75.10<sup>−8</sup>Wm. Mạch điện gồm tụ điện C = 10mF và khóa chuyển mạch K . Ban đầu khóa K ở vị trí (1), sau khi dòng điện đã ổn định, gọi Q là nhiệt lượng ống dây tỏa ra trong thời gian ∆t = 34,4 µm . Sau đó chuyển khóa K sang vị trí (2), tụ điện được tích điện đến trạng thái ổn định với năng lượng dự trữ là W . Tính thương số W / Q (làm tròn kết quả đến chữ số hàng đơn vị). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259687140-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Đáp số 2<br>Ống dây có  $N=1000$  vòng, mỗi vòng có đường kính  $d=10,cm=0,10,m$ .<br>Chiều dài dây dẫn là  $l=N\\pi d=1000\\cdot 3,14\\cdot 0,10=314,m$ .<br>Tiết diện dây dẫn:  $S_d=0,4,mm^2=4\\cdot 10^{−7},m^2$ .<br>Điện trở của ống dây là  $R=\\rho \\frac{l}{S_d}=1,75\\cdot 10^{−8}\\cdot \\frac{314}{4\\cdot 10^{−7}}\\approx 13,74,\\Omega$ .<br>Khi khóa ở vị trí  $(1)$ , dòng điện cảm ứng ổn định có  $I=\\frac{e}{R}$ .<br>Nhiệt lượng tỏa ra trong thời gian  $\\Delta t$  là  $Q=I^2R\\Delta t=\\frac{e^2}{R}\\Delta t$ .<br>Khi chuyển khóa sang vị trí  $(2)$ , tụ điện tích điện đến hiệu điện thế  $U=e$ .<br>Năng lượng của tụ điện là  $W=\\frac{1}{2}Ce^2$ .<br>Do đó:  $\\frac{W}{Q}=\\frac{\\frac{1}{2}Ce^2}{\\frac{e^2}{R}\\Delta t}=\\frac{CR}{2\\Delta t}$ .<br>Thay  $C=10,\\mu F=10^{−5},F$ ,  $R\\approx 13,74,\\Omega$ ,  $\\Delta t=34,4,\\mu s=34,4\\cdot 10^{−6},s$ : $\\frac{W}{Q}=\\frac{10^{−5}\\cdot 13,74}{2\\cdot 34,4\\cdot 10^{−6}}\\approx 1,997\\approx 2$ .<br>Lưu ý nhỏ: nếu đáp án tham khảo ghi  $4$  thì có thể họ đã lấy chiều dài mỗi vòng là  $2\\pi d$  hoặc bỏ hệ số  $\\frac{1}{2}$  trong công thức năng lượng tụ điện. Theo công thức chuẩn  $W=\\frac{1}{2}CU^2$  và “đường kính  $10,cm$ ”, kết quả là  $2$ .","difficultySource":"ai"},"ex":[{"exam":133,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"2","question":"Một ống dây dẫn hình trụ dài gồm 1000 vòng dây, mỗi vòng có đường kính 10 cm, được đặt trong từ trường có các đường sức từ song song với trục ống dây. Cảm ứng từ của từ trường biến thiên với tốc độ không đổi. Dây dẫn có tiết diện 0,4mm2 và điện trở suất  $\\rho$ = 1,75.10<sup>−8</sup>Wm. Mạch điện gồm tụ điện C = 10mF và khóa chuyển mạch K . Ban đầu khóa K ở vị trí (1), sau khi dòng điện đã ổn định, gọi Q là nhiệt lượng ống dây tỏa ra trong thời gian ∆t = 34,4 µm . Sau đó chuyển khóa K sang vị trí (2), tụ điện được tích điện đến trạng thái ổn định với năng lượng dự trữ là W . Tính thương số W / Q (làm tròn kết quả đến chữ số hàng đơn vị). <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259687140-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Đáp số 2<br>Ống dây có  $N=1000$  vòng, mỗi vòng có đường kính  $d=10,cm=0,10,m$ .<br>Chiều dài dây dẫn là  $l=N\\pi d=1000\\cdot 3,14\\cdot 0,10=314,m$ .<br>Tiết diện dây dẫn:  $S_d=0,4,mm^2=4\\cdot 10^{−7},m^2$ .<br>Điện trở của ống dây là  $R=\\rho \\frac{l}{S_d}=1,75\\cdot 10^{−8}\\cdot \\frac{314}{4\\cdot 10^{−7}}\\approx 13,74,\\Omega$ .<br>Khi khóa ở vị trí  $(1)$ , dòng điện cảm ứng ổn định có  $I=\\frac{e}{R}$ .<br>Nhiệt lượng tỏa ra trong thời gian  $\\Delta t$  là  $Q=I^2R\\Delta t=\\frac{e^2}{R}\\Delta t$ .<br>Khi chuyển khóa sang vị trí  $(2)$ , tụ điện tích điện đến hiệu điện thế  $U=e$ .<br>Năng lượng của tụ điện là  $W=\\frac{1}{2}Ce^2$ .<br>Do đó:  $\\frac{W}{Q}=\\frac{\\frac{1}{2}Ce^2}{\\frac{e^2}{R}\\Delta t}=\\frac{CR}{2\\Delta t}$ .<br>Thay  $C=10,\\mu F=10^{−5},F$ ,  $R\\approx 13,74,\\Omega$ ,  $\\Delta t=34,4,\\mu s=34,4\\cdot 10^{−6},s$ : $\\frac{W}{Q}=\\frac{10^{−5}\\cdot 13,74}{2\\cdot 34,4\\cdot 10^{−6}}\\approx 1,997\\approx 2$ .<br>Lưu ý nhỏ: nếu đáp án tham khảo ghi  $4$  thì có thể họ đã lấy chiều dài mỗi vòng là  $2\\pi d$  hoặc bỏ hệ số  $\\frac{1}{2}$  trong công thức năng lượng tụ điện. Theo công thức chuẩn  $W=\\frac{1}{2}CU^2$  và “đường kính  $10,cm$ ”, kết quả là  $2$ .","difficultySource":"ai"}}]},{"id":458482,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":3,"options":["$3,1.10^{−6} Wb$","$11,1.10^{−6} Wb$","$6,4.10^{−8} Wb$","$5,54.10^{−8} Wb$"],"question":"Một khung dây hình vuông có cạnh dài 4 cm, đặt trong từ trường đều có cảm ứng từ  $B=4.10^{−5}T$ , mặt phẳng khung dây tạo với các đường sức từ một góc  $60^∘$ . Từ thông qua mặt phẳng khung dây có độ lớn là","difficulty":"trung-binh","explanation":"Phương pháp:<br>Từ thông qua mặt phẳng khung dây có độ lớn:  $\\Phi =BScos\\alpha$<br>Cách giải:<br>Mặt phẳng khung dây tạo với các đường sức từ một góc  $60^0\\Rightarrow \\alpha =\\left(\\vec{n};\\vec{B}\\right)=30^0$<br>Khung dây hình vuông, cạnh dài 4cm có diện tích:<br>S = 0,042 =1,6.10<sup>−3</sup>(m2)<br>Từ thông qua mặt phẳng khung dây là:<br>$\\Phi =BScos\\alpha =4.10^{−5}.1,6.10^{−3}.cos30^0$<br>$\\Rightarrow \\Phi =5,54.10^{−8}\\left(Wb\\right)$","difficultySource":"ai"},"ex":[{"exam":234,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":3,"options":["$3,1.10^{−6} Wb$","$11,1.10^{−6} Wb$","$6,4.10^{−8} Wb$","$5,54.10^{−8} Wb$"],"question":"Một khung dây hình vuông có cạnh dài 4 cm, đặt trong từ trường đều có cảm ứng từ  $B=4.10^{−5}T$ , mặt phẳng khung dây tạo với các đường sức từ một góc  $60^∘$ . Từ thông qua mặt phẳng khung dây có độ lớn là","difficulty":"trung-binh","explanation":"Phương pháp:<br>Từ thông qua mặt phẳng khung dây có độ lớn:  $\\Phi =BScos\\alpha$<br>Cách giải:<br>Mặt phẳng khung dây tạo với các đường sức từ một góc  $60^0\\Rightarrow \\alpha =\\left(\\vec{n};\\vec{B}\\right)=30^0$<br>Khung dây hình vuông, cạnh dài 4cm có diện tích:<br>S = 0,042 =1,6.10<sup>−3</sup>(m2)<br>Từ thông qua mặt phẳng khung dây là:<br>$\\Phi =BScos\\alpha =4.10^{−5}.1,6.10^{−3}.cos30^0$<br>$\\Rightarrow \\Phi =5,54.10^{−8}\\left(Wb\\right)$","difficultySource":"ai"}}]},{"id":458489,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["Mỗi kilôgam đồng toả ra nhiệt lượng  $1,8.10^5 J$  khi hoá lỏng hoàn toàn","Khối đồng cần thu nhiệt lượng  $1,8.10^5 J$  để hoá lỏng.","Khối đồng sẽ toả ra nhiệt lượng  $1,8.10^5 J$  khi nóng chảy hoàn toàn.","Mỗi kilôgam đồng cần thu nhiệt lượng  $1,8.10^5 J$  để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy."],"question":"Nhiệt nóng chảy riêng của đồng là  $1,8.10^5 J/kg$  có ý nghĩa gì?","difficulty":"de","explanation":"Phương pháp:<br>Nhiệt nóng chảy riêng (λ) của một chất được định nghĩa là nhiệt lượng cần thiết để cung cấp cho một đơn vị đo về lượng chất đó (như đơn vị đo khối lượng hay số phân tử như mol) để nó chuyển từ trạng thái rắn sang trạng thái lỏng, tại nhiệt độ nóng chảy.<br>Cách giải:<br>Nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kgcó ý nghĩa: Mỗi kilôgam đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy.","difficultySource":"ai"},"ex":[{"exam":234,"idx":13,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["Mỗi kilôgam đồng toả ra nhiệt lượng  $1,8.10^5 J$  khi hoá lỏng hoàn toàn","Khối đồng cần thu nhiệt lượng  $1,8.10^5 J$  để hoá lỏng.","Khối đồng sẽ toả ra nhiệt lượng  $1,8.10^5 J$  khi nóng chảy hoàn toàn.","Mỗi kilôgam đồng cần thu nhiệt lượng  $1,8.10^5 J$  để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy."],"question":"Nhiệt nóng chảy riêng của đồng là  $1,8.10^5 J/kg$  có ý nghĩa gì?","difficulty":"de","explanation":"Phương pháp:<br>Nhiệt nóng chảy riêng (λ) của một chất được định nghĩa là nhiệt lượng cần thiết để cung cấp cho một đơn vị đo về lượng chất đó (như đơn vị đo khối lượng hay số phân tử như mol) để nó chuyển từ trạng thái rắn sang trạng thái lỏng, tại nhiệt độ nóng chảy.<br>Cách giải:<br>Nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kgcó ý nghĩa: Mỗi kilôgam đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy.","difficultySource":"ai"}}]},{"id":458491,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["$2,3.10^5 J$","$2,3.10^6 J$","$0,23.10^4 J$","$23.10^6 J$"],"question":"Biết nhiệt hóa hơi riêng của nước là  $L=2,3.10^6 J/kg$ . Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100 g nước  $100^∘C$  là","difficulty":"de","explanation":"Phương pháp:<br>Công thức nhiệt lượng cung cấp để làm bay hơi hoàn toàn m g nước: Q = Lm.<br>Cách giải:<br>Nhiệt hóa hơi riêng là nhiệt lượng cần truyền cho một đơn vị khối lượng chất lỏng để nó chuyển thành hơi ở một nhiệt độ xác định.<br>Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100 g nước ở 1000C là<br>Q = Lm = 2,3.106.0,1 =  2,3.10<sup>5</sup> (J)","difficultySource":"ai"},"ex":[{"exam":234,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["$2,3.10^5 J$","$2,3.10^6 J$","$0,23.10^4 J$","$23.10^6 J$"],"question":"Biết nhiệt hóa hơi riêng của nước là  $L=2,3.10^6 J/kg$ . Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100 g nước  $100^∘C$  là","difficulty":"de","explanation":"Phương pháp:<br>Công thức nhiệt lượng cung cấp để làm bay hơi hoàn toàn m g nước: Q = Lm.<br>Cách giải:<br>Nhiệt hóa hơi riêng là nhiệt lượng cần truyền cho một đơn vị khối lượng chất lỏng để nó chuyển thành hơi ở một nhiệt độ xác định.<br>Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100 g nước ở 1000C là<br>Q = Lm = 2,3.106.0,1 =  2,3.10<sup>5</sup> (J)","difficultySource":"ai"}}]},{"id":458513,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["7,2.10<sup>3</sup> J","7,2.10<sup>6</sup> J","1,125.10<sup>5</sup> J","9.10<sup>5</sup> J"],"question":"Giả thiết rằng rượu ethylic có nhiệt hoá hơi riêng là 0,9.106 J/kg và khối lượng riêng là 0,8 kg/lít. Nhiệt lượng cần thiết để 10 lít rượu ethylic hoá hơi hoàn toàn ở nhiệt độ sôi là:","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần thiết để chất lỏng hoá hơi hoàn toàn ở nhiệt độ sôi được tính theo công thức $Q = L\\cdot m$, trong đó $L$ là nhiệt hoá hơi riêng (J/kg) và $m$ là khối lượng (kg).</p><p class=\"text-base leading-relaxed my-2\">Khối lượng rượu ethylic: $m = D\\cdot V = 0{,}8 \\text{ kg/lít} \\cdot 10 \\text{ lít} = 8 \\text{ kg}$.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần thiết: $Q = L\\cdot m = 0{,}9\\cdot 10^{6} \\text{ J/kg} \\cdot 8 \\text{ kg} = 7{,}2\\cdot 10^{6} \\text{ J}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy đáp án đúng là <strong>B. $7{,}2\\cdot 10^{6}$ J</strong>.</p>","difficultySource":"ai"},"ex":[{"exam":235,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["7,2.10<sup>3</sup> J","7,2.10<sup>6</sup> J","1,125.10<sup>5</sup> J","9.10<sup>5</sup> J"],"question":"Giả thiết rằng rượu ethylic có nhiệt hoá hơi riêng là 0,9.106 J/kg và khối lượng riêng là 0,8 kg/lít. Nhiệt lượng cần thiết để 10 lít rượu ethylic hoá hơi hoàn toàn ở nhiệt độ sôi là:","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần thiết để chất lỏng hoá hơi hoàn toàn ở nhiệt độ sôi được tính theo công thức $Q = L\\cdot m$, trong đó $L$ là nhiệt hoá hơi riêng (J/kg) và $m$ là khối lượng (kg).</p><p class=\"text-base leading-relaxed my-2\">Khối lượng rượu ethylic: $m = D\\cdot V = 0{,}8 \\text{ kg/lít} \\cdot 10 \\text{ lít} = 8 \\text{ kg}$.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần thiết: $Q = L\\cdot m = 0{,}9\\cdot 10^{6} \\text{ J/kg} \\cdot 8 \\text{ kg} = 7{,}2\\cdot 10^{6} \\text{ J}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy đáp án đúng là <strong>B. $7{,}2\\cdot 10^{6}$ J</strong>.</p>","difficultySource":"ai"}}]},{"id":458528,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"14","question":"Một căn phòng hở có kích thước như hình vẽ. Ban đầu không khí trong phòng ở điều kiện tiêu chuẩn (nhiệt độ ở 00C; áp suất 1,013.10<sup>5</sup> Pa). Người ta tăng nhiệt độ không khí trong phòng lên tới 200C. Cho biết khối lượng mol của không khí bằng 29 g/mol. Khối lượng không khí đã ra khỏi phòng khi được tăng nhiệt độ là bao nhiêu kg? (Kết quả làm tròn đến phần nguyên)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790616967934-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$n_d−n_s=\\frac{1,013.10^5.5.8.4}{8,31}\\left(\\frac{1}{273}−\\frac{1}{293}\\right)=487,67\\left(mol\\right)=\\frac{m\\left(g\\right)}{M\\left(29g/mol\\right)}$<br>$\\Rightarrow m=14,14\\left(kg\\right)$","difficultySource":"ai"},"ex":[{"exam":235,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"14","question":"Một căn phòng hở có kích thước như hình vẽ. Ban đầu không khí trong phòng ở điều kiện tiêu chuẩn (nhiệt độ ở 00C; áp suất 1,013.10<sup>5</sup> Pa). Người ta tăng nhiệt độ không khí trong phòng lên tới 200C. Cho biết khối lượng mol của không khí bằng 29 g/mol. Khối lượng không khí đã ra khỏi phòng khi được tăng nhiệt độ là bao nhiêu kg? (Kết quả làm tròn đến phần nguyên)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790616967934-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$n_d−n_s=\\frac{1,013.10^5.5.8.4}{8,31}\\left(\\frac{1}{273}−\\frac{1}{293}\\right)=487,67\\left(mol\\right)=\\frac{m\\left(g\\right)}{M\\left(29g/mol\\right)}$<br>$\\Rightarrow m=14,14\\left(kg\\right)$","difficultySource":"ai"}}]},{"id":465877,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"4","question":"Trong một lần chạy bộ ngoài trời, một người tiêu hao 6.10<sup>5</sup>J nội năng của mình. Biết nhiệt lượng mà cơ thể người truyền ra ngoài môi trường là 2.10<sup>5</sup>J. Tổng cộng mà người này thực hiện trong quá trình chạy bộ là x.10<sup>5</sup>J . Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"Đáp số 4<br>$\\Delta U=A+Q$<br>$\\Rightarrow −6.10^5=−\\left(x.10^5\\right)−2.10^5$<br>$\\Rightarrow x=4$","difficultySource":"ai"},"ex":[{"exam":142,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"4","question":"Trong một lần chạy bộ ngoài trời, một người tiêu hao 6.10<sup>5</sup>J nội năng của mình. Biết nhiệt lượng mà cơ thể người truyền ra ngoài môi trường là 2.10<sup>5</sup>J. Tổng cộng mà người này thực hiện trong quá trình chạy bộ là x.10<sup>5</sup>J . Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"Đáp số 4<br>$\\Delta U=A+Q$<br>$\\Rightarrow −6.10^5=−\\left(x.10^5\\right)−2.10^5$<br>$\\Rightarrow x=4$","difficultySource":"ai"}}]},{"id":465878,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"7,92","question":"Trong một cuộc thi sáng tạo khoa học, một đội thi đã đề xuất giải pháp cảnh báo nhiệt độ cho một kho lạnh mà không dùng đến cảm biến điện tử. Họ sử dụng bộ dụng cụ như hình bên và thực hiện như sau: Đặt cố định một xi lanh kín, thành mỏng, có diện tích tiết diện S = 50cm2 trên mặt sàn; Cho một khối khí lí tưởng vào trong xi lanh và ngăn cách với bên ngoài bằng một pit-tông (khối lượng m1 = 1kg ) có thể di chuyển không ma sát trong xi lanh; Đặt thanh cứng AB đồng chất tiết diện đều có trục quay cố định tại O sao cho OA = OB, đầu A nối với pit-tông bằng sợi dây, đầu B treo vật có khối lượng m2 = 4,75kg đặt trên mặt cân điện tử. Biết tại nhiệt độ phòng 27°C, pit-tông cách đáy xi lanh 40cm, áp suất của khối khí lí tưởng trong xi lanh là 98750 Pa và thanh AB cân bằng nằm ngang. Cho các dây treo nhẹ, không co dãn và luôn có phương thẳng đứng, nhiệt độ của khí trong xi lanh luôn bằng nhiệt độ của kho, áp suất khí quyển là p0 =105 Pa . Bỏ qua sự dãn nở vì nhiệt của thiết bị. Lấy g = 10$m/s^2$. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259765440-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Số mol khí lí tưởng trong xi lanh là x.10<sup>−2</sup> mol . Giá trị của x là bao nhiêu (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"de","explanation":"Đáp số 7,92<br>$n=\\frac{pV}{RT}=\\frac{98750.\\left(40.50\\right).10^{−6}}{8,31.\\left(27+273\\right)}\\approx 0,07922\\approx 7,92.10^{−2}$","difficultySource":"ai"},"ex":[{"exam":142,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"7,92","question":"Trong một cuộc thi sáng tạo khoa học, một đội thi đã đề xuất giải pháp cảnh báo nhiệt độ cho một kho lạnh mà không dùng đến cảm biến điện tử. Họ sử dụng bộ dụng cụ như hình bên và thực hiện như sau: Đặt cố định một xi lanh kín, thành mỏng, có diện tích tiết diện S = 50cm2 trên mặt sàn; Cho một khối khí lí tưởng vào trong xi lanh và ngăn cách với bên ngoài bằng một pit-tông (khối lượng m1 = 1kg ) có thể di chuyển không ma sát trong xi lanh; Đặt thanh cứng AB đồng chất tiết diện đều có trục quay cố định tại O sao cho OA = OB, đầu A nối với pit-tông bằng sợi dây, đầu B treo vật có khối lượng m2 = 4,75kg đặt trên mặt cân điện tử. Biết tại nhiệt độ phòng 27°C, pit-tông cách đáy xi lanh 40cm, áp suất của khối khí lí tưởng trong xi lanh là 98750 Pa và thanh AB cân bằng nằm ngang. Cho các dây treo nhẹ, không co dãn và luôn có phương thẳng đứng, nhiệt độ của khí trong xi lanh luôn bằng nhiệt độ của kho, áp suất khí quyển là p0 =105 Pa . Bỏ qua sự dãn nở vì nhiệt của thiết bị. Lấy g = 10m/s2. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259765440-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Số mol khí lí tưởng trong xi lanh là x.10<sup>−2</sup> mol . Giá trị của x là bao nhiêu (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"de","explanation":"Đáp số 7,92<br>$n=\\frac{pV}{RT}=\\frac{98750.\\left(40.50\\right).10^{−6}}{8,31.\\left(27+273\\right)}\\approx 0,07922\\approx 7,92.10^{−2}$","difficultySource":"ai"}}]},{"id":523786,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh thực hiện thí nghiệm đo nhiệt hóa hơi riêng của nước. Họ tiến hành thí nghiệm theo trình tự như sau:<br>− Lấy một lượng nước cho vào ấm đun siêu tốc, đặt ấm lên cân điện tử và bắt bầu đun. Khi nước trong ấm sôi, mở nắp để hơi nước thoát ra ngoài.<br>− Ghi lại số chỉ của cân m (kg) theo thời gian t (s).<br>Kết quả thu được như bảng sau:<br>Lần đo\tm (kg)\tt (s)<br>1\t1,773\t162,05<br>2\t1,673\t323,09<br>3\t1,573\t480,18<br>4\t1,473\t645,25<br>5\t1,373\t805,22<br>Biết ấm có vỏ cách nhiệt tốt và có công suất  $℘=1,50.10^3W;$  đồng hồ đo thời gian có độ chia nhỏ nhất là 0,01 s; số chỉ của cân ở thời điểm ban đầu  $t_0=0,00s$  (nước bắt đầu sôi) là  $m_0=1,873kg.$  Coi nhiệt lượng do ấm tỏa ra chỉ dùng để cung cấp cho lượng nước trong ấm. Lấy sai số dụng cụ bằng một nửa độ chia nhỏ nhất.","difficulty":"kho","statements":[{"text":"Số chỉ của cân là khối lượng của nước còn lại trong ấm tại thời điểm đo.","answer":false},{"text":"Sai số dụng cụ của đồng hồ đo thời gian trong thí nghiệm trên là 0,005 s.","answer":true},{"text":"Khối lượng nước đã hóa hơi trong khoảng thời gian 323,09 s (kể từ thời điểm ban đầu) là 200 g.","answer":true},{"text":"Giá trị trung bình của nhiệt hóa hơi riêng của nước đo được từ thí nghiệm trên xấp xỉ bằng 2,418.10<sup>6</sup> J/kg.","answer":true}],"explanation":"a) sai<br>Số chỉ của cân là tổng khối lượng của nước còn lại trong ấm tại thời điểm đo và khối lượng của ấm.<br>b) đúng<br>Sai số dụng cụ của đồng hồ đo thời gian trong thí nghiệm trên là:<br>${\\Delta x}_{dc}=\\frac{1}{2}ĐCNN=\\frac{1}{2}.0,01=0,005$  s.<br>c) đúng<br>Khối lượng nước đã hóa hơi trong khoảng thời gian 323,09 s (kể từ thời điểm ban đầu) là:<br>$\\Delta m=m_0-m=1,873-1,673=0,2$  kg = 200 g.<br>d) đúng<br>Ta có:  $\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $℘t=L.\\Delta m=L\\left(m_0-m\\right)$    $L=\\frac{℘t}{m_0-m}$  (J/kg).","difficultySource":"ai"},"ex":[{"exam":260,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh thực hiện thí nghiệm đo nhiệt hóa hơi riêng của nước. Họ tiến hành thí nghiệm theo trình tự như sau:<br>− Lấy một lượng nước cho vào ấm đun siêu tốc, đặt ấm lên cân điện tử và bắt bầu đun. Khi nước trong ấm sôi, mở nắp để hơi nước thoát ra ngoài.<br>− Ghi lại số chỉ của cân m (kg) theo thời gian t (s).<br>Kết quả thu được như bảng sau:<br>Lần đo\tm (kg)\tt (s)<br>1\t1,773\t162,05<br>2\t1,673\t323,09<br>3\t1,573\t480,18<br>4\t1,473\t645,25<br>5\t1,373\t805,22<br>Biết ấm có vỏ cách nhiệt tốt và có công suất  $℘=1,50.10^3W;$  đồng hồ đo thời gian có độ chia nhỏ nhất là 0,01 s; số chỉ của cân ở thời điểm ban đầu  $t_0=0,00s$  (nước bắt đầu sôi) là  $m_0=1,873kg.$  Coi nhiệt lượng do ấm tỏa ra chỉ dùng để cung cấp cho lượng nước trong ấm. Lấy sai số dụng cụ bằng một nửa độ chia nhỏ nhất.","difficulty":"kho","statements":[{"text":"Số chỉ của cân là khối lượng của nước còn lại trong ấm tại thời điểm đo.","answer":false},{"text":"Sai số dụng cụ của đồng hồ đo thời gian trong thí nghiệm trên là 0,005 s.","answer":true},{"text":"Khối lượng nước đã hóa hơi trong khoảng thời gian 323,09 s (kể từ thời điểm ban đầu) là 200 g.","answer":true},{"text":"Giá trị trung bình của nhiệt hóa hơi riêng của nước đo được từ thí nghiệm trên xấp xỉ bằng 2,418.10<sup>6</sup> J/kg.","answer":true}],"explanation":"a) sai<br>Số chỉ của cân là tổng khối lượng của nước còn lại trong ấm tại thời điểm đo và khối lượng của ấm.<br>b) đúng<br>Sai số dụng cụ của đồng hồ đo thời gian trong thí nghiệm trên là:<br>${\\Delta x}_{dc}=\\frac{1}{2}ĐCNN=\\frac{1}{2}.0,01=0,005$  s.<br>c) đúng<br>Khối lượng nước đã hóa hơi trong khoảng thời gian 323,09 s (kể từ thời điểm ban đầu) là:<br>$\\Delta m=m_0-m=1,873-1,673=0,2$  kg = 200 g.<br>d) đúng<br>Ta có:  $\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $℘t=L.\\Delta m=L\\left(m_0-m\\right)$    $L=\\frac{℘t}{m_0-m}$  (J/kg).","difficultySource":"ai"}}]},{"id":523787,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một lọ giác hơi chứa không khí (xem là khí lí tưởng) được hơ nóng rồi úp nhanh lên da bệnh nhân. Nhiệt độ và áp suất của khối khí trong lọ khí đó lần lượt là 600 K và 1,00.10<sup>5</sup> Pa. Sau một thời gian, nhiệt độ của khí trong lọ giảm còn 300 K, đồng thời do da bị hút vào nên thể tích khí giảm đi 20% so với thể tích ban đầu. Biết áp suất khí quyển là 1,00.10<sup>5</sup> Pa, diện tích miệng lọ là 30 cm2. Khí trong lọ giác hơi không thoát ra ngoài.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044600195-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất của khí trong lọ giác hơi khi nhiệt độ của khí giảm còn 300 K là 6,25.10<sup>4</sup> Pa.","answer":true},{"text":"Trong quá trình biến đổi trạng thái, áp suất của khí trong lọ giác hơi luôn tỉ lệ thuận với nhiệt độ tuyệt đối của khí.","answer":false},{"text":"Khi nhiệt độ của khí trong lọ giác hơi giảm còn 300 K, lực hút tác dụng lên da có độ lớn xấp xỉ bằng 112,5 N.","answer":true},{"text":"Nhiệt độ của khí trong lọ giác hơi giảm nên nội năng của khí giảm.","answer":true}],"explanation":"a) đúng<br>Theo phương trình trạng thái khí lí tưởng ta có:<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}$    $p_2=\\frac{p_1V_1T_2}{V_2T_1}=\\frac{{10}^5.V_1.300}{0,8V_1.600}=6,25.{10}^4$  Pa.<br>b) sai<br>Vì thể tích của khí trong lọ giác hơi thay đổi nên áp suất của khí không tỉ lệ thuận với nhiệt độ tuyệt đối của khí.<br>c) đúng<br>Lực hút tác dụng lên da là:<br>$F=F_{ngoài}-F_{trong}=p_0S-pS=\\left(p_0-p\\right)S=\\left({10}^5-6,25.{10}^4\\right).30.{10}^{-4}=112,5$  N.<br>d) đúng<br>Nội năng của khí lí tưởng chỉ phụ thuộc vào nhiệt độ, khi nhiệt độ của khí giảm thì nội năng của khí giảm.","difficultySource":"ai"},"ex":[{"exam":260,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một lọ giác hơi chứa không khí (xem là khí lí tưởng) được hơ nóng rồi úp nhanh lên da bệnh nhân. Nhiệt độ và áp suất của khối khí trong lọ khí đó lần lượt là 600 K và 1,00.10<sup>5</sup> Pa. Sau một thời gian, nhiệt độ của khí trong lọ giảm còn 300 K, đồng thời do da bị hút vào nên thể tích khí giảm đi 20% so với thể tích ban đầu. Biết áp suất khí quyển là 1,00.10<sup>5</sup> Pa, diện tích miệng lọ là 30 cm2. Khí trong lọ giác hơi không thoát ra ngoài.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044600195-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất của khí trong lọ giác hơi khi nhiệt độ của khí giảm còn 300 K là 6,25.10<sup>4</sup> Pa.","answer":true},{"text":"Trong quá trình biến đổi trạng thái, áp suất của khí trong lọ giác hơi luôn tỉ lệ thuận với nhiệt độ tuyệt đối của khí.","answer":false},{"text":"Khi nhiệt độ của khí trong lọ giác hơi giảm còn 300 K, lực hút tác dụng lên da có độ lớn xấp xỉ bằng 112,5 N.","answer":true},{"text":"Nhiệt độ của khí trong lọ giác hơi giảm nên nội năng của khí giảm.","answer":true}],"explanation":"a) đúng<br>Theo phương trình trạng thái khí lí tưởng ta có:<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}$    $p_2=\\frac{p_1V_1T_2}{V_2T_1}=\\frac{{10}^5.V_1.300}{0,8V_1.600}=6,25.{10}^4$  Pa.<br>b) sai<br>Vì thể tích của khí trong lọ giác hơi thay đổi nên áp suất của khí không tỉ lệ thuận với nhiệt độ tuyệt đối của khí.<br>c) đúng<br>Lực hút tác dụng lên da là:<br>$F=F_{ngoài}-F_{trong}=p_0S-pS=\\left(p_0-p\\right)S=\\left({10}^5-6,25.{10}^4\\right).30.{10}^{-4}=112,5$  N.<br>d) đúng<br>Nội năng của khí lí tưởng chỉ phụ thuộc vào nhiệt độ, khi nhiệt độ của khí giảm thì nội năng của khí giảm.","difficultySource":"ai"}}]},{"id":523791,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thuyết động học phân tử chất khí","answer":"4,1","question":"Ở điều kiện chuẩn, một phân tử khí oxygen có tốc độ trung bình khoảng 450 m/s. Quãng đường tự do trung bình của phân tử (khoảng cách trung bình giữa hai lần va chạm liên tiếp) là 1,1.10<sup>7</sup> m. Trung bình mỗi giây, một phân tử oxy thực hiện khoảng x.10<sup>9</sup> lần va chạm. Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần chục)","difficulty":"de","explanation":"Số va chạm trong một giây là:  $\\frac{450.1}{1,1.{10}^{-7}}\\approx 4,1.{10}^9$<br>Vậy x = 4,1.","difficultySource":"ai"},"ex":[{"exam":260,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Thuyết động học phân tử chất khí","answer":"4,1","question":"Ở điều kiện chuẩn, một phân tử khí oxygen có tốc độ trung bình khoảng 450 m/s. Quãng đường tự do trung bình của phân tử (khoảng cách trung bình giữa hai lần va chạm liên tiếp) là 1,1.10<sup>7</sup> m. Trung bình mỗi giây, một phân tử oxy thực hiện khoảng x.10<sup>9</sup> lần va chạm. Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần chục)","difficulty":"de","explanation":"Số va chạm trong một giây là:  $\\frac{450.1}{1,1.{10}^{-7}}\\approx 4,1.{10}^9$<br>Vậy x = 4,1.","difficultySource":"ai"}}]},{"id":523801,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":0,"options":["8 lít.","20 lít.","15 lít.","10 lít."],"question":"Người ta biến đổi đẳng nhiệt một khối khí có thể tích là 12 lít ở áp suất 105 Pa sang trạng thái có áp suất 1,5.10<sup>5</sup> Pa. Sau khi biến đổi, thể tích khối khí là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Quá trình biến đổi đẳng nhiệt của một lượng khí xác định tuân theo định luật Boyle–Mariotte: tích áp suất và thể tích không đổi, $p_1V_1 = p_2V_2$.</p><p class=\"text-base leading-relaxed my-2\">Trạng thái đầu: $p_1 = 10^5$ Pa, $V_1 = 12$ lít.</p><p class=\"text-base leading-relaxed my-2\">Trạng thái sau: $p_2 = 1{,}5\\cdot 10^5$ Pa, thể tích $V_2$ cần tìm.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $V_2 = \\dfrac{p_1 V_1}{p_2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow V_2 = \\dfrac{10^5 \\cdot 12}{1{,}5\\cdot 10^5} = 8$ lít.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: thể tích khối khí sau biến đổi là 8 lít, chọn đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":261,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":0,"options":["8 lít.","20 lít.","15 lít.","10 lít."],"question":"Người ta biến đổi đẳng nhiệt một khối khí có thể tích là 12 lít ở áp suất 105 Pa sang trạng thái có áp suất 1,5.10<sup>5</sup> Pa. Sau khi biến đổi, thể tích khối khí là","difficulty":"de","explanation":"$p_1V_1=p_2V_2\\Rightarrow V_2=\\frac{p_1V_1}{p_2}=8\\left(lit\\right)$","difficultySource":"ai"}}]},{"id":523814,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Người ta sử dụng bộ thí nghiệm (hình bên) để tìm hiểu về mối liên hệ giữa áp suất và thể tích của  $1,5.10^{-4}$  mol khí ở nhiệt độ không đổi.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044611519-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"(2) là pit-tông có ống nối khí trong xi lanh với áp kế.","answer":true},{"text":"Với kết quả thu được ở bảng bên, tích pV trong hệ đơn vị SI bằng 3.","answer":false},{"text":"Nhiệt độ của lượng khí đã dùng trong thí nghiệm khoảng 301K","answer":false},{"text":"Thí nghiệm này là thí nghiệm kiểm chứng định luật Boyle.","answer":true}],"explanation":"a) đúng<br>(2) là pit-tông có ống nối khí trong xi lanh với áp kế.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Ta có tích pV = 3.10-6.10<sup>5</sup> = 0,3<br>c) sai<br>Ta có  $pV=nRT$ ; thay p = 105 Pa; V = 3.10<sup>−6</sup> m3; n =  $1,5.10^{-4}$  mol; R = 8,31 J.mol-1.K-1 ta được<br>T = 240,67 K<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Thí nghiệm này là thí nghiệm kiểm chứng định luật Boyle.","difficultySource":"ai"},"ex":[{"exam":261,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Người ta sử dụng bộ thí nghiệm (hình bên) để tìm hiểu về mối liên hệ giữa áp suất và thể tích của  $1,5.10^{-4}$  mol khí ở nhiệt độ không đổi.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044611519-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"(2) là pit-tông có ống nối khí trong xi lanh với áp kế.","answer":true},{"text":"Với kết quả thu được ở bảng bên, tích pV trong hệ đơn vị SI bằng 3.","answer":false},{"text":"Nhiệt độ của lượng khí đã dùng trong thí nghiệm khoảng 301K","answer":false},{"text":"Thí nghiệm này là thí nghiệm kiểm chứng định luật Boyle.","answer":true}],"explanation":"a) đúng<br>(2) là pit-tông có ống nối khí trong xi lanh với áp kế.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Ta có tích pV = 3.10-6.10<sup>5</sup> = 0,3<br>c) sai<br>Ta có  $pV=nRT$ ; thay p = 105 Pa; V = 3.10<sup>−6</sup> m3; n =  $1,5.10^{-4}$  mol; R = 8,31 J.mol-1.K-1 ta được<br>T = 240,67 K<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Thí nghiệm này là thí nghiệm kiểm chứng định luật Boyle.","difficultySource":"ai"}}]},{"id":523817,"nq":{"form":"bai_tap","type":"true_false","topic":"Hiện tượng phóng xạ. Chu kì bán rã","question":"Đồng vị Iodine  $\\left(​_{53}^{131}I\\right)$  là chất phóng xạ  $\\beta^-$  được sử dụng trong y học để điều trị các bệnh liên quan đến tuyến giáp. Chất này có chu kỳ bán rã là 8,04 ngày. Một bệnh nhân được chỉ định sử dụng liều Iodine-131 với độ phóng xạ ban đầu là  $H_0= 5,20\\cdot {10}^8 Bq$ . Coi rằng 85% lượng Iodine $\\left(​_{53}^{131}I\\right)$  trong liều đó sẽ tập trung tại tuyến giáp. Bệnh nhân được kiểm tra tuyến giáp lần thứ nhất ngay sau khi dùng liều và lần thứ hai sau 48 giờ. Biết khối lượng mol nguyên tử của Iodine là 127 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  $​_{53}^{131}I$  phát ra hạt electron để biến đổi thành hạt nhân  $​_{54}^{131}Xe$ .","answer":true},{"text":"Hằng số phóng xạ của  $​_{53}^{131}I$  là  $0,086 s^{-1}$ .","answer":false},{"text":"Khối lượng của  $​_{53}^{131}I$  có trong liều mà bệnh nhân đã sử dụng là  $0,032 \\mu g$ .","answer":false},{"text":"Sau khi dùng liều 48 giờ, lượng  $​_{53}^{131}I$  đã lắng đọng tại tuyến giáp có độ phóng xạ là  $3,97\\cdot {10}^8 Bq$ .","answer":false}],"explanation":"a) đúng<br>$​_{53}^{131}I \\rightarrow \\beta^-+ ​_{54}^{131}Xe$<br>b) sai<br>$\\lambda =\\frac{ln2}{T}=$   $1.10^{-7}$   $s^{-1}$<br>c) sai<br>$H_0= \\lambda N_0\\rightarrow N_0=\\frac{H_0}{\\lambda }=5,2.10^{15} hạt$<br>Khối lượng I là: m $=\\frac{N}{N_A}.M=1,132.10^{-6}g= 1,132 \\mu g.$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>Độ phóng xạ còn lại sau 48 h:  ${H=H}_0.2^{-t/T}=4,38.10^8$  Bq.<br>Vì chỉ có 85% lượng Iodine $\\left(​_{53}^{131}I\\right)$  trong liều đó sẽ tập trung tại tuyến giáp nên: H’ = 0,85H = 3,72. 10<sup>8</sup> Bq.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":261,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Hiện tượng phóng xạ. Chu kì bán rã","question":"Đồng vị Iodine  $\\left(​_{53}^{131}I\\right)$  là chất phóng xạ  $\\beta^-$  được sử dụng trong y học để điều trị các bệnh liên quan đến tuyến giáp. Chất này có chu kỳ bán rã là 8,04 ngày. Một bệnh nhân được chỉ định sử dụng liều Iodine-131 với độ phóng xạ ban đầu là  $H_0= 5,20\\cdot {10}^8 Bq$ . Coi rằng 85% lượng Iodine $\\left(​_{53}^{131}I\\right)$  trong liều đó sẽ tập trung tại tuyến giáp. Bệnh nhân được kiểm tra tuyến giáp lần thứ nhất ngay sau khi dùng liều và lần thứ hai sau 48 giờ. Biết khối lượng mol nguyên tử của Iodine là 127 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  $​_{53}^{131}I$  phát ra hạt electron để biến đổi thành hạt nhân  $​_{54}^{131}Xe$ .","answer":true},{"text":"Hằng số phóng xạ của  $​_{53}^{131}I$  là  $0,086 s^{-1}$ .","answer":false},{"text":"Khối lượng của  $​_{53}^{131}I$  có trong liều mà bệnh nhân đã sử dụng là  $0,032 \\mu g$ .","answer":false},{"text":"Sau khi dùng liều 48 giờ, lượng  $​_{53}^{131}I$  đã lắng đọng tại tuyến giáp có độ phóng xạ là  $3,97\\cdot {10}^8 Bq$ .","answer":false}],"explanation":"a) đúng<br>$​_{53}^{131}I \\rightarrow \\beta^-+ ​_{54}^{131}Xe$<br>b) sai<br>$\\lambda =\\frac{ln2}{T}=$   $1.10^{-7}$   $s^{-1}$<br>c) sai<br>$H_0= \\lambda N_0\\rightarrow N_0=\\frac{H_0}{\\lambda }=5,2.10^{15} hạt$<br>Khối lượng I là: m $=\\frac{N}{N_A}.M=1,132.10^{-6}g= 1,132 \\mu g.$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>Độ phóng xạ còn lại sau 48 h:  ${H=H}_0.2^{-t/T}=4,38.10^8$  Bq.<br>Vì chỉ có 85% lượng Iodine $\\left(​_{53}^{131}I\\right)$  trong liều đó sẽ tập trung tại tuyến giáp nên: H’ = 0,85H = 3,72. 10<sup>8</sup> Bq.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":523826,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["167 kJ.","167.103 kJ.","167 MJ.","1,67 kJ."],"question":"Nhiệt nóng chảy riêng của nước đá bằng 3,34.10<sup>5</sup> J/kg, nhiệt lượng cần thiết để làm nóng chảy hoàn toàn 500 g nước đá ở 00C là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần thiết để làm nóng chảy hoàn toàn một vật rắn ở nhiệt độ nóng chảy được tính theo công thức $Q = \\lambda m$, trong đó $\\lambda$ là nhiệt nóng chảy riêng và $m$ là khối lượng.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 500\\ \\text{g} = 0{,}5\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 3{,}34 \\cdot 10^{5} \\cdot 0{,}5 = 1{,}67 \\cdot 10^{5}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 1{,}67 \\cdot 10^{5}\\ \\text{J} = 167\\ \\text{kJ}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: nhiệt lượng cần thiết là $167\\ \\text{kJ}$, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":262,"idx":2,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["167 kJ.","167.103 kJ.","167 MJ.","1,67 kJ."],"question":"Nhiệt nóng chảy riêng của nước đá bằng 3,34.10<sup>5</sup> J/kg, nhiệt lượng cần thiết để làm nóng chảy hoàn toàn 500 g nước đá ở 00C là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần thiết để làm nóng chảy hoàn toàn một vật rắn ở nhiệt độ nóng chảy được tính theo công thức $Q = \\lambda m$, trong đó $\\lambda$ là nhiệt nóng chảy riêng và $m$ là khối lượng.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 500\\ \\text{g} = 0{,}5\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 3{,}34 \\cdot 10^{5} \\cdot 0{,}5 = 1{,}67 \\cdot 10^{5}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 1{,}67 \\cdot 10^{5}\\ \\text{J} = 167\\ \\text{kJ}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: nhiệt lượng cần thiết là $167\\ \\text{kJ}$, đáp án A.</p>","difficultySource":"ai"}}]},{"id":523833,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":2,"options":["1,7.10<sup>27</sup>.","1,7.10<sup>24</sup>.","1,51.10<sup>24</sup>.","1,51.10<sup>27</sup>."],"question":"Một lốp xe ô tô có thể tích 25 lít chứa không khí (được coi là lí tưởng) ở nhiệt độ 270C và áp suất 2,5.10<sup>5</sup> Pa. Lấy NA = 6,02.10<sup>23</sup> mol‒1. Số phân tử không khí có trong lốp ô tô này là","difficulty":"trung-binh","explanation":"$n=\\frac{pV}{RT}=\\frac{2,5.10^5.25.10^{−3}}{8,31.\\left(27+273\\right)}\\approx 2,51 mol$<br>$N=nN_A=2,51.6,02.10^{23}\\approx 1,51.10^{24}$","difficultySource":"ai"},"ex":[{"exam":262,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":2,"options":["1,7.10<sup>27</sup>.","1,7.10<sup>24</sup>.","1,51.10<sup>24</sup>.","1,51.10<sup>27</sup>."],"question":"Một lốp xe ô tô có thể tích 25 lít chứa không khí (được coi là lí tưởng) ở nhiệt độ 270C và áp suất 2,5.10<sup>5</sup> Pa. Lấy NA = 6,02.10<sup>23</sup> mol‒1. Số phân tử không khí có trong lốp ô tô này là","difficulty":"trung-binh","explanation":"$n=\\frac{pV}{RT}=\\frac{2,5.10^5.25.10^{−3}}{8,31.\\left(27+273\\right)}\\approx 2,51 mol$<br>$N=nN_A=2,51.6,02.10^{23}\\approx 1,51.10^{24}$","difficultySource":"ai"}}]},{"id":523842,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng thực hiện quá trình biến đổi trạng thái nhiệt từ trạng thái (1) sang trạng thái (2) mà áp suất p của khối khí phụ thuộc vào thể tích V của nó được mô tả như giản đồ ở hình vẽ bên. Biết ở trạng thái (1) khối khí có nhiệt độ T1 = 600 K, thể tích V1 = 2.10‒3 m3 và áp suất p1 = 2.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044616316-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình biến đổi khí từ trạng thái (1) sang trạng thái (2) là quá trình đẳng nhiệt.","answer":false},{"text":"Công do chất khí thực hiện khi biến đổi từ trạng thái (1) sang trạng thái (2) có độ lớn là 500 J.","answer":true},{"text":"Nhiệt độ của khối khí ở trạng thái (2) là 450 K.","answer":true},{"text":"Nhiệt độ của khối khí trong quá trình biến đổi từ trạng thái (1) sang trạng thái (2) đạt giá trị lớn nhất khi áp suất của khối khí là 1,375.10<sup>5</sup> Pa.","answer":true}],"explanation":"a) sai<br>Trên hệ trục tọa độ pOV, đường đẳng nhiệt có dạng là đường hypebol<br>b) đúng<br>Dễ thấy:  $\\left\\{\\begin{aligned}p_1=4p_2 <br>V_2=3V_1\\end{aligned}\\right.$<br>Công của khối khí thực hiện là diện tích hình thang:<br>$A^/=\\frac{1}{2}.\\left(p_1+p_2\\right)\\left(V_2−V_1\\right)=\\frac{1}{2}.\\left(p_1+\\frac{p_1}{4}\\right)\\left(3V_1−V_1\\right)=\\frac{5}{4}p_1V_1=\\frac{5}{4}.2.10^5.2.10^{−3}=500\\left(J\\right)$<br>c) đúng<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}\\Rightarrow \\frac{4p_2V_1}{600}=\\frac{p_2.3V_1}{T_2}\\Rightarrow T_2=450K$<br>d) đúng<br>$p=aV+b\\Rightarrow \\left\\{\\begin{aligned}p_1=aV_1+b <br>\\frac{p_1}{4}=a.3V_1+b\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}2.10^5=a.2.10^{−3}+b <br>\\frac{2.10^5}{4}=a.3.2.10^{−3}+b\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}a=−375.10^5 <br>b=275.10^3\\end{aligned}\\right.$<br>$\\frac{pV}{T}=constT_{max}\\rightarrow pV=aV^2+bV$  đạt max<br>Đạo hàm  ${\\left(pV\\right)}^/=2aV+b=0\\Rightarrow V=−\\frac{b}{2a}=−\\frac{275.10^3}{2.\\left(−375.10^5\\right)}=\\frac{11}{3000}m^3$<br>$\\Rightarrow p=−375.10^5.\\frac{11}{3000}+275.10^3=1,375.10^5Pa$","difficultySource":"ai"},"ex":[{"exam":262,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng thực hiện quá trình biến đổi trạng thái nhiệt từ trạng thái (1) sang trạng thái (2) mà áp suất p của khối khí phụ thuộc vào thể tích V của nó được mô tả như giản đồ ở hình vẽ bên. Biết ở trạng thái (1) khối khí có nhiệt độ T1 = 600 K, thể tích V1 = 2.10‒3 m3 và áp suất p1 = 2.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044616316-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình biến đổi khí từ trạng thái (1) sang trạng thái (2) là quá trình đẳng nhiệt.","answer":false},{"text":"Công do chất khí thực hiện khi biến đổi từ trạng thái (1) sang trạng thái (2) có độ lớn là 500 J.","answer":true},{"text":"Nhiệt độ của khối khí ở trạng thái (2) là 450 K.","answer":true},{"text":"Nhiệt độ của khối khí trong quá trình biến đổi từ trạng thái (1) sang trạng thái (2) đạt giá trị lớn nhất khi áp suất của khối khí là 1,375.10<sup>5</sup> Pa.","answer":true}],"explanation":"a) sai<br>Trên hệ trục tọa độ pOV, đường đẳng nhiệt có dạng là đường hypebol<br>b) đúng<br>Dễ thấy:  $\\left\\{\\begin{aligned}p_1=4p_2 <br>V_2=3V_1\\end{aligned}\\right.$<br>Công của khối khí thực hiện là diện tích hình thang:<br>$A^/=\\frac{1}{2}.\\left(p_1+p_2\\right)\\left(V_2−V_1\\right)=\\frac{1}{2}.\\left(p_1+\\frac{p_1}{4}\\right)\\left(3V_1−V_1\\right)=\\frac{5}{4}p_1V_1=\\frac{5}{4}.2.10^5.2.10^{−3}=500\\left(J\\right)$<br>c) đúng<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}\\Rightarrow \\frac{4p_2V_1}{600}=\\frac{p_2.3V_1}{T_2}\\Rightarrow T_2=450K$<br>d) đúng<br>$p=aV+b\\Rightarrow \\left\\{\\begin{aligned}p_1=aV_1+b <br>\\frac{p_1}{4}=a.3V_1+b\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}2.10^5=a.2.10^{−3}+b <br>\\frac{2.10^5}{4}=a.3.2.10^{−3}+b\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}a=−375.10^5 <br>b=275.10^3\\end{aligned}\\right.$<br>$\\frac{pV}{T}=constT_{max}\\rightarrow pV=aV^2+bV$  đạt max<br>Đạo hàm  ${\\left(pV\\right)}^/=2aV+b=0\\Rightarrow V=−\\frac{b}{2a}=−\\frac{275.10^3}{2.\\left(−375.10^5\\right)}=\\frac{11}{3000}m^3$<br>$\\Rightarrow p=−375.10^5.\\frac{11}{3000}+275.10^3=1,375.10^5Pa$","difficultySource":"ai"}}]},{"id":523843,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Người ta dùng một lò hồ quang điện để nấu chảy một khối kim loại nặng 20 kg. Biết lò hồ quang cung cấp cho khối kim loại một nhiệt lượng không đổi là 5000 J/s. Sự thay đổi nhiệt độ của khối kim loại được ghi lại theo thời gian như hình vẽ.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044616503-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Giai đoạn AB trên đồ thị tương ứng với quá trình nóng chảy của kim loại.","answer":false},{"text":"Giai đoạn BC khối kim loại không nhận thêm nhiệt lượng từ lò nung.","answer":false},{"text":"Nhiệt dung riêng của khối kim loại là 500 J/kg.K.","answer":true},{"text":"Nhiệt nóng chảy riêng của khối kim loại là 3.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) sai<br>Giai đoạn AB, chất rắn tăng nhiệt độ.<br>b) sai<br>Giai đoạn BC, kim loại nhận nhiệt lượng và nóng chảy.<br>c) đúng<br>$Q_{AB}=Pt_{AB}=5000.50.60=15.10^6J$<br>$Q_{AB}=mc\\Delta t\\Rightarrow 15.10^6=20.c.\\left(1530−30\\right)\\Rightarrow c=500\\left(J/kg.K\\right)$<br>d) đúng<br>$Q_{BC}=Pt_{BC}=5000.\\left(70−50\\right).60=6.10^6\\left(J\\right)$<br>$\\lambda =\\frac{Q_{BC}}{m}=\\frac{6.10^6}{20}=3.10^5 J/kg$","difficultySource":"ai"},"ex":[{"exam":262,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Người ta dùng một lò hồ quang điện để nấu chảy một khối kim loại nặng 20 kg. Biết lò hồ quang cung cấp cho khối kim loại một nhiệt lượng không đổi là 5000 J/s. Sự thay đổi nhiệt độ của khối kim loại được ghi lại theo thời gian như hình vẽ.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044616503-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Giai đoạn AB trên đồ thị tương ứng với quá trình nóng chảy của kim loại.","answer":false},{"text":"Giai đoạn BC khối kim loại không nhận thêm nhiệt lượng từ lò nung.","answer":false},{"text":"Nhiệt dung riêng của khối kim loại là 500 J/kg.K.","answer":true},{"text":"Nhiệt nóng chảy riêng của khối kim loại là 3.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) sai<br>Giai đoạn AB, chất rắn tăng nhiệt độ.<br>b) sai<br>Giai đoạn BC, kim loại nhận nhiệt lượng và nóng chảy.<br>c) đúng<br>$Q_{AB}=Pt_{AB}=5000.50.60=15.10^6J$<br>$Q_{AB}=mc\\Delta t\\Rightarrow 15.10^6=20.c.\\left(1530−30\\right)\\Rightarrow c=500\\left(J/kg.K\\right)$<br>d) đúng<br>$Q_{BC}=Pt_{BC}=5000.\\left(70−50\\right).60=6.10^6\\left(J\\right)$<br>$\\lambda =\\frac{Q_{BC}}{m}=\\frac{6.10^6}{20}=3.10^5 J/kg$","difficultySource":"ai"}}]},{"id":523844,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong lĩnh vực y học, đồng vị phóng xạ  ${}_{53}^{131}I$ , với chu kỳ bán rã 8 ngày, được sử dụng rộng rãi trong điều trị các bệnh liên quan đến ung thư tuyến giáp. Giả sử một bệnh nhân trong liệu trình điều trị nhận được liều thuốc chứa  ${}_{53}^{131}I$ với độ phóng xạ H0 = 5.10<sup>15</sup> Bq tại thời điểm mẫu thuốc vừa được sản xuất.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044616682-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 10‒6 s‒1.","answer":true},{"text":"Số hạt nhân của chất phóng xạ tại thời điểm ban đầu là 5.10<sup>21</sup> hạt.","answer":true},{"text":"Tỉ số giữa số hạt nhân  ${}_{53}^{131}I$ còn lại và số hạt nhân  ${}_{53}^{131}I$ đã phân rã sau 24 ngày kể từ khi bệnh nhân nhận liều thuốc trên là 7.","answer":false},{"text":"Khối lượng chất phóng xạ còn lại trong cơ thể bệnh nhân bị giảm đi e lần (với e là cơ số tự nhiên) sau 11,75 ngày.","answer":false}],"explanation":"a) đúng<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8.24.60.60}\\approx 10^{−6}s^{−1}$<br>b) đúng<br>$N_0=\\frac{H_0}{\\lambda }=\\frac{5.10^{15}}{10^{−6}}\\approx 5.10^{21}$  hạt<br>c) sai<br>$\\frac{N}{\\Delta N}=\\frac{N_0.2^{−\\frac{t}{T}}}{N_0\\left(1−2^{−\\frac{t}{T}}\\right)}=\\frac{2^{−\\frac{t}{T}}}{1−2^{−\\frac{t}{T}}}=\\frac{2^{−\\frac{24}{8}}}{1−2^{−\\frac{24}{8}}}=\\frac{1}{7}$<br>d) sai<br>$\\frac{m}{m_0}=2^{−\\frac{t}{T}}\\Rightarrow e^{−1}=2^{\\frac{−t}{8}}\\Rightarrow t\\approx 11,54$  ngày","difficultySource":"ai"},"ex":[{"exam":262,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong lĩnh vực y học, đồng vị phóng xạ  ${}_{53}^{131}I$ , với chu kỳ bán rã 8 ngày, được sử dụng rộng rãi trong điều trị các bệnh liên quan đến ung thư tuyến giáp. Giả sử một bệnh nhân trong liệu trình điều trị nhận được liều thuốc chứa  ${}_{53}^{131}I$ với độ phóng xạ H0 = 5.10<sup>15</sup> Bq tại thời điểm mẫu thuốc vừa được sản xuất.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044616682-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 10‒6 s‒1.","answer":true},{"text":"Số hạt nhân của chất phóng xạ tại thời điểm ban đầu là 5.10<sup>21</sup> hạt.","answer":true},{"text":"Tỉ số giữa số hạt nhân  ${}_{53}^{131}I$ còn lại và số hạt nhân  ${}_{53}^{131}I$ đã phân rã sau 24 ngày kể từ khi bệnh nhân nhận liều thuốc trên là 7.","answer":false},{"text":"Khối lượng chất phóng xạ còn lại trong cơ thể bệnh nhân bị giảm đi e lần (với e là cơ số tự nhiên) sau 11,75 ngày.","answer":false}],"explanation":"a) đúng<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8.24.60.60}\\approx 10^{−6}s^{−1}$<br>b) đúng<br>$N_0=\\frac{H_0}{\\lambda }=\\frac{5.10^{15}}{10^{−6}}\\approx 5.10^{21}$  hạt<br>c) sai<br>$\\frac{N}{\\Delta N}=\\frac{N_0.2^{−\\frac{t}{T}}}{N_0\\left(1−2^{−\\frac{t}{T}}\\right)}=\\frac{2^{−\\frac{t}{T}}}{1−2^{−\\frac{t}{T}}}=\\frac{2^{−\\frac{24}{8}}}{1−2^{−\\frac{24}{8}}}=\\frac{1}{7}$<br>d) sai<br>$\\frac{m}{m_0}=2^{−\\frac{t}{T}}\\Rightarrow e^{−1}=2^{\\frac{−t}{8}}\\Rightarrow t\\approx 11,54$  ngày","difficultySource":"ai"}}]},{"id":523846,"nq":{"form":"bai_tap","type":"short_answer","topic":"Áp suất khí quyển theo độ cao (ôn tập)","answer":"1,1","question":"Rãnh Marianas (hay Rãnh Mariana) là một rãnh đại dương nằm ở phía tây Thái Bình Dương, cách khoảng 200 km về phía đông của quần đảo Mariana. Đây là điểm sâu nhất được biết đến trên Trái Đất, với độ sâu lớn nhất đạt tới khoảng 10,92 km. Điểm sâu nhất trong rãnh này được gọi là \"Challenger Deep\". Áp suất ở độ sâu này là a.10<sup>8</sup> Pa. Giá trị của a bằng bao nhiêu? (làm tròn đến chữ số thập phân thứ nhất). Biết áp suất khí quyển ở mặt biển là p0 = 105 Pa, khối lượng riêng của nước biển khoảng 1025 kg/m3 và lấy gia tốc trọng trường g = 9,81 $m/s^2$.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044617387-hinh-14.jpg\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp suất tại độ sâu $h$: $p=p_0+\\rho gh$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p=10^5+1025\\cdot9{,}81\\cdot10920\\approx1{,}099\\cdot10^8$ Pa.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a\\approx1{,}1$ (làm tròn đến chữ số thập phân thứ nhất).</p>","difficultySource":"ai"},"ex":[{"exam":262,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Áp suất khí quyển theo độ cao (ôn tập)","answer":"1,1","question":"Rãnh Marianas (hay Rãnh Mariana) là một rãnh đại dương nằm ở phía tây Thái Bình Dương, cách khoảng 200 km về phía đông của quần đảo Mariana. Đây là điểm sâu nhất được biết đến trên Trái Đất, với độ sâu lớn nhất đạt tới khoảng 10,92 km. Điểm sâu nhất trong rãnh này được gọi là \"Challenger Deep\". Áp suất ở độ sâu này là a.10<sup>8</sup> Pa. Giá trị của a bằng bao nhiêu? (làm tròn đến chữ số thập phân thứ nhất). Biết áp suất khí quyển ở mặt biển là p0 = 105 Pa, khối lượng riêng của nước biển khoảng 1025 kg/m3 và lấy gia tốc trọng trường g = 9,81 m/s2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044617387-hinh-14.jpg\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$+ p=p_0+Dgh=10^5+1025.9,81.10,92.10^3\\approx 1,1.10^8\\Rightarrow a\\approx 1,1$","difficultySource":"ai"}}]},{"id":523848,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"20,7","question":"Khi một chiếc bàn là hơi nước hoạt động, nước ban đầu từ bình ở nhiệt độ 270C nhỏ xuống tấm kim loại, sau đó bay hơi thành hơi nước ở 1000C. Bộ phận làm nóng có công suất điện là 1800 W. Giả sử toàn bộ năng lượng điện được truyền vào tấm kim loại, giúp duy trì nhiệt độ làm việc ổn định. Cho biết nhiệt dung riêng của nước là 4200 J/(kg.K) và nhiệt hoá hơi riêng của nước là 2,3.10<sup>6</sup> J/kg. Trong 30 giây, bàn là tạo ra bao nhiêu gam hơi nước? (làm tròn kết quả đến chữ số hàng phần mười).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044618084-hinh-16.jpg\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$Q=P.t=1800.30=54000J$<br>$Q=mc\\Delta t+mL\\Rightarrow 54000=m.4200.\\left(100−27\\right)+m.2,3.10^6$<br>$\\Rightarrow m\\approx 0,0207kg=20,7g$","difficultySource":"ai"},"ex":[{"exam":262,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"20,7","question":"Khi một chiếc bàn là hơi nước hoạt động, nước ban đầu từ bình ở nhiệt độ 270C nhỏ xuống tấm kim loại, sau đó bay hơi thành hơi nước ở 1000C. Bộ phận làm nóng có công suất điện là 1800 W. Giả sử toàn bộ năng lượng điện được truyền vào tấm kim loại, giúp duy trì nhiệt độ làm việc ổn định. Cho biết nhiệt dung riêng của nước là 4200 J/(kg.K) và nhiệt hoá hơi riêng của nước là 2,3.10<sup>6</sup> J/kg. Trong 30 giây, bàn là tạo ra bao nhiêu gam hơi nước? (làm tròn kết quả đến chữ số hàng phần mười).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791044618084-hinh-16.jpg\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$Q=P.t=1800.30=54000J$<br>$Q=mc\\Delta t+mL\\Rightarrow 54000=m.4200.\\left(100−27\\right)+m.2,3.10^6$<br>$\\Rightarrow m\\approx 0,0207kg=20,7g$","difficultySource":"ai"}}]},{"id":570383,"nq":{"form":"bai_tap","type":"true_false","topic":"Năng lượng toả ra của phản ứng hạt nhân","question":"Đồng vị mendelevium 258101Md là chất phóng xạ α có chu kì bán rã 51,5 ngày và khối lượng ban đầu là 105 g. Cho biết khối lượng của các hạt 258101Md, 42He, và hạt sản phẩm lần lượt là 258,0984 u; 4,0026 u; và 254,0880 u.  Năng lượng toả ra của phản ứng phân rã phóng xạ trên là 7,27 MeV.","difficulty":"kho","statements":[{"text":"Hạt nhân sản phẩm có 155 neutron.","answer":false},{"text":"Năng lượng toả ra trong một chu kì phóng xạ trên là 7,2.10<sup>5</sup> MeV.","answer":false},{"text":"Độ phóng xạ của mẫu 105 g của 258101Md nguyên chất là 3,81.10<sup>16</sup> Bq.","answer":true},{"text":"Số hạt 42He được phóng ra từ 105g 258101Md nguyên chất trong 60,0 ngày đầu là 1,36.10<sup>23</sup> hạt.","answer":true}],"explanation":"a) sai<br>Số neutron = A – Z = 157.<br>b) sai<br>Số hạt nhân đã bị phân rã trong một chu kì là  $\\Delta N= \\frac{N_0}{2}=\\frac{m_0}{M}.N_A=2,45.{10}^{23}hạt$<br>Năng lượng toản ra trong 1 chu kì là  $\\Delta E= \\Delta N.E_{toả}=2,45.{10}^{23}.7,27=1,78.{10}^{24} MeV$ .<br>c) đúng<br>$H_0= \\lambda .N_0= \\frac{ln2}{T}.\\frac{m_0}{M}.N_A=3,82.{10}^{16}Bq$<br>d) đúng<br>$N_{He}=\\Delta N_{Md}=\\left(1-2^{-\\frac{t}{T}}\\right)N_0=\\left(1-2^{-\\frac{60}{51,5}}\\right)N_0$ = 1,36.10<sup>23</sup>hạt.","difficultySource":"ai"},"ex":[{"exam":269,"idx":16,"el":{"form":"bai_tap","type":"true_false","topic":"Năng lượng toả ra của phản ứng hạt nhân","question":"Đồng vị mendelevium 258101Md là chất phóng xạ α có chu kì bán rã 51,5 ngày và khối lượng ban đầu là 105 g. Cho biết khối lượng của các hạt 258101Md, 42He, và hạt sản phẩm lần lượt là 258,0984 u; 4,0026 u; và 254,0880 u.  Năng lượng toả ra của phản ứng phân rã phóng xạ trên là 7,27 MeV.","difficulty":"kho","statements":[{"text":"Hạt nhân sản phẩm có 155 neutron.","answer":false},{"text":"Năng lượng toả ra trong một chu kì phóng xạ trên là 7,2.10<sup>5</sup> MeV.","answer":false},{"text":"Độ phóng xạ của mẫu 105 g của 258101Md nguyên chất là 3,81.10<sup>16</sup> Bq.","answer":true},{"text":"Số hạt 42He được phóng ra từ 105g 258101Md nguyên chất trong 60,0 ngày đầu là 1,36.10<sup>23</sup> hạt.","answer":true}],"explanation":"a) sai<br>Số neutron = A – Z = 157.<br>b) sai<br>Số hạt nhân đã bị phân rã trong một chu kì là  $\\Delta N= \\frac{N_0}{2}=\\frac{m_0}{M}.N_A=2,45.{10}^{23}hạt$<br>Năng lượng toản ra trong 1 chu kì là  $\\Delta E= \\Delta N.E_{toả}=2,45.{10}^{23}.7,27=1,78.{10}^{24} MeV$ .<br>c) đúng<br>$H_0= \\lambda .N_0= \\frac{ln2}{T}.\\frac{m_0}{M}.N_A=3,82.{10}^{16}Bq$<br>d) đúng<br>$N_{He}=\\Delta N_{Md}=\\left(1-2^{-\\frac{t}{T}}\\right)N_0=\\left(1-2^{-\\frac{60}{51,5}}\\right)N_0$ = 1,36.10<sup>23</sup>hạt.","difficultySource":"ai"}}]},{"id":570385,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính nhiệt lượng theo nhiệt dung riêng","question":"Một ấm điện có công suất 1000 W chứa 300 g nước ở 20°C được đun đến khi sôi ở 100oC. Cho nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4,2.10<sup>3</sup> J/kg.K; 2,26.10<sup>6</sup> J/kg. Bỏ qua hao phí nhiệt ra môi trường và nhiệt lượng thu của vỏ ấm.","difficulty":"trung-binh","statements":[{"text":"Nhiệt lượng chỉ để làm nóng 300 g nước từ 200C đến 1000C là 100800 J.","answer":true},{"text":"Nhiệt lượng cần cung cấp để 200 g nước hóa hơi hoàn toàn ở 1000C là 678.106 J.","answer":false},{"text":"Thời gian cần thiết để đun nước trong ấm đạt đến nhiệt độ sôi là 100,8 phút.","answer":false},{"text":"Sau khi nước đến nhiệt độ sôi, người ta để ấm tiếp tục đun nước sôi trong 226 s. Khối lượng nước còn lại trong ấm là 100 g.","answer":false}],"explanation":"a) đúng<br>$Q_{thu}=mc\\Delta t= 100800 J$ .<br>b) sai<br>Q = L.m = 452000 J.<br>c) sai<br>$Q=A=P.t\\rightarrow t=\\frac{A}{P}=452 s=7,53 phút.$<br>d) sai<br>$Q=P.t=L.m\\rightarrow m=\\frac{P.t}{L}=0,1 kg$<br>Khối lượng nước còn lại là m’ = 0,3 – 0,1 = 0,2 kg.","difficultySource":"ai"},"ex":[{"exam":269,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Tính nhiệt lượng theo nhiệt dung riêng","question":"Một ấm điện có công suất 1000 W chứa 300 g nước ở 20°C được đun đến khi sôi ở 100oC. Cho nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4,2.10<sup>3</sup> J/kg.K; 2,26.10<sup>6</sup> J/kg. Bỏ qua hao phí nhiệt ra môi trường và nhiệt lượng thu của vỏ ấm.","difficulty":"trung-binh","statements":[{"text":"Nhiệt lượng chỉ để làm nóng 300 g nước từ 200C đến 1000C là 100800 J.","answer":true},{"text":"Nhiệt lượng cần cung cấp để 200 g nước hóa hơi hoàn toàn ở 1000C là 678.106 J.","answer":false},{"text":"Thời gian cần thiết để đun nước trong ấm đạt đến nhiệt độ sôi là 100,8 phút.","answer":false},{"text":"Sau khi nước đến nhiệt độ sôi, người ta để ấm tiếp tục đun nước sôi trong 226 s. Khối lượng nước còn lại trong ấm là 100 g.","answer":false}],"explanation":"a) đúng<br>$Q_{thu}=mc\\Delta t= 100800 J$ .<br>b) sai<br>Q = L.m = 452000 J.<br>c) sai<br>$Q=A=P.t\\rightarrow t=\\frac{A}{P}=452 s=7,53 phút.$<br>d) sai<br>$Q=P.t=L.m\\rightarrow m=\\frac{P.t}{L}=0,1 kg$<br>Khối lượng nước còn lại là m’ = 0,3 – 0,1 = 0,2 kg.","difficultySource":"ai"}}]},{"id":570394,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":2,"options":["775,6W","776,5kW","776,5W","775,6kW"],"question":"Đổ 1,5 lít nước ở 200C vào một ấm nhôm có khối lượng 600g, ở cùng nhiệt độ 200C và sau đó đun bằng bếp điện. Sau 35 phút thì đã có 20% khối lượng nước đã hóa hơi ở nhiệt độ sôi 1000C.  Biết rằng 75% nhiệt lượng mà bếp cung cấp được dùng vào việc đun nước. Cho biết nhiệt dung riêng của nước là 4190J/kg.K, của nhôm là 880J/kgK nhiệt hóa hơi của nước ở 1000C là 2,26.10<sup>6</sup>J/kg, khối lượng riêng của nước là 1kg/l. Công suất cung cấp nhiệt của bếp điện là","difficulty":"kho","explanation":"Nhiệt lượng cung cấp để đun nước:<br>$Q_{ci}=c_nm_n\\left(t_2−t_1\\right)+c_bm_b\\left(t_2−t_1\\right)+Lm_n.20%$  $\\rightarrow Q_{ci}=1223040J$<br>Nhiệt lượng toàn phần ấm đã cung cấp: $Q_{tp}=\\frac{Q_{ci}}{H}=1630720J$<br>Công suất cung cấp nhiệt của ấm:  $P=\\frac{Q_{tp}}{t}=776,5 W$","difficultySource":"ai"},"ex":[{"exam":270,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":2,"options":["775,6W","776,5kW","776,5W","775,6kW"],"question":"Đổ 1,5 lít nước ở 200C vào một ấm nhôm có khối lượng 600g, ở cùng nhiệt độ 200C và sau đó đun bằng bếp điện. Sau 35 phút thì đã có 20% khối lượng nước đã hóa hơi ở nhiệt độ sôi 1000C.  Biết rằng 75% nhiệt lượng mà bếp cung cấp được dùng vào việc đun nước. Cho biết nhiệt dung riêng của nước là 4190J/kg.K, của nhôm là 880J/kgK nhiệt hóa hơi của nước ở 1000C là 2,26.10<sup>6</sup>J/kg, khối lượng riêng của nước là 1kg/l. Công suất cung cấp nhiệt của bếp điện là","difficulty":"kho","explanation":"Nhiệt lượng cung cấp để đun nước:<br>$Q_{ci}=c_nm_n\\left(t_2−t_1\\right)+c_bm_b\\left(t_2−t_1\\right)+Lm_n.20%$  $\\rightarrow Q_{ci}=1223040J$<br>Nhiệt lượng toàn phần ấm đã cung cấp: $Q_{tp}=\\frac{Q_{ci}}{H}=1630720J$<br>Công suất cung cấp nhiệt của ấm:  $P=\\frac{Q_{tp}}{t}=776,5 W$","difficultySource":"ai"}}]},{"id":570398,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["1,6(l)","2,6(l)","4,6(l)","3,51(l)"],"question":"Vận động viên điền kinh bị mất rất nhiều nước trong khi thi đấu. Các vận động viên thường chỉ có thể chuyển hoá khoảng 22% năng lượng dự trữ trong cơ thể thành năng lượng dùng cho các hoạt động của cơ thể. Phần năng lượng còn lại chuyển thành nhiệt thải ra ngoài nhờ sự bay hơi của nước qua hô hấp và da để giữ cho nhiệt độ cơ thể không đổi. Nếu vận động viên dùng hết 10800kJ trong cuộc thi thì có khoảng bao nhiêu lít nước đã thoát ra ngoài cơ thể? Coi nhiệt độ cơ thể của vận động viên hoàn toàn không đổi và nhiệt hoá hơi riêng của nước ở nhiệt độ của vận động viên là 2,4.10<sup>6</sup>J/kg. Biết khối lượng riêng của nước là 1,0.10<sup>3</sup>kg/m3.","difficulty":"trung-binh","explanation":"Ta có:  $\\rho =\\frac{m}{V}\\Rightarrow m=\\rho V$<br>Phần năng lượng dùng để bay hơi nước:<br>$Q=Q_{tp}.H=\\left(10800.10^3\\right).0,78=8424000J$<br>Mặt khác: $Q=mL=V\\rho L$   $\\rightarrow V=\\frac{Q}{\\rho L}=\\frac{8424000}{1000.2,4.10^6}=3,51.10^{−3} m^3\\rightarrow V=3,51l$","difficultySource":"ai"},"ex":[{"exam":270,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["1,6(l)","2,6(l)","4,6(l)","3,51(l)"],"question":"Vận động viên điền kinh bị mất rất nhiều nước trong khi thi đấu. Các vận động viên thường chỉ có thể chuyển hoá khoảng 22% năng lượng dự trữ trong cơ thể thành năng lượng dùng cho các hoạt động của cơ thể. Phần năng lượng còn lại chuyển thành nhiệt thải ra ngoài nhờ sự bay hơi của nước qua hô hấp và da để giữ cho nhiệt độ cơ thể không đổi. Nếu vận động viên dùng hết 10800kJ trong cuộc thi thì có khoảng bao nhiêu lít nước đã thoát ra ngoài cơ thể? Coi nhiệt độ cơ thể của vận động viên hoàn toàn không đổi và nhiệt hoá hơi riêng của nước ở nhiệt độ của vận động viên là 2,4.10<sup>6</sup>J/kg. Biết khối lượng riêng của nước là 1,0.10<sup>3</sup>kg/m3.","difficulty":"trung-binh","explanation":"Ta có:  $\\rho =\\frac{m}{V}\\Rightarrow m=\\rho V$<br>Phần năng lượng dùng để bay hơi nước:<br>$Q=Q_{tp}.H=\\left(10800.10^3\\right).0,78=8424000J$<br>Mặt khác: $Q=mL=V\\rho L$   $\\rightarrow V=\\frac{Q}{\\rho L}=\\frac{8424000}{1000.2,4.10^6}=3,51.10^{−3} m^3\\rightarrow V=3,51l$","difficultySource":"ai"}}]},{"id":570411,"nq":{"form":"bai_tap","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Trong chẩn đoán bệnh bằng cộng hưởng từ, người được chụp nằm trong từ trường hướng dọc cơ thể, từ đầu đến chân. Một người được chụp đã quên tháo vòng tay của mình. Vòng tay này bằng kim loại có đường kính 6 cm và có điện trở 0,01 $\\Omega$ . Giả sử mặt phẳng của vòng tay vuông góc với cảm ứng từ và khi chụp từ trường của máy giảm từ 1,5 (T) xuống 0,3 (T) trong 1,2 s.","difficulty":"kho","statements":[{"text":"Cường độ dòng điện cảm ứng sinh ra trong vòng tay do thay đổi từ trường của máy cộng hưởng từ khi chụp là 0,2826 A.","answer":true},{"text":"Độ biến thiên của cảm ứng từ trong thời gian 1,2 s có độ lớn là 1,2(T).","answer":true},{"text":"Tốc độ biến thiên từ thông qua vòng tay có độ lớn là 2,26.10<sup>−3</sup> Wb/s","answer":false},{"text":"Khi chụp cộng hưởng từ, không nên đeo các đồ dùng bằng kim loại vì dòng điện cảm ứng trong các đồ dùng ấy có thể ảnh hưởng đến kết quả đo của máy.","answer":false}],"explanation":"a) đúng<br>$I=\\frac{N.S.\\Delta B}{\\Delta t.R}=\\frac{1.3,14.3^2.10^{−4}(1,5−0,3)}{1,2.0,01}=0,2826A$<br>b) đúng<br>c) sai<br>Tốc độ biến thiên từ thông  $\\frac{N.S.\\Delta B}{\\Delta t}=\\frac{3,14.3^2.10^{−4}(1,5−0,3)}{1,2}=2,826.10^{−3}Wb/s$<br>d) đúng","difficultySource":"ai"},"ex":[{"exam":270,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Trong chẩn đoán bệnh bằng cộng hưởng từ, người được chụp nằm trong từ trường hướng dọc cơ thể, từ đầu đến chân. Một người được chụp đã quên tháo vòng tay của mình. Vòng tay này bằng kim loại có đường kính 6 cm và có điện trở 0,01 $\\Omega$ . Giả sử mặt phẳng của vòng tay vuông góc với cảm ứng từ và khi chụp từ trường của máy giảm từ 1,5 (T) xuống 0,3 (T) trong 1,2 s.","difficulty":"kho","statements":[{"text":"Cường độ dòng điện cảm ứng sinh ra trong vòng tay do thay đổi từ trường của máy cộng hưởng từ khi chụp là 0,2826 A.","answer":true},{"text":"Độ biến thiên của cảm ứng từ trong thời gian 1,2 s có độ lớn là 1,2(T).","answer":true},{"text":"Tốc độ biến thiên từ thông qua vòng tay có độ lớn là 2,26.10<sup>−3</sup> Wb/s","answer":false},{"text":"Khi chụp cộng hưởng từ, không nên đeo các đồ dùng bằng kim loại vì dòng điện cảm ứng trong các đồ dùng ấy có thể ảnh hưởng đến kết quả đo của máy.","answer":false}],"explanation":"a) đúng<br>$I=\\frac{N.S.\\Delta B}{\\Delta t.R}=\\frac{1.3,14.3^2.10^{−4}(1,5−0,3)}{1,2.0,01}=0,2826A$<br>b) đúng<br>c) sai<br>Tốc độ biến thiên từ thông  $\\frac{N.S.\\Delta B}{\\Delta t}=\\frac{3,14.3^2.10^{−4}(1,5−0,3)}{1,2}=2,826.10^{−3}Wb/s$<br>d) đúng","difficultySource":"ai"}}]},{"id":570416,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng áp và định luật Charles","answer":"3,9","question":"Một chiếc xe tải vượt qua một sa mạc. Chuyến đi bắt đầu vào sáng sớm khi nhiệt độ là 3,0°C. Thể tích khí chứa trong mỗi lốp xe là 1,50 m³ và áp suất trong các lốp xe là 3,42. 10<sup>5</sup> Pa. Coi khí trong lốp xe là khí lí tưởng, có nhiệt độ như nhiệt độ ngoài trời, khí không thoát ra ngoài và thể tích lốp không thay đổi. Đến giữa trưa, nhiệt độ tăng lên đến 42°C, áp suất trong lốp là n.105 Pa. Tính giá trị của n (viết kết quả làm tròn đến một chữ số sau dấu phấy thập phân)?","difficulty":"de","explanation":"Áp dụng định luật Charles  $\\frac{p}{T}=const\\Rightarrow \\frac{3,42.10^5}{3+273}=\\frac{p_2}{42+273}\\Rightarrow p_2\\approx 3,9.10^5 Pa.$","difficultySource":"ai"},"ex":[{"exam":270,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng áp và định luật Charles","answer":"3,9","question":"Một chiếc xe tải vượt qua một sa mạc. Chuyến đi bắt đầu vào sáng sớm khi nhiệt độ là 3,0°C. Thể tích khí chứa trong mỗi lốp xe là 1,50 m³ và áp suất trong các lốp xe là 3,42. 10<sup>5</sup> Pa. Coi khí trong lốp xe là khí lí tưởng, có nhiệt độ như nhiệt độ ngoài trời, khí không thoát ra ngoài và thể tích lốp không thay đổi. Đến giữa trưa, nhiệt độ tăng lên đến 42°C, áp suất trong lốp là n.105 Pa. Tính giá trị của n (viết kết quả làm tròn đến một chữ số sau dấu phấy thập phân)?","difficulty":"de","explanation":"Áp dụng định luật Charles  $\\frac{p}{T}=const\\Rightarrow \\frac{3,42.10^5}{3+273}=\\frac{p_2}{42+273}\\Rightarrow p_2\\approx 3,9.10^5 Pa.$","difficultySource":"ai"}}]},{"id":571215,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":2,"options":["6,02.10<sup>23</sup>.","4,05.10<sup>23</sup>.","3,01.10<sup>23</sup>.","1,50.10<sup>23</sup>."],"question":"Biết khối lượng mol của hydrogen (H2) là 2 g/mol. Trong 1 g khí hydrogen có số phân tử là","difficulty":"de","explanation":"Khối lượng mol của H₂ là 2 g/mol.<br>Trong 1 g H₂ có số mol:  $n=\\frac{1}{2}=0,5mol$<br>Số phân tử là: N = nNA = 0,5.6,02.10<sup>23</sup> = 3,01.10<sup>23</sup>","difficultySource":"ai"},"ex":[{"exam":271,"idx":2,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":2,"options":["6,02.10<sup>23</sup>.","4,05.10<sup>23</sup>.","3,01.10<sup>23</sup>.","1,50.10<sup>23</sup>."],"question":"Biết khối lượng mol của hydrogen (H2) là 2 g/mol. Trong 1 g khí hydrogen có số phân tử là","difficulty":"de","explanation":"Khối lượng mol của H₂ là 2 g/mol.<br>Trong 1 g H₂ có số mol:  $n=\\frac{1}{2}=0,5mol$<br>Số phân tử là: N = nNA = 0,5.6,02.10<sup>23</sup> = 3,01.10<sup>23</sup>","difficultySource":"ai"}}]},{"id":571220,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":1,"options":["10,28.10<sup>−3</sup> V.","12,56.10<sup>−3</sup> V.","25,68.10<sup>−3</sup> V.","37,68.10<sup>−3</sup> V."],"question":"Một máy phát điện xoay chiều (như hình vẽ) có khung dây phẳng gồm 50 vòng dây, mỗi vòng dây có diện tích 2,0 cm2. Khung dây quay trong một từ trường đều có độ lớn cảm ứng từ là 0,02 T và hướng vuông góc với trục quay, tốc độ quay ổn định là 30 vòng/giây. Suất điện động cảm ứng cực đại qua khung dây có giá trị là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045268004-hinh-1.jpg\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Suất điện động cảm ứng cực đại của máy phát điện xoay chiều:<br>E0 = NBSω<br>Trong đó:<br>N = 50<br>S = 2,0 cm2 = 2,0.10<sup>−4</sup> m2<br>B = 0,02T<br>f = 30 vòng/s nên:<br>ω = 2πf = 2.3,14.30 = 188,4 rad/s<br>Suy ra:<br>E0 = 50.0,02.2,0.10-4.188,4<br>E0 = 0,03768V = 37,68.10<sup>−3</sup> V","difficultySource":"ai"},"ex":[{"exam":271,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":1,"options":["10,28.10<sup>−3</sup> V.","12,56.10<sup>−3</sup> V.","25,68.10<sup>−3</sup> V.","37,68.10<sup>−3</sup> V."],"question":"Một máy phát điện xoay chiều (như hình vẽ) có khung dây phẳng gồm 50 vòng dây, mỗi vòng dây có diện tích 2,0 cm2. Khung dây quay trong một từ trường đều có độ lớn cảm ứng từ là 0,02 T và hướng vuông góc với trục quay, tốc độ quay ổn định là 30 vòng/giây. Suất điện động cảm ứng cực đại qua khung dây có giá trị là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045268004-hinh-1.jpg\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Suất điện động cảm ứng cực đại của máy phát điện xoay chiều:<br>E0 = NBSω<br>Trong đó:<br>N = 50<br>S = 2,0 cm2 = 2,0.10<sup>−4</sup> m2<br>B = 0,02T<br>f = 30 vòng/s nên:<br>ω = 2πf = 2.3,14.30 = 188,4 rad/s<br>Suy ra:<br>E0 = 50.0,02.2,0.10-4.188,4<br>E0 = 0,03768V = 37,68.10<sup>−3</sup> V","difficultySource":"ai"}}]},{"id":571231,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Dùng bếp điện để đun một ấm nhôm khối lượng 600 g đựng 1,5 lít nước ở nhiệt độ 200C. Sau 35 phút đã có 20% lượng nước trong ấm hóa hơi ở nhiệt độ 1000C và chỉ có 75% nhiệt lượng mà bếp tỏa ra được dùng vào việc đun ấm nước. Biết nhiệt dung riêng của nhôm là 880 J/kg.K, của nước là 4200 J/kg.K, nhiệt hóa hơi riêng của nước sôi 1000C là 2,26.10<sup>6</sup> J/kg, khối lượng riêng của nước là 1 kg/lít.","difficulty":"kho","statements":[{"text":"Nhiệt lượng trung bình mà bếp tỏa ra trong mỗi giây trong quá trình đun ấm nước là 582,97 J/s.","answer":false},{"text":"Nhiệt lượng bếp cung cấp cho nước tăng từ 200C lên 1000C là 540.000 J.","answer":false},{"text":"Nhiệt lượng bếp cung cấp cho ấm nhôm tăng từ 200C lên 1000C là 42.240 J.","answer":true},{"text":"Nhiệt hóa hơi riêng xác định bằng công thức L = Q/m.","answer":true}],"explanation":"Dữ kiện:<br>mAl = 600 g = 0,6 kg<br>mnuoc =1,5 lít = 1,5 kg<br>t1 = 200C , t2 = 1000C<br>∆t = 800C cAl = 880 J / kg.K<br>cnuoc = 4200 J / kg.K<br>L = 2,26.10<sup>6</sup> J / kg<br>Lượng nước hóa hơi: mhh = 20%.1,5 = 0,3 kg<br>Thời gian đun:<br>35 phút = 2100 s<br>a) sai<br>Nhiệt lượng dùng để đun nóng nước:<br>Q1 = mnuoccnuoc∆t =1,5.4200.80 = 504000 J<br>Nhiệt lượng dùng để đun nóng ấm nhôm:<br>Q2 = mAlcAl∆t = 0,6.880.80 = 42240 J<br>Nhiệt lượng dùng để hóa hơi nước:<br>Q3 = mhhL = 0,3.2,26.10<sup>6</sup> = 678000 J<br>Tổng nhiệt lượng có ích:<br>Qích = 504000 + 42240 = 678000 = 1224240 J<br>Vì chỉ có 75% nhiệt lượng bếp tỏa ra được dùng vào việc đun ấm nước nên:<br>$Q_{bep}=\\frac{Q_{ich}}{0,75}=\\frac{1224240}{0,75}=1632320J$<br>Công suất trung bình của bếp:<br>$P=\\frac{Q_{bep}}{t}=\\frac{1632320}{2100}\\approx 777,3J/s$<br>Mệnh đề cho 582,97 J / s là giá trị của   $\\frac{Q_{ich}}{2100}$  , chưa tính hiệu suất.<br>b) sai<br>Nhiệt lượng cung cấp cho nước tăng từ 200C lên 1000C là:<br>Q1 = mnuoccnuoc∆t<br>Q1 = 1,5.4200.80 = 504000 J<br>Mệnh đề nói 540000 J nên sai.<br>c) đúng<br>Nhiệt lượng cung cấp cho ấm nhôm tăng từ 200C lên 1000C :<br>Q2 = mAlcAl∆t<br>Q2 = 0,6.880.80 = 42240 J<br>d) đúng<br>Nhiệt hóa hơi riêng được xác định bởi công thức:  $L=\\frac{Q}{m}$<br>Trong đó Q là nhiệt lượng cần để hóa hơi hoàn toàn khối lượng m chất lỏng ở nhiệt độ sôi.","difficultySource":"ai"},"ex":[{"exam":271,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Dùng bếp điện để đun một ấm nhôm khối lượng 600 g đựng 1,5 lít nước ở nhiệt độ 200C. Sau 35 phút đã có 20% lượng nước trong ấm hóa hơi ở nhiệt độ 1000C và chỉ có 75% nhiệt lượng mà bếp tỏa ra được dùng vào việc đun ấm nước. Biết nhiệt dung riêng của nhôm là 880 J/kg.K, của nước là 4200 J/kg.K, nhiệt hóa hơi riêng của nước sôi 1000C là 2,26.10<sup>6</sup> J/kg, khối lượng riêng của nước là 1 kg/lít.","difficulty":"kho","statements":[{"text":"Nhiệt lượng trung bình mà bếp tỏa ra trong mỗi giây trong quá trình đun ấm nước là 582,97 J/s.","answer":false},{"text":"Nhiệt lượng bếp cung cấp cho nước tăng từ 200C lên 1000C là 540.000 J.","answer":false},{"text":"Nhiệt lượng bếp cung cấp cho ấm nhôm tăng từ 200C lên 1000C là 42.240 J.","answer":true},{"text":"Nhiệt hóa hơi riêng xác định bằng công thức L = Q/m.","answer":true}],"explanation":"Dữ kiện:<br>mAl = 600 g = 0,6 kg<br>mnuoc =1,5 lít = 1,5 kg<br>t1 = 200C , t2 = 1000C<br>∆t = 800C cAl = 880 J / kg.K<br>cnuoc = 4200 J / kg.K<br>L = 2,26.10<sup>6</sup> J / kg<br>Lượng nước hóa hơi: mhh = 20%.1,5 = 0,3 kg<br>Thời gian đun:<br>35 phút = 2100 s<br>a) sai<br>Nhiệt lượng dùng để đun nóng nước:<br>Q1 = mnuoccnuoc∆t =1,5.4200.80 = 504000 J<br>Nhiệt lượng dùng để đun nóng ấm nhôm:<br>Q2 = mAlcAl∆t = 0,6.880.80 = 42240 J<br>Nhiệt lượng dùng để hóa hơi nước:<br>Q3 = mhhL = 0,3.2,26.10<sup>6</sup> = 678000 J<br>Tổng nhiệt lượng có ích:<br>Qích = 504000 + 42240 = 678000 = 1224240 J<br>Vì chỉ có 75% nhiệt lượng bếp tỏa ra được dùng vào việc đun ấm nước nên:<br>$Q_{bep}=\\frac{Q_{ich}}{0,75}=\\frac{1224240}{0,75}=1632320J$<br>Công suất trung bình của bếp:<br>$P=\\frac{Q_{bep}}{t}=\\frac{1632320}{2100}\\approx 777,3J/s$<br>Mệnh đề cho 582,97 J / s là giá trị của   $\\frac{Q_{ich}}{2100}$  , chưa tính hiệu suất.<br>b) sai<br>Nhiệt lượng cung cấp cho nước tăng từ 200C lên 1000C là:<br>Q1 = mnuoccnuoc∆t<br>Q1 = 1,5.4200.80 = 504000 J<br>Mệnh đề nói 540000 J nên sai.<br>c) đúng<br>Nhiệt lượng cung cấp cho ấm nhôm tăng từ 200C lên 1000C :<br>Q2 = mAlcAl∆t<br>Q2 = 0,6.880.80 = 42240 J<br>d) đúng<br>Nhiệt hóa hơi riêng được xác định bởi công thức:  $L=\\frac{Q}{m}$<br>Trong đó Q là nhiệt lượng cần để hóa hơi hoàn toàn khối lượng m chất lỏng ở nhiệt độ sôi.","difficultySource":"ai"}}]},{"id":571233,"nq":{"form":"bai_tap","type":"true_false","topic":"Năng lượng toả ra của phản ứng hạt nhân","question":"Người ta cần tổng hợp 1 mol 42He từ phản ứng hạt nhân:  ${}_1^1H+_3^7Li\\rightarrow_2^4He+X$ . Biết khối lượng của các hạt nhân  ${}_1^1H;_3^7Li;_2^4He$ lần lượt là 1,0073 amu, 7,0144 amu và 4,0015 amu. Cho 1 amu = 931,5 MeV/c2.","difficulty":"kho","statements":[{"text":"Số phản ứng cần thiết là 6,02.10<sup>23</sup>.","answer":false},{"text":"Hạt nhân X là ${}_2^4{He}$ .","answer":true},{"text":"Mỗi phản ứng tỏa năng lượng là 0,0187 MeV.","answer":false},{"text":"Năng lượng tỏa ra khi tổng hợp được 1 mol  ${}_2^4{He}$  xấp xỉ là 5,24.10<sup>24</sup> MeV.","answer":true}],"explanation":"Phản ứng hạt nhân:  ${}_1^1H+_3^7Li\\rightarrow_2^4He+X$<br>Bảo toàn số khối và điện tích:<br>Vế trái có:<br>A = 1 + 7 = 8<br>Z = 1 + 3 = 4<br>Vế phải đã có hạt ${}_2^4{He}$ , nên hạt X phải có:<br>$A_X=8−4=4$<br>$Z_X=4−2=2$<br>Vậy: X =  ${}_2^4{He}$<br>Phản ứng thực chất là:  ${}_1^1H+_3^7Li\\rightarrow_2^4He+_2^4He$<br>a) sai<br>Mỗi phản ứng tạo ra 2 hạt nhân  ${}_2^4{He}$ .<br>Muốn tổng hợp 1 mol  ${}_2^4{He}$ thì cần số hạt helium là:<br>NA = 6,02.10<sup>23</sup> hạt<br>Vì mỗi phản ứng tạo 2 hạt helium nên số phản ứng cần thiết là:<br>$N=\\frac{N_A}{2}=3,01.10^{23}$ phản ứng<br>Mệnh đề nói 6,02.10<sup>23</sup> phản ứng nên sai.<br>b) đúng<br>Như đã bảo toàn số khối và điện tích ở trên:<br>X =  ${}_2^4{He}$<br>c) sai<br>Khối lượng trước phản ứng:<br>mtruoc = 1,0073 + 7,0144 = 8,0217 amu<br>Khối lượng sau phản ứng:<br>msau = 4,0015 + 4,0015 = 8,0030 amu<br>Độ hụt khối của phản ứng:<br>∆m = mtruoc - msau = 8,0217 - 8,0030 = 0,0187 amu<br>Năng lượng tỏa ra mỗi phản ứng:<br>E = ∆m.c2 = 0,0187.931,5 = 17,42 MeV<br>Mệnh đề nói 0,0187 MeV nên sai.<br>Giá trị 0,0187 là độ hụt khối theo đơn vị amu, không phải năng lượng MeV.<br>d) đúng<br>Số phản ứng cần để tổng hợp 1 mol  ${}_2^4{He}$ là:<br>$N=\\frac{6,02.10^{23}}{2}=3,01.10^{23}$<br>Năng lượng tỏa ra mỗi phản ứng:<br>E1  $\\approx$  17,42 MeV<br>Tổng năng lượng tỏa ra:<br>E =  N.E1<br>E = 3,01.1023.17,42  $\\approx$  5,24.10<sup>24</sup> MeV","difficultySource":"ai"},"ex":[{"exam":271,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Năng lượng toả ra của phản ứng hạt nhân","question":"Người ta cần tổng hợp 1 mol 42He từ phản ứng hạt nhân:  ${}_1^1H+_3^7Li\\rightarrow_2^4He+X$ . Biết khối lượng của các hạt nhân  ${}_1^1H;_3^7Li;_2^4He$ lần lượt là 1,0073 amu, 7,0144 amu và 4,0015 amu. Cho 1 amu = 931,5 MeV/c2.","difficulty":"kho","statements":[{"text":"Số phản ứng cần thiết là 6,02.10<sup>23</sup>.","answer":false},{"text":"Hạt nhân X là ${}_2^4{He}$ .","answer":true},{"text":"Mỗi phản ứng tỏa năng lượng là 0,0187 MeV.","answer":false},{"text":"Năng lượng tỏa ra khi tổng hợp được 1 mol  ${}_2^4{He}$  xấp xỉ là 5,24.10<sup>24</sup> MeV.","answer":true}],"explanation":"Phản ứng hạt nhân:  ${}_1^1H+_3^7Li\\rightarrow_2^4He+X$<br>Bảo toàn số khối và điện tích:<br>Vế trái có:<br>A = 1 + 7 = 8<br>Z = 1 + 3 = 4<br>Vế phải đã có hạt ${}_2^4{He}$ , nên hạt X phải có:<br>$A_X=8−4=4$<br>$Z_X=4−2=2$<br>Vậy: X =  ${}_2^4{He}$<br>Phản ứng thực chất là:  ${}_1^1H+_3^7Li\\rightarrow_2^4He+_2^4He$<br>a) sai<br>Mỗi phản ứng tạo ra 2 hạt nhân  ${}_2^4{He}$ .<br>Muốn tổng hợp 1 mol  ${}_2^4{He}$ thì cần số hạt helium là:<br>NA = 6,02.10<sup>23</sup> hạt<br>Vì mỗi phản ứng tạo 2 hạt helium nên số phản ứng cần thiết là:<br>$N=\\frac{N_A}{2}=3,01.10^{23}$ phản ứng<br>Mệnh đề nói 6,02.10<sup>23</sup> phản ứng nên sai.<br>b) đúng<br>Như đã bảo toàn số khối và điện tích ở trên:<br>X =  ${}_2^4{He}$<br>c) sai<br>Khối lượng trước phản ứng:<br>mtruoc = 1,0073 + 7,0144 = 8,0217 amu<br>Khối lượng sau phản ứng:<br>msau = 4,0015 + 4,0015 = 8,0030 amu<br>Độ hụt khối của phản ứng:<br>∆m = mtruoc - msau = 8,0217 - 8,0030 = 0,0187 amu<br>Năng lượng tỏa ra mỗi phản ứng:<br>E = ∆m.c2 = 0,0187.931,5 = 17,42 MeV<br>Mệnh đề nói 0,0187 MeV nên sai.<br>Giá trị 0,0187 là độ hụt khối theo đơn vị amu, không phải năng lượng MeV.<br>d) đúng<br>Số phản ứng cần để tổng hợp 1 mol  ${}_2^4{He}$ là:<br>$N=\\frac{6,02.10^{23}}{2}=3,01.10^{23}$<br>Năng lượng tỏa ra mỗi phản ứng:<br>E1  $\\approx$  17,42 MeV<br>Tổng năng lượng tỏa ra:<br>E =  N.E1<br>E = 3,01.1023.17,42  $\\approx$  5,24.10<sup>24</sup> MeV","difficultySource":"ai"}}]},{"id":571261,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","question":"Một nhà máy điện nguyên tử tiêu thụ trung bình 58,75 g  ${}_{92}^{235}U$ mỗi ngày. Biết hiệu suất của nhà máy là 25%; mỗi hạt nhân nguyên tử phân hạch giải phóng 200 MeV và trung bình có 2,5 neutron được giải phóng.<br>Cho NA = 6,02.10<sup>23</sup> hạt/mol; 1 MeV = 1,6.10<sup>−13</sup>J.","difficulty":"trung-binh","statements":[{"text":"Mỗi ngày, nhà máy điện nguyên tử đó tiêu thụ trung bình 1,505.10<sup>23</sup> nguyên tử  ${}_{92}^{235}U$","answer":true},{"text":"Năng lượng giải phóng do phân hạch của 58,75 g 235U bằng 3,01.1025 J.","answer":false},{"text":"Công suất phát điện của nhà máy xấp xỉ bằng 13,94 MW.","answer":true},{"text":"Số neutron thu được trong lò phản ứng là 2,2575.10<sup>23</sup> hạt.","answer":true}],"explanation":"a) đúng<br>a)\tSố nguyên tử chứa trong 58,75 g  ${}_{92}^{235}U$ :<br>$N=n.N_A=\\frac{m}{M}.N_A=\\frac{58,75}{235}.6,02.10^{23}=$ =1,505.10<sup>23</sup> nguyên tử  ${}_{92}^{235}U$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>b)\tMỗi hạt nhân nguyên tử phân hạch giải phóng 200 MeV.<br>Năng lượng giải phóng do phân hạch của 58,75 g 235U:<br>W = N.200 MeV = 1,505.1023.200 = 3,01.10<sup>25</sup> MeV =  4,816.10<sup>12</sup> J.<br>c) đúng<br>Công suất tỏa nhiệt do phân hạch của 58,75 g 235U:  $P_{toa}=\\frac{W}{t}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Công suất phát điện của nhà máy:<br>$P=255.P_{toa}=25%.\\frac{W}{t}=25%.\\frac{4,816.10^{12}}{24.3600}\\approx 13,94.10^6W=13,94\\left(MW\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Số neutron được giải phóng do 58,75 g 235U:<br>𝑁1 = 𝑁.2,5 = 1,505.1023.2,5 = 3,7625.10<sup>23</sup> hạt.<br>$Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Số neutorn bị hấp thụ để 58,75 g 235U phân hạch hết:<br>𝑁2 = 𝑁 = 1,505.10<sup>23</sup> hạt.<br>Số neutron thu được trong lò phản ứng:<br>N = 𝑁1 − 𝑁2 = 3,7625.10<sup>23</sup> −1,505.10<sup>23</sup> = 2,2575.10<sup>23</sup> hạt.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":272,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","question":"Một nhà máy điện nguyên tử tiêu thụ trung bình 58,75 g  ${}_{92}^{235}U$ mỗi ngày. Biết hiệu suất của nhà máy là 25%; mỗi hạt nhân nguyên tử phân hạch giải phóng 200 MeV và trung bình có 2,5 neutron được giải phóng.<br>Cho NA = 6,02.10<sup>23</sup> hạt/mol; 1 MeV = 1,6.10<sup>−13</sup>J.","difficulty":"trung-binh","statements":[{"text":"Mỗi ngày, nhà máy điện nguyên tử đó tiêu thụ trung bình 1,505.10<sup>23</sup> nguyên tử  ${}_{92}^{235}U$","answer":true},{"text":"Năng lượng giải phóng do phân hạch của 58,75 g 235U bằng 3,01.1025 J.","answer":false},{"text":"Công suất phát điện của nhà máy xấp xỉ bằng 13,94 MW.","answer":true},{"text":"Số neutron thu được trong lò phản ứng là 2,2575.10<sup>23</sup> hạt.","answer":true}],"explanation":"a) đúng<br>a)\tSố nguyên tử chứa trong 58,75 g  ${}_{92}^{235}U$ :<br>$N=n.N_A=\\frac{m}{M}.N_A=\\frac{58,75}{235}.6,02.10^{23}=$ =1,505.10<sup>23</sup> nguyên tử  ${}_{92}^{235}U$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>b)\tMỗi hạt nhân nguyên tử phân hạch giải phóng 200 MeV.<br>Năng lượng giải phóng do phân hạch của 58,75 g 235U:<br>W = N.200 MeV = 1,505.1023.200 = 3,01.10<sup>25</sup> MeV =  4,816.10<sup>12</sup> J.<br>c) đúng<br>Công suất tỏa nhiệt do phân hạch của 58,75 g 235U:  $P_{toa}=\\frac{W}{t}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Công suất phát điện của nhà máy:<br>$P=255.P_{toa}=25%.\\frac{W}{t}=25%.\\frac{4,816.10^{12}}{24.3600}\\approx 13,94.10^6W=13,94\\left(MW\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Số neutron được giải phóng do 58,75 g 235U:<br>𝑁1 = 𝑁.2,5 = 1,505.1023.2,5 = 3,7625.10<sup>23</sup> hạt.<br>$Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Số neutorn bị hấp thụ để 58,75 g 235U phân hạch hết:<br>𝑁2 = 𝑁 = 1,505.10<sup>23</sup> hạt.<br>Số neutron thu được trong lò phản ứng:<br>N = 𝑁1 − 𝑁2 = 3,7625.10<sup>23</sup> −1,505.10<sup>23</sup> = 2,2575.10<sup>23</sup> hạt.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":571265,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"0,17","question":"Xét một đoạn dây tải điện thẳng dài 45 m có dòng điện với cường độ 150 A chạy qua theo hướng về phía Bắc. Từ trường Trái Đất tại vị trí này có độ lớn khoảng 0,5.10<sup>−4</sup> T, có hướng lệch một góc 300 so với dòng điện. Lực từ tác dụng lên đoạn dây nói trên bằng bao nhiêu Newton (N)? (làm tròn đến hàng phần trăm)","difficulty":"de","explanation":"Lực từ tác dụng lên đoạn dây tải điện có độ lớn là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}F=BIℓ.sin\\left(\\vec{B};\\vec{I}\\right)=0,5.10^{−4}.150.45.sin30^0=0,17\\left(N\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":272,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"0,17","question":"Xét một đoạn dây tải điện thẳng dài 45 m có dòng điện với cường độ 150 A chạy qua theo hướng về phía Bắc. Từ trường Trái Đất tại vị trí này có độ lớn khoảng 0,5.10<sup>−4</sup> T, có hướng lệch một góc 300 so với dòng điện. Lực từ tác dụng lên đoạn dây nói trên bằng bao nhiêu Newton (N)? (làm tròn đến hàng phần trăm)","difficulty":"de","explanation":"Lực từ tác dụng lên đoạn dây tải điện có độ lớn là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}F=BIℓ.sin\\left(\\vec{B};\\vec{I}\\right)=0,5.10^{−4}.150.45.sin30^0=0,17\\left(N\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":571982,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":3,"options":["2,04.10<sup>23</sup>.","1,02.10<sup>23</sup>.","6,02.10<sup>23</sup>.","12,04.10<sup>23</sup>."],"question":"2 mol không khí thì có bao nhiêu phân tử không khí? Lấy số Avogadro NA = 6,02.10<sup>23</sup> mol−1.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Số phân tử không khí trong một lượng chất được tính theo công thức: $N = n \\cdot N_A$, trong đó $n$ là số mol và $N_A$ là số Avogadro.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $n = 2\\ \\text{mol}$ và $N_A = 6{,}02\\cdot 10^{23}\\ \\text{mol}^{-1}$:</p><p class=\"text-base leading-relaxed my-2\">$N = 2 \\cdot 6{,}02\\cdot 10^{23} = 12{,}04\\cdot 10^{23}$ (phân tử).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: 2 mol không khí có $12{,}04\\cdot 10^{23}$ phân tử, chọn đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":273,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":3,"options":["2,04.10<sup>23</sup>.","1,02.10<sup>23</sup>.","6,02.10<sup>23</sup>.","12,04.10<sup>23</sup>."],"question":"2 mol không khí thì có bao nhiêu phân tử không khí? Lấy số Avogadro NA = 6,02.10<sup>23</sup> mol−1.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Số phân tử không khí trong một lượng chất được tính theo công thức: $N = n \\cdot N_A$, trong đó $n$ là số mol và $N_A$ là số Avogadro.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $n = 2\\ \\text{mol}$ và $N_A = 6{,}02\\cdot 10^{23}\\ \\text{mol}^{-1}$:</p><p class=\"text-base leading-relaxed my-2\">$N = 2 \\cdot 6{,}02\\cdot 10^{23} = 12{,}04\\cdot 10^{23}$ (phân tử).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: 2 mol không khí có $12{,}04\\cdot 10^{23}$ phân tử, chọn đáp án D.</p>","difficultySource":"ai"}}]},{"id":571993,"nq":{"form":"bai_tap","type":"short_answer","topic":"Áp suất và động năng phân tử khí","answer":"9,64","question":"Ở một độ cao so với mặt đất thì áp suất không khí là 30,6 kPa, còn nhiệt độ là 230 K. Tại độ cao đó, mật độ phân tử của không khi là x. 10<sup>24</sup> phân tử/m3. Biết hằng số Boltzmonn là k = 1,38.10<sup>−23</sup>J/K. Giá trị của X bằng bao nhiêu (kết quả làm tròn đến chữ số hàng phần trăm).","difficulty":"de","explanation":"$p=\\mu kT\\Rightarrow 30,6.10^3=x.10^{24}.1,38.10^{−23}.230\\Rightarrow x\\approx 9,64$","difficultySource":"ai"},"ex":[{"exam":273,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Áp suất và động năng phân tử khí","answer":"9,64","question":"Ở một độ cao so với mặt đất thì áp suất không khí là 30,6 kPa, còn nhiệt độ là 230 K. Tại độ cao đó, mật độ phân tử của không khi là x. 10<sup>24</sup> phân tử/m3. Biết hằng số Boltzmonn là k = 1,38.10<sup>−23</sup>J/K. Giá trị của X bằng bao nhiêu (kết quả làm tròn đến chữ số hàng phần trăm).","difficulty":"de","explanation":"$p=\\mu kT\\Rightarrow 30,6.10^3=x.10^{24}.1,38.10^{−23}.230\\Rightarrow x\\approx 9,64$","difficultySource":"ai"}}]},{"id":571996,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"89,9","question":"Một nhà máy thép mỗi lần luyện được 10 tấn thép. Cho nhiệt nóng chảy riêng của thép là 2,77.10<sup>5</sup> J/kg. Nhà máy sử dụng khí đốt để nấu chảy thép. Biết mỗi 1 kg khí đốt khi cháy hoàn toàn tỏa ra nhiệt lượng là 44.106 J và 70% nhiệt lượng này được truyền cho thép. Lượng khí đốt được sử dụng để làm nóng chảy thép tại nhiệt độ nóng chảy trong mỗi lần luyện thép bằng bao nhiêu kg (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$Q=\\lambda m=2,77.10^5.10.10^3=2770.10^6J$<br>$Q_{kd}=\\frac{Q}{H}=\\frac{2770.10^6}{0,7}\\approx 3957.10^6J$<br>$m=\\frac{Q_{kd}}{q}=\\frac{3957.10^6}{44.10^6}\\approx 89,9kg$","difficultySource":"ai"},"ex":[{"exam":273,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"89,9","question":"Một nhà máy thép mỗi lần luyện được 10 tấn thép. Cho nhiệt nóng chảy riêng của thép là 2,77.10<sup>5</sup> J/kg. Nhà máy sử dụng khí đốt để nấu chảy thép. Biết mỗi 1 kg khí đốt khi cháy hoàn toàn tỏa ra nhiệt lượng là 44.106 J và 70% nhiệt lượng này được truyền cho thép. Lượng khí đốt được sử dụng để làm nóng chảy thép tại nhiệt độ nóng chảy trong mỗi lần luyện thép bằng bao nhiêu kg (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$Q=\\lambda m=2,77.10^5.10.10^3=2770.10^6J$<br>$Q_{kd}=\\frac{Q}{H}=\\frac{2770.10^6}{0,7}\\approx 3957.10^6J$<br>$m=\\frac{Q_{kd}}{q}=\\frac{3957.10^6}{44.10^6}\\approx 89,9kg$","difficultySource":"ai"}}]},{"id":573604,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":3,"options":["$400,6 g$ .","$280,3 g$ .","$426,3 g$ .","$128,2 g$ ."],"question":"Một viện nghiên cứu hạt nhân sử dụng một lò phản ứng hạt nhân dùng công suất nhiệt 200 kW. Lò sử dụng nhiên liệu ${}_{}^{235}U$ . Cho rằng toàn bộ năng lượng mà lò phản ứng này đều nhận được từ nhiệt lượng toả ra của sự phân hạch của  ${}_{}^{235}U$  và hiệu suất của nhà máy là 60%. Cho biết mỗi phân hạch toả năng lượng 200 MeV, coi mỗi năm có 365 ngày. Khối lượng  ${}_{}^{235}U$  mà lò phản ứng tiêu thụ trong 1 năm là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045308496-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Ta có: Năng lượng nhà máy cung cấp trong 1 năm là A = P.t = 6,3072.10<sup>12</sup> J<br>Năng lượng cần thiết cung cấp cho nhà máy:  $Q=\\frac{A}{H}=1,0512.10^{13} J$ .<br>$Q=N.E_{1 hạt}=\\frac{m}{M}.N_A.E_{1 hạt}\\rightarrow m=128,23 g.$","difficultySource":"ai"},"ex":[{"exam":274,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":3,"options":["$400,6 g$ .","$280,3 g$ .","$426,3 g$ .","$128,2 g$ ."],"question":"Một viện nghiên cứu hạt nhân sử dụng một lò phản ứng hạt nhân dùng công suất nhiệt 200 kW. Lò sử dụng nhiên liệu ${}_{}^{235}U$ . Cho rằng toàn bộ năng lượng mà lò phản ứng này đều nhận được từ nhiệt lượng toả ra của sự phân hạch của  ${}_{}^{235}U$  và hiệu suất của nhà máy là 60%. Cho biết mỗi phân hạch toả năng lượng 200 MeV, coi mỗi năm có 365 ngày. Khối lượng  ${}_{}^{235}U$  mà lò phản ứng tiêu thụ trong 1 năm là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045308496-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Ta có: Năng lượng nhà máy cung cấp trong 1 năm là A = P.t = 6,3072.10<sup>12</sup> J<br>Năng lượng cần thiết cung cấp cho nhà máy:  $Q=\\frac{A}{H}=1,0512.10^{13} J$ .<br>$Q=N.E_{1 hạt}=\\frac{m}{M}.N_A.E_{1 hạt}\\rightarrow m=128,23 g.$","difficultySource":"ai"}}]},{"id":573605,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Người ta sử dụng bộ thí nghiệm (hình bên) để tìm hiểu về mối liên hệ giữa thể tích V và nhiệt độ tuyệt đối T của  $3.10^{-4}$  gam khí H2 khi áp suất không đổi (hình 10.3 SGK vật lí 12 KNTT trang 42). Kết quả thí nghiệm được cho như bảng sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045309270-hinh-6.webp\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"(2) là xi lanh chứa lượng khí.","answer":false},{"text":"Với kết quả thu được ở bảng bên, tỉ số  $\\frac{V}{T}$  xấp xỉ bằng nhau.","answer":true},{"text":"Áp suất của lượng khí đã dùng trong thí nghiệm khoảng 1,236.10<sup>4</sup> Pa.","answer":true},{"text":"Thí nghiệm này cho thấy, khi áp suất không đổi thể tích tỉ lệ nghịch với nhiệt độ tuyệt đối","answer":false}],"explanation":"a) sai<br>Vì (2) là nhiệt kế điện tử.<br>b) đúng<br>Lập tỉ số các giá trị xấp sỉ bằng nhau<br>c) đúng<br>Ta có  $pV=nRT=\\frac{m}{M}RT$ ; thay T = 297,5 K; V = 30.10<sup>−6</sup> m3;<br>m =  $3.10^{-4}$  gam; M = 2 gam; R = 8,31 J.mol-1.K-1<br>ta được p = 1,236.10<sup>4</sup> Pa.<br>d) sai<br>Vì khi áp suất không đổi thể tích tỉ lệ thuận với nhiệt độ tuyệt đối","difficultySource":"ai"},"ex":[{"exam":274,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Người ta sử dụng bộ thí nghiệm (hình bên) để tìm hiểu về mối liên hệ giữa thể tích V và nhiệt độ tuyệt đối T của  $3.10^{-4}$  gam khí H2 khi áp suất không đổi (hình 10.3 SGK vật lí 12 KNTT trang 42). Kết quả thí nghiệm được cho như bảng sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045309270-hinh-6.webp\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"(2) là xi lanh chứa lượng khí.","answer":false},{"text":"Với kết quả thu được ở bảng bên, tỉ số  $\\frac{V}{T}$  xấp xỉ bằng nhau.","answer":true},{"text":"Áp suất của lượng khí đã dùng trong thí nghiệm khoảng 1,236.10<sup>4</sup> Pa.","answer":true},{"text":"Thí nghiệm này cho thấy, khi áp suất không đổi thể tích tỉ lệ nghịch với nhiệt độ tuyệt đối","answer":false}],"explanation":"a) sai<br>Vì (2) là nhiệt kế điện tử.<br>b) đúng<br>Lập tỉ số các giá trị xấp sỉ bằng nhau<br>c) đúng<br>Ta có  $pV=nRT=\\frac{m}{M}RT$ ; thay T = 297,5 K; V = 30.10<sup>−6</sup> m3;<br>m =  $3.10^{-4}$  gam; M = 2 gam; R = 8,31 J.mol-1.K-1<br>ta được p = 1,236.10<sup>4</sup> Pa.<br>d) sai<br>Vì khi áp suất không đổi thể tích tỉ lệ thuận với nhiệt độ tuyệt đối","difficultySource":"ai"}}]},{"id":573611,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"4,33","question":"Cho phản ứng nhiệt hạch:  ${}_1^3T+{}_1^2D\\rightarrow \\alpha +n$ . Biết mT = 3,01605u; mD = 2,01411u; m = 4,00260u; mn = 1,00867u; 1u = 931 MeV/c2. Cho biết 1 eV = 1,60.10<sup>−19</sup>J. Năng lượng toả ra theo khi 1 gam hạt α được hình thành là x.10<sup>11</sup> J. Giá trị của x là bao nhiêu? (làm tròn kết quả đến chữ số phần trăm).","difficulty":"kho","explanation":"Năng lượng toả ra khi sinh ra 1 hạt  $\\alpha$  là   $E_{toả/hạt}=\\left(m_{tr}-m_s\\right).c^2=2,88.10^{-12} J$<br>$N=\\frac{m}{M}N_A=1,505.10^{23} hạt$<br>$E_{toả}=N.E_{toả/hạt}=4,33.10^{11}$  J.","difficultySource":"ai"},"ex":[{"exam":274,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"4,33","question":"Cho phản ứng nhiệt hạch:  ${}_1^3T+{}_1^2D\\rightarrow \\alpha +n$ . Biết mT = 3,01605u; mD = 2,01411u; m = 4,00260u; mn = 1,00867u; 1u = 931 MeV/c2. Cho biết 1 eV = 1,60.10<sup>−19</sup>J. Năng lượng toả ra theo khi 1 gam hạt α được hình thành là x.10<sup>11</sup> J. Giá trị của x là bao nhiêu? (làm tròn kết quả đến chữ số phần trăm).","difficulty":"kho","explanation":"Năng lượng toả ra khi sinh ra 1 hạt  $\\alpha$  là   $E_{toả/hạt}=\\left(m_{tr}-m_s\\right).c^2=2,88.10^{-12} J$<br>$N=\\frac{m}{M}N_A=1,505.10^{23} hạt$<br>$E_{toả}=N.E_{toả/hạt}=4,33.10^{11}$  J.","difficultySource":"ai"}}]},{"id":574600,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["2,5 MJ","1,8 MJ","0,5 MJ","2,1 MI"],"question":"Nhiệt lượng cần cung cấp cho m = 5 kg nước đá ‒100C chuyển hoàn toàn thành nước ở 00C xấp xỉ bao nhiêu MJ. Cho biết nhiệt dung riêng của nước đá là 2090 J/kg.K và nhiệt nóng chảy riêng của nước đá 3,4.10<sup>5</sup> J/kg. Bỏ qua sự mất mát năng lượng ra môi trường xung quanh.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nước đá cần nhận nhiệt lượng theo hai giai đoạn: làm nóng từ $-10^\\circ$C đến $0^\\circ$C, rồi nóng chảy hoàn toàn ở $0^\\circ$C. Bỏ qua mất mát ra môi trường nên nhiệt lượng cung cấp bằng tổng nhiệt lượng thu vào.</p><p class=\"text-base leading-relaxed my-2\">Giai đoạn 1 (làm nóng nước đá từ $-10^\\circ$C đến $0^\\circ$C):</p><p class=\"text-base leading-relaxed my-2\">$Q_1 = m c \\Delta t$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q_1 = 5 \\cdot 2090 \\cdot 10 = 104\\,500\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Giai đoạn 2 (nóng chảy hoàn toàn ở $0^\\circ$C):</p><p class=\"text-base leading-relaxed my-2\">$Q_2 = \\lambda m$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q_2 = 3{,}4 \\cdot 10^5 \\cdot 5 = 1\\,700\\,000\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Tổng nhiệt lượng cần cung cấp:</p><p class=\"text-base leading-relaxed my-2\">$Q = Q_1 + Q_2 = 104\\,500 + 1\\,700\\,000 = 1\\,804\\,500\\ \\text{J} \\approx 1{,}8\\ \\text{MJ}$</p><p class=\"text-base leading-relaxed my-2\">Vậy đáp án là B.</p>","difficultySource":"ai"},"ex":[{"exam":276,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["2,5 MJ","1,8 MJ","0,5 MJ","2,1 MI"],"question":"Nhiệt lượng cần cung cấp cho m = 5 kg nước đá ‒100C chuyển hoàn toàn thành nước ở 00C xấp xỉ bao nhiêu MJ. Cho biết nhiệt dung riêng của nước đá là 2090 J/kg.K và nhiệt nóng chảy riêng của nước đá 3,4.10<sup>5</sup> J/kg. Bỏ qua sự mất mát năng lượng ra môi trường xung quanh.","difficulty":"de","explanation":"$Q=5.2090.10+5.3,4.10^5=1,8\\left(MJ\\right)$","difficultySource":"ai"}}]},{"id":574609,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một khối khí lí tưởng đơn nguyên tử có thể tích V = 5l ở áp suất khí quyển p = 1,013.10<sup>5</sup> Pa và nhiệt độ T = 300 K (điểm A trong hình). Nó được làm nóng ở thể tích không đổi đến áp suất 3 atm (điểm B). Sau đó, nó được giãn nở đẳng nhiệt đến áp suất 1 atm (điểm C) và cuối cùng bị nén đẳng áp về trạng thái ban đầu.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045332336-hinh-21.png\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Số mol của khí trong mẫu xấp xỉ là 0,203 mol.","answer":true},{"text":"Thể tích của khí ở C là 1,5 lít","answer":false},{"text":"Nhiệt lượng khí nhận được trong quá trình A → B xấp xỉ là 1,52 kJ","answer":true},{"text":"Trong quá trình B → C độ biến thiên nội năng của khí ΔU = 0","answer":true}],"explanation":"a) đúng<br>$pV=nRT\\Rightarrow 1,013.10^5.\\left(5.10^{−3}\\right)=n.8,31.300\\Rightarrow n=0,203\\left(mol\\right)$<br>b) sai<br>Thể tích của khí ở C là 15 lít<br>c) đúng<br>$\\Delta U=Q=\\frac{3}{2}N.k\\frac{R}{N_A}.\\Delta T=\\frac{3}{2}.\\left(0,203\\right).8,31.600=1,518.10^3\\left(J\\right)$<br>d) đúng<br>Từ B → C: Quá trình đẳng nhiệt  $\\Rightarrow T=const$<br>$\\Rightarrow$  Động năng phân tử khí không đổi<br>$\\Rightarrow$  Nội năng sẽ không đổi","difficultySource":"ai"},"ex":[{"exam":276,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một khối khí lí tưởng đơn nguyên tử có thể tích V = 5l ở áp suất khí quyển p = 1,013.10<sup>5</sup> Pa và nhiệt độ T = 300 K (điểm A trong hình). Nó được làm nóng ở thể tích không đổi đến áp suất 3 atm (điểm B). Sau đó, nó được giãn nở đẳng nhiệt đến áp suất 1 atm (điểm C) và cuối cùng bị nén đẳng áp về trạng thái ban đầu.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045332336-hinh-21.png\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Số mol của khí trong mẫu xấp xỉ là 0,203 mol.","answer":true},{"text":"Thể tích của khí ở C là 1,5 lít","answer":false},{"text":"Nhiệt lượng khí nhận được trong quá trình A → B xấp xỉ là 1,52 kJ","answer":true},{"text":"Trong quá trình B → C độ biến thiên nội năng của khí ΔU = 0","answer":true}],"explanation":"a) đúng<br>$pV=nRT\\Rightarrow 1,013.10^5.\\left(5.10^{−3}\\right)=n.8,31.300\\Rightarrow n=0,203\\left(mol\\right)$<br>b) sai<br>Thể tích của khí ở C là 15 lít<br>c) đúng<br>$\\Delta U=Q=\\frac{3}{2}N.k\\frac{R}{N_A}.\\Delta T=\\frac{3}{2}.\\left(0,203\\right).8,31.600=1,518.10^3\\left(J\\right)$<br>d) đúng<br>Từ B → C: Quá trình đẳng nhiệt  $\\Rightarrow T=const$<br>$\\Rightarrow$  Động năng phân tử khí không đổi<br>$\\Rightarrow$  Nội năng sẽ không đổi","difficultySource":"ai"}}]},{"id":574613,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"5,28","question":"Một lượng khí trong một xilanh hình trụ có áp suất của khối khí là 2.10<sup>5</sup> Pa được nung nóng đẳng áp, khí nở ra đẩy pit-tông lên làm thể tích tăng thêm 0,02 m3 và nội năng khí tăng thêm 1280 J. Nhiệt lượng đã truyền cho khối khí bằng bao nhiêu kJ?","difficulty":"trung-binh","explanation":"$\\Delta U=Q+A=−p.\\Delta V$<br>$\\Rightarrow 1280=Q+\\left(−2.10^{5\\left(J\\right)}.0,02\\right)\\Rightarrow Q=5,28.10^{3}$","difficultySource":"ai"},"ex":[{"exam":276,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"5,28","question":"Một lượng khí trong một xilanh hình trụ có áp suất của khối khí là 2.10<sup>5</sup> Pa được nung nóng đẳng áp, khí nở ra đẩy pit-tông lên làm thể tích tăng thêm 0,02 m3 và nội năng khí tăng thêm 1280 J. Nhiệt lượng đã truyền cho khối khí bằng bao nhiêu kJ?","difficulty":"trung-binh","explanation":"$\\Delta U=Q+A=−p.\\Delta V$<br>$\\Rightarrow 1280=Q+\\left(−2.10^{5\\left(J\\right)}.0,02\\right)\\Rightarrow Q=5,28.10^{3}$","difficultySource":"ai"}}]},{"id":574614,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt độ và cân bằng nhiệt","answer":"2","question":"Một cục nước đá ở nhiệt độ t1 = ‒5°C dìm ngập hoàn toàn vào một cốc nước ở nhiệt độ t2 = 38,8°C, khối lượng của nước bằng khối lượng của nước đá bằng m. Coi rằng chỉ có nước và nước đá trao đổi nhiệt với nhau. Bỏ qua sự thay đổi thể tích của nước và nước đá theo nhiệt độ. Cho nhiệt dung riêng, nhiệt nóng chảy riêng, khối lượng riêng của nước đá lần lượt là C1 = 2090 J/kg.K, λ = 3,33.10<sup>5</sup> J/kg, D1 = 0,916 g/cm3; Nhiệt dung riêng, khối lượng riêng của nước lần lượt là C2 = 4180 J/kg.K; D2 = 1 g/cm3. Khi có cân bằng nhiệt, mực nước trong cốc giảm a % so với ban đầu. Tính a (làm tròn đến phần nguyên)","difficulty":"kho","explanation":"Giả sử có 1kg nước và đá<br>$Q_{toa max}=1.4180.38,8=162184\\left(J\\right)$<br>$Q_{thu max}=1.2090.5+1.3,33.10^5=343450\\left(J\\right)$<br>$Q_{toa max}<Q_{thu max}\\Rightarrow$  Đá chưa tan hết<br>$m_{da tan}=\\frac{162184−20905}{3,33.10^5}=0,4556\\left(kg\\right)$<br>$V_{dau}=\\frac{1000}{1}+\\frac{1000}{0,916}=2091,7cm^3$<br>$V_{sau}=\\frac{1000+455,6}{1}+\\frac{1000−455,6}{0,916}=2050cm^3$<br>$\\Rightarrow Giam \\frac{2091,7−2050}{2091,7}\\approx 2%$","difficultySource":"ai"},"ex":[{"exam":276,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt độ và cân bằng nhiệt","answer":"2","question":"Một cục nước đá ở nhiệt độ t1 = ‒5°C dìm ngập hoàn toàn vào một cốc nước ở nhiệt độ t2 = 38,8°C, khối lượng của nước bằng khối lượng của nước đá bằng m. Coi rằng chỉ có nước và nước đá trao đổi nhiệt với nhau. Bỏ qua sự thay đổi thể tích của nước và nước đá theo nhiệt độ. Cho nhiệt dung riêng, nhiệt nóng chảy riêng, khối lượng riêng của nước đá lần lượt là C1 = 2090 J/kg.K, λ = 3,33.10<sup>5</sup> J/kg, D1 = 0,916 g/cm3; Nhiệt dung riêng, khối lượng riêng của nước lần lượt là C2 = 4180 J/kg.K; D2 = 1 g/cm3. Khi có cân bằng nhiệt, mực nước trong cốc giảm a % so với ban đầu. Tính a (làm tròn đến phần nguyên)","difficulty":"kho","explanation":"Giả sử có 1kg nước và đá<br>$Q_{toa max}=1.4180.38,8=162184\\left(J\\right)$<br>$Q_{thu max}=1.2090.5+1.3,33.10^5=343450\\left(J\\right)$<br>$Q_{toa max}<Q_{thu max}\\Rightarrow$  Đá chưa tan hết<br>$m_{da tan}=\\frac{162184−20905}{3,33.10^5}=0,4556\\left(kg\\right)$<br>$V_{dau}=\\frac{1000}{1}+\\frac{1000}{0,916}=2091,7cm^3$<br>$V_{sau}=\\frac{1000+455,6}{1}+\\frac{1000−455,6}{0,916}=2050cm^3$<br>$\\Rightarrow Giam \\frac{2091,7−2050}{2091,7}\\approx 2%$","difficultySource":"ai"}}]},{"id":575515,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh thực hiện thí nghiệm đo nhiệt nóng chảy riêng của nước đá. Bộ thí nghiệm gồm: biến áp nguồn, bộ đo công suất (oát kế) có tích hợp chức năng đo thời gian, nhiệt kế điện tử có thang đo từ –200C đến 1100C, độ phân giải ± 0,10C, nhiệt lượng kế, cân điện tử, các dây nối. Ban đầu, nhóm cho một viên nước đá và một ít nước lạnh vào bình nhiệt lượng kế, cắm nhiệt kế vào bình, khuấy đều hỗn hợp cho đến khi nhiệt kế chỉ 0 0C. Lấy viên nước đá ra cân thì số chỉ của cân là 22,80 g. Sau đó, bỏ viên đá vào lại nhiệt lượng kế, sao cho toàn bộ điện trở chìm trong hỗn hợp nước và nước đá, bật công tắc nguồn, khuấy nhẹ, ghi lại số chỉ của bộ đo công suất và thời gian sau các khoảng 60 giây vào bảng. Khi thời gian là 300 giây, lấy viên đá ra cân thì số chỉ của cân là 10,58 g.<br>Thời gian (s)\tCông suất (W)\tNhiệt độ (0C)<br>60\t14,05\t0<br>120\t14,06\t0<br>180\t14,00\t0<br>240\t14,02\t0","difficulty":"kho","statements":[{"text":"Trong quá trình nước đá tan, nhiệt độ hỗn hợp không đổi.","answer":true},{"text":"Trong quá trình nước đá tan, nội năng của hỗn hợp tăng lên.","answer":true},{"text":"Thực tế, trong quá trình nước đá tan, hỗn hợp nước và nước đá tỏa nhiệt ra môi trường xung quanh.","answer":true},{"text":"Từ bảng số liệu của nhóm, tính được nhiệt nóng chảy riêng trung bình của nước đá là 3,44.10<sup>3</sup> J/kg","answer":false}],"explanation":"a) đúng<br>Trong quá trình nước đá tan, nhiệt độ hỗn hợp không đổi và ở 00C<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Nội năng tăng lên. Vì nó vẫn hấp thụ nhiệt của nhiệt điện trở. Tuy nhiệt độ không tăng lên. Nhưng thế năng tương tác của nó tăng lên rồi<br>c) đúng<br>Không thể tránh được hao phí toả nhiệt ra môi trường xung quanh<br>d) sai<br>$\\begin{aligned}\\end{aligned}\\overline{P}=\\frac{14,05+14,06+14,00+14,02+13,98}{5}=14,022Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\lambda =\\frac{Q}{\\Delta m}=\\frac{\\overline{P}.t}{m_t−m_s}=\\frac{14,022.300}{\\left(22,8−10,58\\right)}=344,2\\left(J/g\\right)=344220\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":278,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh thực hiện thí nghiệm đo nhiệt nóng chảy riêng của nước đá. Bộ thí nghiệm gồm: biến áp nguồn, bộ đo công suất (oát kế) có tích hợp chức năng đo thời gian, nhiệt kế điện tử có thang đo từ –200C đến 1100C, độ phân giải ± 0,10C, nhiệt lượng kế, cân điện tử, các dây nối. Ban đầu, nhóm cho một viên nước đá và một ít nước lạnh vào bình nhiệt lượng kế, cắm nhiệt kế vào bình, khuấy đều hỗn hợp cho đến khi nhiệt kế chỉ 0 0C. Lấy viên nước đá ra cân thì số chỉ của cân là 22,80 g. Sau đó, bỏ viên đá vào lại nhiệt lượng kế, sao cho toàn bộ điện trở chìm trong hỗn hợp nước và nước đá, bật công tắc nguồn, khuấy nhẹ, ghi lại số chỉ của bộ đo công suất và thời gian sau các khoảng 60 giây vào bảng. Khi thời gian là 300 giây, lấy viên đá ra cân thì số chỉ của cân là 10,58 g.<br>Thời gian (s)\tCông suất (W)\tNhiệt độ (0C)<br>60\t14,05\t0<br>120\t14,06\t0<br>180\t14,00\t0<br>240\t14,02\t0","difficulty":"kho","statements":[{"text":"Trong quá trình nước đá tan, nhiệt độ hỗn hợp không đổi.","answer":true},{"text":"Trong quá trình nước đá tan, nội năng của hỗn hợp tăng lên.","answer":true},{"text":"Thực tế, trong quá trình nước đá tan, hỗn hợp nước và nước đá tỏa nhiệt ra môi trường xung quanh.","answer":true},{"text":"Từ bảng số liệu của nhóm, tính được nhiệt nóng chảy riêng trung bình của nước đá là 3,44.10<sup>3</sup> J/kg","answer":false}],"explanation":"a) đúng<br>Trong quá trình nước đá tan, nhiệt độ hỗn hợp không đổi và ở 00C<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Nội năng tăng lên. Vì nó vẫn hấp thụ nhiệt của nhiệt điện trở. Tuy nhiệt độ không tăng lên. Nhưng thế năng tương tác của nó tăng lên rồi<br>c) đúng<br>Không thể tránh được hao phí toả nhiệt ra môi trường xung quanh<br>d) sai<br>$\\begin{aligned}\\end{aligned}\\overline{P}=\\frac{14,05+14,06+14,00+14,02+13,98}{5}=14,022Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\lambda =\\frac{Q}{\\Delta m}=\\frac{\\overline{P}.t}{m_t−m_s}=\\frac{14,022.300}{\\left(22,8−10,58\\right)}=344,2\\left(J/g\\right)=344220\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":575516,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Một khinh khí cầu có tổng khối lượng (gồm khoang và hành khách) là 450 kg. Phần khí cầu chứa 3,00.10³ m³ không khí. Biết khí quyển bên ngoài có nhiệt độ là 250C và áp suất là 1,03.10<sup>5</sup> Pa, gia tốc trọng trường là g = 9,80 $m/s^2$.","difficulty":"kho","statements":[{"text":"Lực tối thiểu để nâng khoang lên khỏi mặt đất là 4410 N.","answer":true},{"text":"Khinh khí cầu bay lên được là do khối lượng riêng của khí trong khí cầu nhỏ hơn của khí quyển.","answer":true},{"text":"Coi không khí ở 250C là khí lý tưởng, số mol không khí trong khí cầu ở nhiệt độ 250C là 1247,8 mol.","answer":false},{"text":"Khi không khí trong khí cầu bị đốt nóng, nó bị giãn nở và một phần bị đẩy ra ngoài thông qua lỗ thoát khí phía trên khí cầu. Biết ở 250C khối lượng riêng của không khí là 1,29 kg/m³ , vỏ khí cầu mỏng, không giãn và nhẹ. Để quả cầu rời khỏi mặt đất, nhiệt độ khí trong khí cầu phải đạt tối thiểu là 64,20C.","answer":true}],"explanation":"a) đúng<br>$F_{min}=P=mg=450.9,8=4410\\left(N\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Khinh khí cầu bay lên được là do khối lượng riêng của khí trong khí cầu nhỏ hơn của khí quyển.<br>c) sai<br>$n=\\frac{pV}{RT}=\\frac{1,03.10^5.3000}{8,31.\\left(25+273\\right)}=124778,9\\left(mol\\right)$<br>d) đúng<br>Nguyên lý hoạt động của khí cầu.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045359538-hinh-18.png\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Khí cầu chở khoang hàng có trọng lượng P của khí cầu và lực đẩy  $F_{asm}$  hướng lên<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Lực đẩy Acsimet sinh ra do chênh lệch khối lượng riêng của khí trong khí cầu và khí bên ngoài khí cầu. Do khí trong khí cầu có nhiệt độ cao hơn dẫn đến giãn nở đẩy không khí ra ngoài. Dẫn đễn khối lượng không khí trong khí cầu giảm đi, V không đổi làm cho khối lượng riêng giảm đi, chênh lệch khối lượng riêng sinh ra lực đẩy Acsimet. Bản chất khí trong khí cầu có khối lượng<br>Để khí cầu bay lên được:  $F_{ASM}\\ge P+P_K$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow \\delta_0gV\\ge 4410+\\delta_k.g.V$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow \\delta_k\\le \\frac{\\delta_0gV−4410}{gV}=\\frac{1,29.9,8.3000−4410}{9,8.3000}=1,14\\left(kg/m^3\\right)Website: thukhoadaihoc.vn$<br>$\\delta_{kmax}=1,14$<br>+  $pV=nRT=\\frac{m}{M}RT\\Rightarrow T=\\frac{pV.M}{mR}=\\frac{pV}{R}.\\frac{1}{\\delta }\\left(Vi \\frac{V}{m}=\\frac{1}{\\delta }\\right)$<br>$\\begin{aligned}\\end{aligned}T\\sim \\frac{1}{\\delta }\\Rightarrow \\frac{T_k}{T_0}=\\frac{\\delta_0}{\\delta_k}\\Rightarrow T_K=\\frac{1,29}{1,14}.\\left(25+273\\right)=337,2\\left(K\\right)=64,2^0CWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":278,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Một khinh khí cầu có tổng khối lượng (gồm khoang và hành khách) là 450 kg. Phần khí cầu chứa 3,00.10³ m³ không khí. Biết khí quyển bên ngoài có nhiệt độ là 250C và áp suất là 1,03.10<sup>5</sup> Pa, gia tốc trọng trường là g = 9,80 m/s2.","difficulty":"kho","statements":[{"text":"Lực tối thiểu để nâng khoang lên khỏi mặt đất là 4410 N.","answer":true},{"text":"Khinh khí cầu bay lên được là do khối lượng riêng của khí trong khí cầu nhỏ hơn của khí quyển.","answer":true},{"text":"Coi không khí ở 250C là khí lý tưởng, số mol không khí trong khí cầu ở nhiệt độ 250C là 1247,8 mol.","answer":false},{"text":"Khi không khí trong khí cầu bị đốt nóng, nó bị giãn nở và một phần bị đẩy ra ngoài thông qua lỗ thoát khí phía trên khí cầu. Biết ở 250C khối lượng riêng của không khí là 1,29 kg/m³ , vỏ khí cầu mỏng, không giãn và nhẹ. Để quả cầu rời khỏi mặt đất, nhiệt độ khí trong khí cầu phải đạt tối thiểu là 64,20C.","answer":true}],"explanation":"a) đúng<br>$F_{min}=P=mg=450.9,8=4410\\left(N\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Khinh khí cầu bay lên được là do khối lượng riêng của khí trong khí cầu nhỏ hơn của khí quyển.<br>c) sai<br>$n=\\frac{pV}{RT}=\\frac{1,03.10^5.3000}{8,31.\\left(25+273\\right)}=124778,9\\left(mol\\right)$<br>d) đúng<br>Nguyên lý hoạt động của khí cầu.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045359538-hinh-18.png\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Khí cầu chở khoang hàng có trọng lượng P của khí cầu và lực đẩy  $F_{asm}$  hướng lên<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Lực đẩy Acsimet sinh ra do chênh lệch khối lượng riêng của khí trong khí cầu và khí bên ngoài khí cầu. Do khí trong khí cầu có nhiệt độ cao hơn dẫn đến giãn nở đẩy không khí ra ngoài. Dẫn đễn khối lượng không khí trong khí cầu giảm đi, V không đổi làm cho khối lượng riêng giảm đi, chênh lệch khối lượng riêng sinh ra lực đẩy Acsimet. Bản chất khí trong khí cầu có khối lượng<br>Để khí cầu bay lên được:  $F_{ASM}\\ge P+P_K$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow \\delta_0gV\\ge 4410+\\delta_k.g.V$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow \\delta_k\\le \\frac{\\delta_0gV−4410}{gV}=\\frac{1,29.9,8.3000−4410}{9,8.3000}=1,14\\left(kg/m^3\\right)Website: thukhoadaihoc.vn$<br>$\\delta_{kmax}=1,14$<br>+  $pV=nRT=\\frac{m}{M}RT\\Rightarrow T=\\frac{pV.M}{mR}=\\frac{pV}{R}.\\frac{1}{\\delta }\\left(Vi \\frac{V}{m}=\\frac{1}{\\delta }\\right)$<br>$\\begin{aligned}\\end{aligned}T\\sim \\frac{1}{\\delta }\\Rightarrow \\frac{T_k}{T_0}=\\frac{\\delta_0}{\\delta_k}\\Rightarrow T_K=\\frac{1,29}{1,14}.\\left(25+273\\right)=337,2\\left(K\\right)=64,2^0CWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":578111,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":3,"options":["200 m.","30 m.","150 m.","300 m."],"question":"Một sóng điện từ có tần số 106 Hz truyền trong một môi trường với tốc độ 3.10<sup>8</sup> m/s. Trong môi trường đó, sóng điện từ này có bước sóng là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng được tính theo công thức $\\lambda = \\dfrac{v}{f}$, trong đó $v$ là tốc độ truyền sóng trong môi trường và $f$ là tần số sóng.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $f = 10^{6}\\ \\text{Hz}$ và $v = 3\\cdot 10^{8}\\ \\text{m/s}$:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda = \\dfrac{3\\cdot 10^{8}}{10^{6}} = 300\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy bước sóng của sóng điện từ trong môi trường đó là $300\\ \\text{m}$.</p>","difficultySource":"ai"},"ex":[{"exam":281,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":3,"options":["200 m.","30 m.","150 m.","300 m."],"question":"Một sóng điện từ có tần số 106 Hz truyền trong một môi trường với tốc độ 3.10<sup>8</sup> m/s. Trong môi trường đó, sóng điện từ này có bước sóng là","difficulty":"de","explanation":"$\\lambda =\\frac{c}{f}=\\frac{3.10^8}{10^6}=300\\left(m\\right)$","difficultySource":"ai"}}]},{"id":578114,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["3,28.10<sup>11</sup> J.","16,4.10<sup>11</sup> J.","16,4.10<sup>10</sup> J.","3,28.10<sup>10</sup> J."],"question":"Cho rằng một hạt nhân Uranium  ${}_{92}^{235}U$ khi phân hạch thì tỏa ra năng lượng là 200 MeV. Lấy NA = 6,023.10<sup>23</sup> mol−1, 1 eV = 1,6.10<sup>−19</sup> J và khối lượng mol của urani 92235U là 235 g/mol. Năng lượng tỏa ra khi 4 g Uranium  ${}_{92}^{235}U$ phân hạch hết là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Số hạt nhân $^{235}_{92}U$ có trong 4 g:</p><p class=\"text-base leading-relaxed my-2\">$N = \\dfrac{m}{M}N_A$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = \\dfrac{4}{235}\\cdot 6{,}023\\cdot 10^{23} \\approx 1{,}025\\cdot 10^{22}$ hạt</p><p class=\"text-base leading-relaxed my-2\">Năng lượng tỏa ra bởi một hạt nhân:</p><p class=\"text-base leading-relaxed my-2\">$E_1 = 200 \\text{ MeV} = 200\\cdot 10^{6}\\cdot 1{,}6\\cdot 10^{-19} = 3{,}2\\cdot 10^{-11}$ J</p><p class=\"text-base leading-relaxed my-2\">Năng lượng tỏa ra khi 4 g Uranium phân hạch hết:</p><p class=\"text-base leading-relaxed my-2\">$E = N\\cdot E_1 = 1{,}025\\cdot 10^{22}\\cdot 3{,}2\\cdot 10^{-11} \\approx 3{,}28\\cdot 10^{11}$ J</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":281,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["3,28.10<sup>11</sup> J.","16,4.10<sup>11</sup> J.","16,4.10<sup>10</sup> J.","3,28.10<sup>10</sup> J."],"question":"Cho rằng một hạt nhân Uranium  ${}_{92}^{235}U$ khi phân hạch thì tỏa ra năng lượng là 200 MeV. Lấy NA = 6,023.10<sup>23</sup> mol−1, 1 eV = 1,6.10<sup>−19</sup> J và khối lượng mol của urani 92235U là 235 g/mol. Năng lượng tỏa ra khi 4 g Uranium  ${}_{92}^{235}U$ phân hạch hết là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Số hạt nhân $^{235}_{92}U$ có trong 4 g:</p><p class=\"text-base leading-relaxed my-2\">$N = \\dfrac{m}{M}N_A$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = \\dfrac{4}{235}\\cdot 6{,}023\\cdot 10^{23} \\approx 1{,}025\\cdot 10^{22}$ hạt</p><p class=\"text-base leading-relaxed my-2\">Năng lượng tỏa ra bởi một hạt nhân:</p><p class=\"text-base leading-relaxed my-2\">$E_1 = 200 \\text{ MeV} = 200\\cdot 10^{6}\\cdot 1{,}6\\cdot 10^{-19} = 3{,}2\\cdot 10^{-11}$ J</p><p class=\"text-base leading-relaxed my-2\">Năng lượng tỏa ra khi 4 g Uranium phân hạch hết:</p><p class=\"text-base leading-relaxed my-2\">$E = N\\cdot E_1 = 1{,}025\\cdot 10^{22}\\cdot 3{,}2\\cdot 10^{-11} \\approx 3{,}28\\cdot 10^{11}$ J</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án A.</p>","difficultySource":"ai"}}]},{"id":578115,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":2,"options":["2,4.10<sup>−6</sup> Wb","1,2.10<sup>−4</sup> Wb","2,4.10<sup>−4</sup> Wb","1,2.10<sup>−6</sup> Wb"],"question":"Một khung dây phẳng diện tích 40 cm2 đặt trong từ trường đều có vectơ cảm ứng từ hợp với vectơ pháp tuyến của mặt phẳng khung dây một góc 600 và có độ lớn 0,12 T. Từ thông qua khung dây này là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông qua khung dây phẳng trong từ trường đều được tính theo công thức $\\Phi = B S \\cos\\alpha$, trong đó $\\alpha$ là góc giữa vectơ cảm ứng từ $\\vec{B}$ và vectơ pháp tuyến $\\vec{n}$ của mặt phẳng khung.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị diện tích: $S = 40\\ \\text{cm}^2 = 40 \\cdot 10^{-4}\\ \\text{m}^2 = 4 \\cdot 10^{-3}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $B = 0{,}12\\ \\text{T}$ và $\\alpha = 60^\\circ$:</p><p class=\"text-base leading-relaxed my-2\">$\\Phi = 0{,}12 \\cdot 4 \\cdot 10^{-3} \\cdot \\cos 60^\\circ = 0{,}12 \\cdot 4 \\cdot 10^{-3} \\cdot 0{,}5 = 2{,}4 \\cdot 10^{-4}\\ \\text{Wb}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy từ thông qua khung dây là $2{,}4 \\cdot 10^{-4}\\ \\text{Wb}$, đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":281,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":2,"options":["2,4.10<sup>−6</sup> Wb","1,2.10<sup>−4</sup> Wb","2,4.10<sup>−4</sup> Wb","1,2.10<sup>−6</sup> Wb"],"question":"Một khung dây phẳng diện tích 40 cm2 đặt trong từ trường đều có vectơ cảm ứng từ hợp với vectơ pháp tuyến của mặt phẳng khung dây một góc 600 và có độ lớn 0,12 T. Từ thông qua khung dây này là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông qua khung dây phẳng trong từ trường đều được tính theo công thức $\\Phi = B S \\cos\\alpha$, trong đó $\\alpha$ là góc giữa vectơ cảm ứng từ $\\vec{B}$ và vectơ pháp tuyến $\\vec{n}$ của mặt phẳng khung.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị diện tích: $S = 40\\ \\text{cm}^2 = 40 \\cdot 10^{-4}\\ \\text{m}^2 = 4 \\cdot 10^{-3}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $B = 0{,}12\\ \\text{T}$ và $\\alpha = 60^\\circ$:</p><p class=\"text-base leading-relaxed my-2\">$\\Phi = 0{,}12 \\cdot 4 \\cdot 10^{-3} \\cdot \\cos 60^\\circ = 0{,}12 \\cdot 4 \\cdot 10^{-3} \\cdot 0{,}5 = 2{,}4 \\cdot 10^{-4}\\ \\text{Wb}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy từ thông qua khung dây là $2{,}4 \\cdot 10^{-4}\\ \\text{Wb}$, đáp án C.</p>","difficultySource":"ai"}}]},{"id":578118,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["107520 J.","78000 J.","185520 J.","29520 kJ."],"question":"Biết nhôm có nhiệt dung riêng là 896 J/kg.K và nhiệt nóng chảy riêng là 3,9.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp cho miếng nhôm khối lượng 200 g ở nhiệt độ 580C để nó hóa lỏng hoàn toàn ở nhiệt độ 6580C là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Quá trình gồm hai giai đoạn: nhôm được đun nóng từ 58°C lên nhiệt độ nóng chảy 658°C, rồi nóng chảy hoàn toàn ở 658°C. Nhiệt lượng tổng cộng là tổng hai phần.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 200\\ \\text{g} = 0{,}2\\ \\text{kg}$; độ tăng nhiệt độ $\\Delta t = 658 - 58 = 600\\ ^\\circ\\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng làm nóng nhôm từ 58°C đến 658°C:</p><p class=\"text-base leading-relaxed my-2\">$Q_1 = m c \\Delta t$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q_1 = 0{,}2 \\cdot 896 \\cdot 600 = 107520\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng làm nhôm nóng chảy hoàn toàn ở 658°C:</p><p class=\"text-base leading-relaxed my-2\">$Q_2 = \\lambda m$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q_2 = 3{,}9\\cdot 10^5 \\cdot 0{,}2 = 78000\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng tổng cộng cần cung cấp:</p><p class=\"text-base leading-relaxed my-2\">$Q = Q_1 + Q_2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 107520 + 78000 = 185520\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: nhiệt lượng cần cung cấp là $185520\\ \\text{J}$, đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":281,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["107520 J.","78000 J.","185520 J.","29520 kJ."],"question":"Biết nhôm có nhiệt dung riêng là 896 J/kg.K và nhiệt nóng chảy riêng là 3,9.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp cho miếng nhôm khối lượng 200 g ở nhiệt độ 580C để nó hóa lỏng hoàn toàn ở nhiệt độ 6580C là","difficulty":"trung-binh","explanation":"$Q=0,2.896.600+0,2.3,9.10^5=185520\\left(J\\right)$","difficultySource":"ai"}}]},{"id":578124,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":1,"options":["F = 6.10<sup>−4</sup> N","F = 2.10<sup>−4</sup> N","F = 6.10<sup>−2</sup> N","F = 2.10<sup>−2</sup> N"],"question":"Hình vẽ bên cạnh mô tả mô hình động cơ điện. Một khung dây dẫn hình chữ nhật ABCD có khả năng quay quanh trục cố định (đường nét đứt) với hai đầu khung dây gắn với cổ góp (là hai bản kim loại hình bán khuyên, cách điện với nhau). Cấp điện cho khung dây bằng cách mắc hai cực nguồn điện một chiều với hai chổi than (tiếp xúc với cổ góp). Toàn bộ khung dây đặt giữa hai cực của nam châm vĩnh cửu. Khi khung dây quay, các đầu khung dây luôn tiếp xúc với vành bán khuyên. Biết cảm ứng từ giữa hai cực nam châm có độ lớn B = 10−3 T chiều dài đoạn dây BC là 20 cm, dòng điện chạy trong khung dây có cường độ I = 1 A thì độ lớn lực từ tác dụng lên đoạn BC là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045392962-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cạnh BC song song với trục quay nên vuông góc với $\\vec B$ (từ cực N sang cực S), do đó $\\sin\\theta=1$ và $F=BI\\ell\\sin\\theta=BI\\ell$.</p><p class=\"text-base leading-relaxed my-2\">$F=10^{-3}\\cdot1\\cdot0{,}2=2\\cdot10^{-4}$ N (đã đổi $\\ell=20$ cm $=0{,}2$ m).</p><p class=\"text-base leading-relaxed my-2\">Không đúng vì: D ($2\\cdot10^{-2}$ N) là $10^{-3}\\cdot1\\cdot20$, tức quên đổi $20$ cm sang mét; A và C có hệ số 6 không ứng với phép tính nào của dữ kiện, $6\\cdot10^{-4}$ N và $6\\cdot10^{-2}$ N không bằng $BI\\ell$.</p><p class=\"text-base leading-relaxed my-2\">Chọn B.</p>","difficultySource":"ai"},"ex":[{"exam":281,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":1,"options":["F = 6.10<sup>−4</sup> N","F = 2.10<sup>−4</sup> N","F = 6.10<sup>−2</sup> N","F = 2.10<sup>−2</sup> N"],"question":"Hình vẽ bên cạnh mô tả mô hình động cơ điện. Một khung dây dẫn hình chữ nhật ABCD có khả năng quay quanh trục cố định (đường nét đứt) với hai đầu khung dây gắn với cổ góp (là hai bản kim loại hình bán khuyên, cách điện với nhau). Cấp điện cho khung dây bằng cách mắc hai cực nguồn điện một chiều với hai chổi than (tiếp xúc với cổ góp). Toàn bộ khung dây đặt giữa hai cực của nam châm vĩnh cửu. Khi khung dây quay, các đầu khung dây luôn tiếp xúc với vành bán khuyên. Biết cảm ứng từ giữa hai cực nam châm có độ lớn B = 10−3 T chiều dài đoạn dây BC là 20 cm, dòng điện chạy trong khung dây có cường độ I = 1 A thì độ lớn lực từ tác dụng lên đoạn BC là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045392962-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"$F=B.I.ℓ=10^{−3}.1.0,2=2.10^{−4}\\left(N\\right)$","difficultySource":"ai"}}]},{"id":578130,"nq":{"form":"bai_tap","type":"true_false","topic":"Hiện tượng phóng xạ. Chu kì bán rã","question":"Hình vẽ bên mô tả sơ đồ hoạt động đơn giản hoá của cảm biến báo khói ion hoá. Nguồn phóng xạ α americium  ${}_{95}^{241}Am$  có chu kỳ bán rã T = 432,2 năm (lấy 1 năm bằng 365 ngày) được đặt giữa hai bản kim loại kết nối với một pin. Các hạt α phóng ra làm ion hoá không khí giữa hai bản kim loại, cho phép một dòng điện nhỏ chạy giữa hai bản kim loại đó và chuông báo không kêu. Nếu có khói bay vào giữa hai bản kim loại, các ion trong này sẽ kết hợp với những phân tử khói và dịch chuyển chậm hơn làm cường độ dòng điện chạy giữa hai bản kim loại giảm đi. Khi dòng điện giảm tới mức nhất định thì cảm biến báo khói sẽ gửi tín hiệu kích hoạt chuông báo cháy. Lấy NA = 6,023.10<sup>23</sup> mol-1 và khối lượng mol của  ${}_{95}^{241}Am$ là 241 g/mol. Các ý a), b), c), d) dưới đây là đúng hay sai?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045394675-hinh-20.jpg\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Hằng số phóng xạ của americium  ${}_{95}^{241}Am$  là 1,604.10<sup>−3</sup> (s-1).","answer":false},{"text":"Độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$ có khối lượng 0,5 µg là 63,55 kBq.","answer":true},{"text":"Tia α phát ra từ nguồn phóng xạ bị lệch về phía bản kim loại nhiễm điện âm.","answer":true},{"text":"Sau khi sử dụng 45 năm, độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$  trong cảm biến giảm còn 93,04% so với độ phóng xạ ban đầu lúc mới mua","answer":true}],"explanation":"a) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{432,2.365.24.3600}=5,09.10^{−11}\\left(s^{−1}\\right)$<br>b) đúng<br>$H=\\lambda N=\\lambda \\frac{m}{\\mu }N_A=\\lambda .\\frac{0,5.10^{−6}}{241}.6,023.10^{23}\\approx 63,55\\left(kBq\\right)$<br>c) đúng<br>Tia α phát ra từ nguồn phóng xạ bị lệch về phía bản kim loại nhiễm điện âm.<br>d) đúng<br>$\\frac{H}{H_0}=2^{−\\frac{t}{T}}=2^{\\frac{−45}{43,2}}\\approx 0,9304=93,04%$","difficultySource":"ai"},"ex":[{"exam":281,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Hiện tượng phóng xạ. Chu kì bán rã","question":"Hình vẽ bên mô tả sơ đồ hoạt động đơn giản hoá của cảm biến báo khói ion hoá. Nguồn phóng xạ α americium  ${}_{95}^{241}Am$  có chu kỳ bán rã T = 432,2 năm (lấy 1 năm bằng 365 ngày) được đặt giữa hai bản kim loại kết nối với một pin. Các hạt α phóng ra làm ion hoá không khí giữa hai bản kim loại, cho phép một dòng điện nhỏ chạy giữa hai bản kim loại đó và chuông báo không kêu. Nếu có khói bay vào giữa hai bản kim loại, các ion trong này sẽ kết hợp với những phân tử khói và dịch chuyển chậm hơn làm cường độ dòng điện chạy giữa hai bản kim loại giảm đi. Khi dòng điện giảm tới mức nhất định thì cảm biến báo khói sẽ gửi tín hiệu kích hoạt chuông báo cháy. Lấy NA = 6,023.10<sup>23</sup> mol-1 và khối lượng mol của  ${}_{95}^{241}Am$ là 241 g/mol. Các ý a), b), c), d) dưới đây là đúng hay sai?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045394675-hinh-20.jpg\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Hằng số phóng xạ của americium  ${}_{95}^{241}Am$  là 1,604.10<sup>−3</sup> (s-1).","answer":false},{"text":"Độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$ có khối lượng 0,5 µg là 63,55 kBq.","answer":true},{"text":"Tia α phát ra từ nguồn phóng xạ bị lệch về phía bản kim loại nhiễm điện âm.","answer":true},{"text":"Sau khi sử dụng 45 năm, độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$  trong cảm biến giảm còn 93,04% so với độ phóng xạ ban đầu lúc mới mua","answer":true}],"explanation":"a) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{432,2.365.24.3600}=5,09.10^{−11}\\left(s^{−1}\\right)$<br>b) đúng<br>$H=\\lambda N=\\lambda \\frac{m}{\\mu }N_A=\\lambda .\\frac{0,5.10^{−6}}{241}.6,023.10^{23}\\approx 63,55\\left(kBq\\right)$<br>c) đúng<br>Tia α phát ra từ nguồn phóng xạ bị lệch về phía bản kim loại nhiễm điện âm.<br>d) đúng<br>$\\frac{H}{H_0}=2^{−\\frac{t}{T}}=2^{\\frac{−45}{43,2}}\\approx 0,9304=93,04%$","difficultySource":"ai"}}]},{"id":578133,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Boyle. Định luật Charles","answer":"2,4","question":"Một bình kín có thể tích không đổi chứa khí lí tưởng ở áp suất 1,8.10<sup>5</sup> Pa và nhiệt độ 270C. Khi nhiệt độ trong bình tăng tới 1270C thì áp suất khí trong bình là x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu?","difficulty":"de","explanation":"$\\frac{p_1}{T_1}=\\frac{p_2}{T_2}\\Rightarrow \\frac{1,8.10^5}{27+273}=\\frac{p_2}{127+273}\\Rightarrow p_2=2,4.10^5\\left(Pa\\right)\\Rightarrow x=2,4$","difficultySource":"ai"},"ex":[{"exam":281,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Boyle. Định luật Charles","answer":"2,4","question":"Một bình kín có thể tích không đổi chứa khí lí tưởng ở áp suất 1,8.10<sup>5</sup> Pa và nhiệt độ 270C. Khi nhiệt độ trong bình tăng tới 1270C thì áp suất khí trong bình là x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu?","difficulty":"de","explanation":"$\\frac{p_1}{T_1}=\\frac{p_2}{T_2}\\Rightarrow \\frac{1,8.10^5}{27+273}=\\frac{p_2}{127+273}\\Rightarrow p_2=2,4.10^5\\left(Pa\\right)\\Rightarrow x=2,4$","difficultySource":"ai"}}]},{"id":578135,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"26,2","question":"Một vật có khối lượng m0 (kg) được làm từ vật liệu có nhiệt dung riêng c phụ thuộc vào nhiệt độ t theo quy luật c(t) = c0(1 + αt) trong đó c0 = 1,3.10<sup>3</sup> J/kg.K và α = 0,012 K-1. Đưa vật vào nhiệt lượng kế chứa 0,5m0 (kg) nước ở nhiệt độ t01 = 450C. Biết nhiệt độ ban đầu của vật là t0 = 0°C nhiệt dung riêng của nước là c1 = 4200 J/kg.K. Bỏ qua nhiệt dung của nhiệt lượng kế và tổn thất nhiệt. Tìm nhiệt độ ổn định của nước trong nhiệt lượng kế? Kết quả tính bằng 0C và làm tròn đến một chữ số thập phân.","difficulty":"kho","explanation":"$Q_{toa\\left(nuoc\\right)}=Q_{thu\\left(vat\\right)}$<br>$\\Leftrightarrow 0,5m_0.4200\\left(45−t\\right)=m_0cdt0t∫$  ( $c\\Delta t$  không đổi  $\\Rightarrow cdt∫$ )<br>$\\Rightarrow 2100.\\left(45−t\\right)=c_0\\left(1+\\alpha t\\right)dt0t∫=c_0dt+c_0.\\alpha .tdt0t∫=c_0t+c_0\\alpha \\frac{t^2}{2}\\left|\\begin{aligned}t <br>0\\end{aligned}\\right|$<br>$\\Rightarrow 2100\\left(45−t\\right)=1,3.10^3t+1,3.10^3.0,012.\\frac{t^2}{2}$<br>$\\Rightarrow t\\approx 26,2\\left({}^0C\\right)$","difficultySource":"ai"},"ex":[{"exam":281,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"26,2","question":"Một vật có khối lượng m0 (kg) được làm từ vật liệu có nhiệt dung riêng c phụ thuộc vào nhiệt độ t theo quy luật c(t) = c0(1 + αt) trong đó c0 = 1,3.10<sup>3</sup> J/kg.K và α = 0,012 K-1. Đưa vật vào nhiệt lượng kế chứa 0,5m0 (kg) nước ở nhiệt độ t01 = 450C. Biết nhiệt độ ban đầu của vật là t0 = 0°C nhiệt dung riêng của nước là c1 = 4200 J/kg.K. Bỏ qua nhiệt dung của nhiệt lượng kế và tổn thất nhiệt. Tìm nhiệt độ ổn định của nước trong nhiệt lượng kế? Kết quả tính bằng 0C và làm tròn đến một chữ số thập phân.","difficulty":"kho","explanation":"$Q_{toa\\left(nuoc\\right)}=Q_{thu\\left(vat\\right)}$<br>$\\Leftrightarrow 0,5m_0.4200\\left(45−t\\right)=m_0cdt0t∫$  ( $c\\Delta t$  không đổi  $\\Rightarrow cdt∫$ )<br>$\\Rightarrow 2100.\\left(45−t\\right)=c_0\\left(1+\\alpha t\\right)dt0t∫=c_0dt+c_0.\\alpha .tdt0t∫=c_0t+c_0\\alpha \\frac{t^2}{2}\\left|\\begin{aligned}t <br>0\\end{aligned}\\right|$<br>$\\Rightarrow 2100\\left(45−t\\right)=1,3.10^3t+1,3.10^3.0,012.\\frac{t^2}{2}$<br>$\\Rightarrow t\\approx 26,2\\left({}^0C\\right)$","difficultySource":"ai"}}]},{"id":578804,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":1,"options":["Tăng thêm 6,4.10<sup>5</sup> Pa.","Giảm đi 6,4.10<sup>5</sup> Pa.","Giảm đi 1,6.10<sup>5</sup> Pa.","Tăng thêm 1,6.10<sup>6</sup> Pa."],"question":"Một lượng khí lí tưởng được giãn nở đẳng nhiệt từ trạng thái có thể tích V1 = 1 lít sang trạng thái có thể tích V2 = 5 lít. Cho biết áp suất ban đầu của lượng khí là p1 = 8.10<sup>5</sup> Pa. Sau khi biến đổi, áp suất p2 của lượng khí thay đổi như thế nào so với lúc đầu?","difficulty":"de","explanation":"$p_1.V_1=p_2.V_2\\rightarrow p_2=\\frac{p_1.V_1}{V_2}=1,6.10^5$  Pa<br>Độ giảm áp suất:  $\\Delta p=p_1-p_2=6,4.10^5$  Pa","difficultySource":"ai"},"ex":[{"exam":282,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":1,"options":["Tăng thêm 6,4.10<sup>5</sup> Pa.","Giảm đi 6,4.10<sup>5</sup> Pa.","Giảm đi 1,6.10<sup>5</sup> Pa.","Tăng thêm 1,6.10<sup>6</sup> Pa."],"question":"Một lượng khí lí tưởng được giãn nở đẳng nhiệt từ trạng thái có thể tích V1 = 1 lít sang trạng thái có thể tích V2 = 5 lít. Cho biết áp suất ban đầu của lượng khí là p1 = 8.10<sup>5</sup> Pa. Sau khi biến đổi, áp suất p2 của lượng khí thay đổi như thế nào so với lúc đầu?","difficulty":"de","explanation":"$p_1.V_1=p_2.V_2\\rightarrow p_2=\\frac{p_1.V_1}{V_2}=1,6.10^5$  Pa<br>Độ giảm áp suất:  $\\Delta p=p_1-p_2=6,4.10^5$  Pa","difficultySource":"ai"}}]},{"id":578808,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Áp suất và động năng phân tử khí","answer":1,"options":["$4,114.10^{25}$ .","$1,144.10^{25}$ .","$4,008.10^{25}$ .","$5,4224.10^{28}$ ."],"question":"Một bình kín chứa khí hydrogen với thể tích 0,5  $m^3$  và áp suất 1,013.10<sup>5</sup> Pa. Cho biết trung bình của các bình phương tốc độ là 4.10<sup>6</sup> m2/s2 . Số phân tử khí chứa trong bình là","difficulty":"trung-binh","explanation":"$p.V= N.k.T\\rightarrow T=\\frac{p.V}{N.k}$  (1)<br>Mặt khác:  $\\overline{v^2}=\\frac{3RT}{M}\\rightarrow T=\\frac{\\overline{v^2}.M}{3R}$  (2)<br>Từ (1) và (2) suy ra:  $\\frac{p.V}{N.k}=\\frac{\\overline{v^2}.M}{3R}\\rightarrow N=\\frac{p.V.3R}{k.\\overline{v^2}.M}=1,144.10^{25}$  phân tử.","difficultySource":"ai"},"ex":[{"exam":282,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Áp suất và động năng phân tử khí","answer":1,"options":["$4,114.10^{25}$ .","$1,144.10^{25}$ .","$4,008.10^{25}$ .","$5,4224.10^{28}$ ."],"question":"Một bình kín chứa khí hydrogen với thể tích 0,5  $m^3$  và áp suất 1,013.10<sup>5</sup> Pa. Cho biết trung bình của các bình phương tốc độ là 4.10<sup>6</sup> m2/s2 . Số phân tử khí chứa trong bình là","difficulty":"trung-binh","explanation":"$p.V= N.k.T\\rightarrow T=\\frac{p.V}{N.k}$  (1)<br>Mặt khác:  $\\overline{v^2}=\\frac{3RT}{M}\\rightarrow T=\\frac{\\overline{v^2}.M}{3R}$  (2)<br>Từ (1) và (2) suy ra:  $\\frac{p.V}{N.k}=\\frac{\\overline{v^2}.M}{3R}\\rightarrow N=\\frac{p.V.3R}{k.\\overline{v^2}.M}=1,144.10^{25}$  phân tử.","difficultySource":"ai"}}]},{"id":578810,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":0,"options":["2,5.105 T.","2,8.105 T.","1,9.10<sup>−5</sup> T.","1,6.10<sup>−5</sup> T."],"question":"Một đoạn dây dẫn thẳng dài l = 2,0 m mang dòng điện I = 5,0 A được đặt nằm ngang, hướng của dòng điện hợp với hướng từ trường Trái Đất một góc 30°. Tại nơi đặt đoạn dây từ trường của Trái Đất coi như từ trường đều và có độ lớn B.  Lực từ tác dụng lên đoạn dây có độ lớn là F = 1,25.10<sup>−4</sup> N. Cảm ứng từ B của từ trường Trái Đất có độ lớn là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045402092-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ: $F=BIl\\sin\\theta$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow B=\\dfrac{F}{Il\\sin\\theta}=\\dfrac{1{,}25\\cdot10^{-4}}{5{,}0\\cdot2{,}0\\cdot\\sin30^\\circ}=2{,}5\\cdot10^{-5}$ T.</p><p class=\"text-base leading-relaxed my-2\">Chọn A (đề ghi mất dấu trừ ở số mũ nên A là $2{,}5\\cdot10^{-5}$ T).</p>","difficultySource":"ai"},"ex":[{"exam":282,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":0,"options":["2,5.105 T.","2,8.105 T.","1,9.10<sup>−5</sup> T.","1,6.10<sup>−5</sup> T."],"question":"Một đoạn dây dẫn thẳng dài l = 2,0 m mang dòng điện I = 5,0 A được đặt nằm ngang, hướng của dòng điện hợp với hướng từ trường Trái Đất một góc 30°. Tại nơi đặt đoạn dây từ trường của Trái Đất coi như từ trường đều và có độ lớn B.  Lực từ tác dụng lên đoạn dây có độ lớn là F = 1,25.10<sup>−4</sup> N. Cảm ứng từ B của từ trường Trái Đất có độ lớn là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045402092-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Vì  $F=B.I.l.sin\\alpha \\rightarrow B= \\frac{F}{I.l.sin\\alpha }=2,5.105 T$","difficultySource":"ai"}}]},{"id":578817,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["$24110,1 kg$ .","$14720,6 kg$ .","$16245,7 kg$ .","$12657,8 kg$ ."],"question":"Trong lõi mặt trời, quá trình nhiệt hạch chính là sự kết hợp 4 proton để tạo thành một hạt nhân  ${}_{}^4{He}$ , kèm theo việc giải phóng năng lượng khoảng 26,7 MeV mỗi phản ứng. Cho biết năng suất toả nhiệt của than đá là 3,2.10<sup>7</sup> J/kg. Khối lượng than đá cần đốt cháy để toả ra năng lượng tương đương với 1,2 g proton tham gia nhiệt hạch là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045402438-hinh-3.webp\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Ta có: Số hạt nhân proton có trong 1,2 g là:   $N=\\frac{m}{M}.N_A=7,224.10^{23}$  hạt.<br>Năng lượng toả ra khi 1,2 g proton tham gia phản ứng:  $Q=\\frac{N}{4}.26,7.1,6.10^{-13}=7,72.10^{11} J$ .","difficultySource":"ai"},"ex":[{"exam":282,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["$24110,1 kg$ .","$14720,6 kg$ .","$16245,7 kg$ .","$12657,8 kg$ ."],"question":"Trong lõi mặt trời, quá trình nhiệt hạch chính là sự kết hợp 4 proton để tạo thành một hạt nhân  ${}_{}^4{He}$ , kèm theo việc giải phóng năng lượng khoảng 26,7 MeV mỗi phản ứng. Cho biết năng suất toả nhiệt của than đá là 3,2.10<sup>7</sup> J/kg. Khối lượng than đá cần đốt cháy để toả ra năng lượng tương đương với 1,2 g proton tham gia nhiệt hạch là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045402438-hinh-3.webp\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Ta có: Số hạt nhân proton có trong 1,2 g là:   $N=\\frac{m}{M}.N_A=7,224.10^{23}$  hạt.<br>Năng lượng toả ra khi 1,2 g proton tham gia phản ứng:  $Q=\\frac{N}{4}.26,7.1,6.10^{-13}=7,72.10^{11} J$ .","difficultySource":"ai"}}]},{"id":578825,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2620","question":"Một người cần đun sôi 5 lít nước từ 30°C lên khi sôi 100°C, nhưng vì không chú ý nên khi rót nước sôi ra chỉ còn 4,5 lít. Cho biết nhiệt dung riêng của nước là 4200 J/kg.K, nhiệt hoá hơi riêng của nước là L = 2,3.10<sup>6</sup> J/kg và khối lượng riêng của nước là 1000 kg/m3. Nhiệt lượng cần thiết để cung cấp cho lượng nước là bao nhiêu kJ (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng nước ban đầu: $m = D\\cdot V = 1000\\cdot 5\\cdot 10^{-3} = 5\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng nước đã hóa hơi (thất thoát khi rót): $\\Delta m = 5 - 4{,}5 = 0{,}5\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần để đun 5 kg nước từ 30°C lên 100°C: $Q_1 = m c \\Delta t = 5\\cdot 4200\\cdot (100-30) = 1\\,470\\,000\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần để làm hóa hơi 0,5 kg nước ở 100°C: $Q_2 = \\Delta m\\cdot L = 0{,}5\\cdot 2{,}3\\cdot 10^{6} = 1\\,150\\,000\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Tổng nhiệt lượng: $Q = Q_1 + Q_2 = 1\\,470\\,000 + 1\\,150\\,000 = 2\\,620\\,000\\ \\text{J} = 2620\\ \\text{kJ}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: nhiệt lượng cần cung cấp là $Q \\approx 2620$ kJ.</p>","difficultySource":"ai"},"ex":[{"exam":282,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2620","question":"Một người cần đun sôi 5 lít nước từ 30°C lên khi sôi 100°C, nhưng vì không chú ý nên khi rót nước sôi ra chỉ còn 4,5 lít. Cho biết nhiệt dung riêng của nước là 4200 J/kg.K, nhiệt hoá hơi riêng của nước là L = 2,3.10<sup>6</sup> J/kg và khối lượng riêng của nước là 1000 kg/m3. Nhiệt lượng cần thiết để cung cấp cho lượng nước là bao nhiêu kJ (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"$Q_{thu}=m.c.\\Delta t+L.m^'=2620000 J=2620 kJ.$","difficultySource":"ai"}}]},{"id":579726,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":0,"options":["3,95.10<sup>21</sup> phân tử.","4,36.10<sup>21</sup> phân tử.","1,88.10<sup>22</sup> phân tử.","2,08.10<sup>22</sup> phân tử."],"question":"Không khí là hỗn hợp khí có chứa oxygen chiếm 21% về khối lượng. Biết khối lượng mol của phân tử oxygen là 32 g/mol. Số phân tử oxygen có trong 1 g không khí xấp xỉ bằng","difficulty":"de","explanation":"Khối lượng oxygen có trong 1g không khí là:  $m=21%.1=0,21$  g.<br>Số phân tử oxygen:  $N_{O_2}=\\frac{m_{O_2}}{M_{0_2}}.N_A=\\frac{0,21 }{32}. 6,02.{10}^{23}\\approx 3,95.{10}^{21}$  phân tử.","difficultySource":"ai"},"ex":[{"exam":283,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":0,"options":["3,95.10<sup>21</sup> phân tử.","4,36.10<sup>21</sup> phân tử.","1,88.10<sup>22</sup> phân tử.","2,08.10<sup>22</sup> phân tử."],"question":"Không khí là hỗn hợp khí có chứa oxygen chiếm 21% về khối lượng. Biết khối lượng mol của phân tử oxygen là 32 g/mol. Số phân tử oxygen có trong 1 g không khí xấp xỉ bằng","difficulty":"de","explanation":"Khối lượng oxygen có trong 1g không khí là:  $m=21%.1=0,21$  g.<br>Số phân tử oxygen:  $N_{O_2}=\\frac{m_{O_2}}{M_{0_2}}.N_A=\\frac{0,21 }{32}. 6,02.{10}^{23}\\approx 3,95.{10}^{21}$  phân tử.","difficultySource":"ai"}}]},{"id":583750,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":2,"options":["0,471 ℓ.","0,523 ℓ.","0,314 ℓ.","0,262 ℓ."],"question":"Một xi lanh có pit tông di chuyển được và chứa một lượng khí lí tưởng ở nhiệt độ 30 °C, thể tích 0,785 ℓ và áp suất 1,2.10<sup>5</sup> Pa. Thực hiện nén khí đẳng nhiệt đến áp suất 2.10<sup>5</sup> Pa thì thể tích của lượng khí giảm đi","difficulty":"trung-binh","explanation":"Công thức: định luật Boyle cho quá trình đẳng nhiệt p1V1 = p2V2.<br>Thay số: p1 = 1,2.10⁵ Pa, V1 = 0,785 ℓ, p2 = 2.10⁵ Pa → V2 = p1V1/p2 = 1,2.10⁵.0,785/2.10⁵ = 0,471 ℓ; thể tích giảm ΔV = V1 − V2 = 0,785 − 0,471.<br>Kết quả: ΔV = 0,314 ℓ. Đáp án C.<br>Áp dụng định luật Boyle, ta có:<br>$p_1.V_1=p_2.V_2$    $V_2=\\frac{p_1.V_1}{p_2}=\\frac{1,2.{10}^5.0,785}{2.{10}^5}=0,471$  (ℓ)<br>Thể tích của lượng khí đã giảm đi một lượng là: 0,785 – 0,471 = 0,314 (ℓ).","difficultySource":"ai"},"ex":[{"exam":288,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":2,"options":["0,471 ℓ.","0,523 ℓ.","0,314 ℓ.","0,262 ℓ."],"question":"Một xi lanh có pit tông di chuyển được và chứa một lượng khí lí tưởng ở nhiệt độ 30 °C, thể tích 0,785 ℓ và áp suất 1,2.10<sup>5</sup> Pa. Thực hiện nén khí đẳng nhiệt đến áp suất 2.10<sup>5</sup> Pa thì thể tích của lượng khí giảm đi","difficulty":"trung-binh","explanation":"Công thức: định luật Boyle cho quá trình đẳng nhiệt p1V1 = p2V2.<br>Thay số: p1 = 1,2.10⁵ Pa, V1 = 0,785 ℓ, p2 = 2.10⁵ Pa → V2 = p1V1/p2 = 1,2.10⁵.0,785/2.10⁵ = 0,471 ℓ; thể tích giảm ΔV = V1 − V2 = 0,785 − 0,471.<br>Kết quả: ΔV = 0,314 ℓ. Đáp án C.<br>Áp dụng định luật Boyle, ta có:<br>$p_1.V_1=p_2.V_2$    $V_2=\\frac{p_1.V_1}{p_2}=\\frac{1,2.{10}^5.0,785}{2.{10}^5}=0,471$  (ℓ)<br>Thể tích của lượng khí đã giảm đi một lượng là: 0,785 – 0,471 = 0,314 (ℓ).","difficultySource":"ai"}}]},{"id":583762,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":3,"options":["20 197,14 tấn.","20 190,48 tấn.","20 167 tấn.","20 188 tấn."],"question":"Bom hydrogen (bom H) là một loại vũ khí hạt nhân có sức tàn phá lớn hơn bom nguyên tử (bom A) rất nhiều lần, dù hiện nay cả bom hydrogen và bom nguyên tử đều không được sử dụng trong các cuộc chiến tranh. Sở dĩ bom hydrogen có sức tàn phá lớn như vậy là do nó là sự kết hợp của phản ứng phân hạch của  ${}_{92}^{235}U$  (giai đoạn 1) để tạo ra môi trường có nhiệt độ rất cao, cung cấp động năng cho các hạt tham gia phản ứng nhiệt hạch (giai đoạn 2) theo phương trình phản ứng  ${}_1^2H$  +  ${}_1^3H$    ${}_2^4{He}$  +  ${}_0^1n$  + 17,6 MeV.<br>Giả sử năng lượng tỏa ra từ quá trình phân hạch còn lại sau khi tạo phản ứng nhiệt hạch là 2,8.10<sup>10</sup> J và khối lượng  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là 200 g thì sức tàn phá của quả bom này tương đương với khoảng bao nhiêu tấn thuốc nổ TNT? Biết rằng năng lượng tỏa ra khi một tấn thuốc nổ TNT cháy hoàn toàn là 4,2.10<sup>9</sup> J; khối lượng nguyên tử bằng số khối của nguyên tử đó tính theo đơn vị amu.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045469835-hinh-16.webp\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Công thức: số hạt nhân He-4 sinh ra N = (m/M).N_A; năng lượng toả ra từ phản ứng nhiệt hạch E = N.17,6 MeV (đổi ra J); tổng năng lượng toả ra của cả quả bom = năng lượng phân hạch còn lại + năng lượng nhiệt hạch; số tấn TNT tương đương = tổng năng lượng / năng lượng 1 tấn TNT.<br>Thay số: N = (200/4).6,02.10²³ = 3,01.10²⁵ hạt; E = 3,01.10²⁵.17,6.10⁶.1,6.10⁻¹⁹ ≈ 8,47616.10¹³ J; tổng năng lượng = 2,8.10¹⁰ + 8,47616.10¹³ J; số tấn TNT = (2,8.10¹⁰ + 8,47616.10¹³)/4,2.10⁹.<br>Kết quả: ≈ 20188 tấn TNT. Đáp án D.<br>Số nguyên tử  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là:<br>$N=\\frac{m}{M}.N_A=\\frac{200}{4}.6,02.{10}^{23}=3,01.{10}^{25}$  nguyên tử.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Tổng năng lượng tỏa ra của các phản ứng nhiệt hạch là:<br>$3,01.{10}^{25}.17,6.{10}^6.1,6.{10}^{-19}=8,47616.{10}^{13}$  (J).<br>Tổng năng lượng tỏa ra từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là:<br>$2,8.{10}^{10}+8,47616.{10}^{13}$  (J).<br>Lượng thuốc nổ TNT cháy hoàn toàn để có năng lượng tỏa ra bằng với năng lượng tỏa ra từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân đã cho là:<br>$\\frac{2,8.{10}^{10}+8,47616.{10}^{13}}{4,2.{10}^9}=20 188$  tấn.","difficultySource":"ai"},"ex":[{"exam":288,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":3,"options":["20 197,14 tấn.","20 190,48 tấn.","20 167 tấn.","20 188 tấn."],"question":"Bom hydrogen (bom H) là một loại vũ khí hạt nhân có sức tàn phá lớn hơn bom nguyên tử (bom A) rất nhiều lần, dù hiện nay cả bom hydrogen và bom nguyên tử đều không được sử dụng trong các cuộc chiến tranh. Sở dĩ bom hydrogen có sức tàn phá lớn như vậy là do nó là sự kết hợp của phản ứng phân hạch của  ${}_{92}^{235}U$  (giai đoạn 1) để tạo ra môi trường có nhiệt độ rất cao, cung cấp động năng cho các hạt tham gia phản ứng nhiệt hạch (giai đoạn 2) theo phương trình phản ứng  ${}_1^2H$  +  ${}_1^3H$    ${}_2^4{He}$  +  ${}_0^1n$  + 17,6 MeV.<br>Giả sử năng lượng tỏa ra từ quá trình phân hạch còn lại sau khi tạo phản ứng nhiệt hạch là 2,8.10<sup>10</sup> J và khối lượng  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là 200 g thì sức tàn phá của quả bom này tương đương với khoảng bao nhiêu tấn thuốc nổ TNT? Biết rằng năng lượng tỏa ra khi một tấn thuốc nổ TNT cháy hoàn toàn là 4,2.10<sup>9</sup> J; khối lượng nguyên tử bằng số khối của nguyên tử đó tính theo đơn vị amu.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045469835-hinh-16.webp\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Công thức: số hạt nhân He-4 sinh ra N = (m/M).N_A; năng lượng toả ra từ phản ứng nhiệt hạch E = N.17,6 MeV (đổi ra J); tổng năng lượng toả ra của cả quả bom = năng lượng phân hạch còn lại + năng lượng nhiệt hạch; số tấn TNT tương đương = tổng năng lượng / năng lượng 1 tấn TNT.<br>Thay số: N = (200/4).6,02.10²³ = 3,01.10²⁵ hạt; E = 3,01.10²⁵.17,6.10⁶.1,6.10⁻¹⁹ ≈ 8,47616.10¹³ J; tổng năng lượng = 2,8.10¹⁰ + 8,47616.10¹³ J; số tấn TNT = (2,8.10¹⁰ + 8,47616.10¹³)/4,2.10⁹.<br>Kết quả: ≈ 20188 tấn TNT. Đáp án D.<br>Số nguyên tử  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là:<br>$N=\\frac{m}{M}.N_A=\\frac{200}{4}.6,02.{10}^{23}=3,01.{10}^{25}$  nguyên tử.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Tổng năng lượng tỏa ra của các phản ứng nhiệt hạch là:<br>$3,01.{10}^{25}.17,6.{10}^6.1,6.{10}^{-19}=8,47616.{10}^{13}$  (J).<br>Tổng năng lượng tỏa ra từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là:<br>$2,8.{10}^{10}+8,47616.{10}^{13}$  (J).<br>Lượng thuốc nổ TNT cháy hoàn toàn để có năng lượng tỏa ra bằng với năng lượng tỏa ra từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân đã cho là:<br>$\\frac{2,8.{10}^{10}+8,47616.{10}^{13}}{4,2.{10}^9}=20 188$  tấn.","difficultySource":"ai"}}]},{"id":583768,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"1544","question":"Một bình Oxy y tế có thể tích 10 lít, chứa khí oxygen ở áp suất 1,5.10<sup>7</sup> Pa và nhiệt độ 25 C. Sau một thời gian sử dụng, nhiệt độ và áp suất của khối khí trong bình giảm còn 20 C và 3.10<sup>6</sup> Pa. Biết khối lượng phân tử khí oxygen là 32 g/mol. Lượng khí oxygen đã sử dụng theo đơn vị gram (g) (làm tròn kết quả đến hàng đơn vị) bằng bao nhiêu ?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045471742-hinh-22.png\" alt=\"Hình 22\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Công thức: phương trình Clapeyron cho khối khí trong bình ở hai thời điểm p.V=(m/M).R.T ⟹ m=M.p.V/(R.T); khối lượng khí đã dùng Δm=m0−m.<br>Thay số: M=32 g/mol, V=10 lít=10.10⁻³ m³; m0 = 32.1,5.10⁷.10.10⁻³/(8,31.298); m = 32.3.10⁶.10.10⁻³/(8,31.293).<br>Kết quả: Δm = m0 − m ≈ 1544 g. Đáp số: 1544.<br>Áp dụng phương trình Clapeyron cho lượng khí oxygen trong bình ở trạng thái trước khi sử dụng, ta có:<br>$p_0.V_0=\\frac{m_0}{M}.R.T_0$    $m_0=\\frac{M.p_0.V_0}{R.T_0}$<br>Áp dụng phương trình Clapeyron cho lượng khí oxygen trong bình ở trạng thái sau khi sử dụng, ta có:<br>$p.V=\\frac{m}{M}.R.T$    $m=\\frac{M.p.V}{RT}$<br>Lượng khí oxygen đã sử dụng là:<br>$\\Delta m=m_0-m=\\frac{M.p_0.V_0}{R.T_0}-\\frac{M.p.V}{RT}=\\frac{32.1,5.{10}^7.10.{10}^{-3}}{8,31.\\left(25+273\\right)}-\\frac{32.3.{10}^6.10.{10}^{-3}}{8,31.\\left(20+273\\right)}=1 544$  (g).","difficultySource":"ai"},"ex":[{"exam":288,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"1544","question":"Một bình Oxy y tế có thể tích 10 lít, chứa khí oxygen ở áp suất 1,5.10<sup>7</sup> Pa và nhiệt độ 25 C. Sau một thời gian sử dụng, nhiệt độ và áp suất của khối khí trong bình giảm còn 20 C và 3.10<sup>6</sup> Pa. Biết khối lượng phân tử khí oxygen là 32 g/mol. Lượng khí oxygen đã sử dụng theo đơn vị gram (g) (làm tròn kết quả đến hàng đơn vị) bằng bao nhiêu ?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045471742-hinh-22.png\" alt=\"Hình 22\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Công thức: phương trình Clapeyron cho khối khí trong bình ở hai thời điểm p.V=(m/M).R.T ⟹ m=M.p.V/(R.T); khối lượng khí đã dùng Δm=m0−m.<br>Thay số: M=32 g/mol, V=10 lít=10.10⁻³ m³; m0 = 32.1,5.10⁷.10.10⁻³/(8,31.298); m = 32.3.10⁶.10.10⁻³/(8,31.293).<br>Kết quả: Δm = m0 − m ≈ 1544 g. Đáp số: 1544.<br>Áp dụng phương trình Clapeyron cho lượng khí oxygen trong bình ở trạng thái trước khi sử dụng, ta có:<br>$p_0.V_0=\\frac{m_0}{M}.R.T_0$    $m_0=\\frac{M.p_0.V_0}{R.T_0}$<br>Áp dụng phương trình Clapeyron cho lượng khí oxygen trong bình ở trạng thái sau khi sử dụng, ta có:<br>$p.V=\\frac{m}{M}.R.T$    $m=\\frac{M.p.V}{RT}$<br>Lượng khí oxygen đã sử dụng là:<br>$\\Delta m=m_0-m=\\frac{M.p_0.V_0}{R.T_0}-\\frac{M.p.V}{RT}=\\frac{32.1,5.{10}^7.10.{10}^{-3}}{8,31.\\left(25+273\\right)}-\\frac{32.3.{10}^6.10.{10}^{-3}}{8,31.\\left(20+273\\right)}=1 544$  (g).","difficultySource":"ai"}}]},{"id":583771,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"0,70","question":"Đồng vị phóng xạ chromium  ${}_{24}^{51}{Cr}$  được sử dụng trong phương pháp nguyên tử đánh dấu của y học hạt nhân khi chẩn đoán các bệnh về thận và huyết học. Chu kì bán rã và khối lượng nguyên tử chromium  ${}_{24}^{51}{Cr}$  lần lượt là 27,7 ngày và 51 amu. Mẫu chromium  ${}_{24}^{51}{Cr}$  nguyên chất với độ phóng xạ 23,9.10<sup>11</sup> Bq có khối lượng bao nhiêu mg (làm tròn kết quả đến hàng phần trăm)?","difficulty":"trung-binh","explanation":"Công thức: độ phóng xạ H=λN=(ln2/T).(m/M).N_A ⟹ m=H.T.M/(N_A.ln2).<br>Thay số: H=23,9.10¹¹ Bq, T=27,7 ngày=27,7.24.3600 s, M=51 g/mol, N_A=6,02.10²³ → m=23,9.10¹¹.27,7.24.3600.51/(6,02.10²³.ln2).<br>Kết quả: m ≈ 0,70 mg. Đáp số: 0,70.<br>Khối lượng của mẫu chromium  ${}_{24}^{51}{Cr}$  nguyên chất có độ phóng xạ 23,9.10<sup>11</sup> Bq là:<br>$H=.N=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m}{M}.N_A$    $m=\\frac{H.T.M}{N_A.\\ln\\left(2\\right)}=\\frac{23,9.{10}^{11}.27,7.24.3600.51}{6,02.{10}^{23}.\\ln\\left(2\\right)}\\approx 0,70$  mg.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":288,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"0,70","question":"Đồng vị phóng xạ chromium  ${}_{24}^{51}{Cr}$  được sử dụng trong phương pháp nguyên tử đánh dấu của y học hạt nhân khi chẩn đoán các bệnh về thận và huyết học. Chu kì bán rã và khối lượng nguyên tử chromium  ${}_{24}^{51}{Cr}$  lần lượt là 27,7 ngày và 51 amu. Mẫu chromium  ${}_{24}^{51}{Cr}$  nguyên chất với độ phóng xạ 23,9.10<sup>11</sup> Bq có khối lượng bao nhiêu mg (làm tròn kết quả đến hàng phần trăm)?","difficulty":"trung-binh","explanation":"Công thức: độ phóng xạ H=λN=(ln2/T).(m/M).N_A ⟹ m=H.T.M/(N_A.ln2).<br>Thay số: H=23,9.10¹¹ Bq, T=27,7 ngày=27,7.24.3600 s, M=51 g/mol, N_A=6,02.10²³ → m=23,9.10¹¹.27,7.24.3600.51/(6,02.10²³.ln2).<br>Kết quả: m ≈ 0,70 mg. Đáp số: 0,70.<br>Khối lượng của mẫu chromium  ${}_{24}^{51}{Cr}$  nguyên chất có độ phóng xạ 23,9.10<sup>11</sup> Bq là:<br>$H=.N=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m}{M}.N_A$    $m=\\frac{H.T.M}{N_A.\\ln\\left(2\\right)}=\\frac{23,9.{10}^{11}.27,7.24.3600.51}{6,02.{10}^{23}.\\ln\\left(2\\right)}\\approx 0,70$  mg.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":585095,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"495","question":"Biết nhiệt nóng chảy riêng của nước đá là  $\\lambda =3,3.10^5 J/kg$ . Cần cung cấp một nhiệt lượng bao nhiêu kJ để làm nóng chảy hoàn toàn  $1,5 kg$  nước đá ở  $0^∘C$ ?","difficulty":"de","explanation":"Phương pháp:<br>Nhiệt lượng chỉ cung cấp cho quá trình nóng chảy:  $Q=m\\lambda$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Cách giải:<br>Cần cung cấp một nhiệt lượng để làm nóng chảy hoàn toàn 1,5 kg nước đá ở 0°C là<br>Q = mλ = 1,5.3,3.10<sup>5</sup> = 495.103(J) = 495(kJ)","difficultySource":"ai"},"ex":[{"exam":290,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"495","question":"Biết nhiệt nóng chảy riêng của nước đá là  $\\lambda =3,3.10^5 J/kg$ . Cần cung cấp một nhiệt lượng bao nhiêu kJ để làm nóng chảy hoàn toàn  $1,5 kg$  nước đá ở  $0^∘C$ ?","difficulty":"de","explanation":"Phương pháp:<br>Nhiệt lượng chỉ cung cấp cho quá trình nóng chảy:  $Q=m\\lambda$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Cách giải:<br>Cần cung cấp một nhiệt lượng để làm nóng chảy hoàn toàn 1,5 kg nước đá ở 0°C là<br>Q = mλ = 1,5.3,3.10<sup>5</sup> = 495.103(J) = 495(kJ)","difficultySource":"ai"}}]},{"id":587112,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"0,03","question":"Hình vẽ mô tả nguyên lý hoạt động của một chiếc bàn là hơi nước. Nước ban đầu từ bình ở nhiệt độ 30°C nhỏ xuống tấm kim loại, sau đó bay hơi thành hơi nước ở 100°C. Bộ phận làm nóng có công suất điện là 1,5 kW. Giả sử toàn bộ năng lượng điện được truyền vào tấm kim loại, giúp duy trì nhiệt độ làm việc ổn định. Cho biết nhiệt dung riêng của nước là 4180 J/kg.K và nhiệt hoá hơi riêng của nước là 2,3.10<sup>6</sup> J/kg. Trong mỗi phút, bàn là tạo ra bao nhiêu gam hơi nước? (làm tròn kết quả đến quả phần trăm).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045512100-hinh-19.jpg\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":".  $Q=P.t=mc\\Delta t+L.m=m\\left(c\\Delta t+L\\right)\\rightarrow m=\\frac{Q}{\\left(c\\Delta t+L\\right)}=0,0347 g$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một hạt neutron chậm bắn vào hạt nhân  ${}_{92}^{235}U$  đang đứng yên, gây ra phản ứng phân hạch theo phương trình: n +  ${}_{92}^{235}U$ → ${}_{36}^{90}{Kr}$  +  ${}_{56}^{144}{Ba}$  + x.n. Biết năng lượng liên kết riêng của  ${}_{92}^{235}U$  là 7,60 MeV/nucleon; của  ${}_{36}^{90}{Kr}$  là 8,53 MeV/nucleon và của  ${}_{56}^{144}{Ba}$  là 8,25 MeV/nucleon.<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một hạt neutron chậm bắn vào hạt nhân  ${}_{92}^{235}U$  đang đứng yên, gây ra phản ứng phân hạch theo phương trình: n +  ${}_{92}^{235}U$ → ${}_{36}^{90}{Kr}$  +  ${}_{56}^{144}{Ba}$  + x.n. Biết năng lượng liên kết riêng của  ${}_{92}^{235}U$  là 7,60 MeV/nucleon; của  ${}_{36}^{90}{Kr}$  là 8,53 MeV/nucleon và của  ${}_{56}^{144}{Ba}$  là 8,25 MeV/nucleon.","difficultySource":"ai"},"ex":[{"exam":292,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"0,03","question":"Hình vẽ mô tả nguyên lý hoạt động của một chiếc bàn là hơi nước. Nước ban đầu từ bình ở nhiệt độ 30°C nhỏ xuống tấm kim loại, sau đó bay hơi thành hơi nước ở 100°C. Bộ phận làm nóng có công suất điện là 1,5 kW. Giả sử toàn bộ năng lượng điện được truyền vào tấm kim loại, giúp duy trì nhiệt độ làm việc ổn định. Cho biết nhiệt dung riêng của nước là 4180 J/kg.K và nhiệt hoá hơi riêng của nước là 2,3.10<sup>6</sup> J/kg. Trong mỗi phút, bàn là tạo ra bao nhiêu gam hơi nước? (làm tròn kết quả đến quả phần trăm).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045512100-hinh-19.jpg\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":".  $Q=P.t=mc\\Delta t+L.m=m\\left(c\\Delta t+L\\right)\\rightarrow m=\\frac{Q}{\\left(c\\Delta t+L\\right)}=0,0347 g$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một hạt neutron chậm bắn vào hạt nhân  ${}_{92}^{235}U$  đang đứng yên, gây ra phản ứng phân hạch theo phương trình: n +  ${}_{92}^{235}U$ → ${}_{36}^{90}{Kr}$  +  ${}_{56}^{144}{Ba}$  + x.n. Biết năng lượng liên kết riêng của  ${}_{92}^{235}U$  là 7,60 MeV/nucleon; của  ${}_{36}^{90}{Kr}$  là 8,53 MeV/nucleon và của  ${}_{56}^{144}{Ba}$  là 8,25 MeV/nucleon.<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một hạt neutron chậm bắn vào hạt nhân  ${}_{92}^{235}U$  đang đứng yên, gây ra phản ứng phân hạch theo phương trình: n +  ${}_{92}^{235}U$ → ${}_{36}^{90}{Kr}$  +  ${}_{56}^{144}{Ba}$  + x.n. Biết năng lượng liên kết riêng của  ${}_{92}^{235}U$  là 7,60 MeV/nucleon; của  ${}_{36}^{90}{Kr}$  là 8,53 MeV/nucleon và của  ${}_{56}^{144}{Ba}$  là 8,25 MeV/nucleon.","difficultySource":"ai"}}]},{"id":589471,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":0,"options":["1 538 kJ.","1 431 kJ.","162 kJ.","1 482 kJ."],"question":"Một chai rượu ethylic (hỗn hợp của ethylic acohol và nước) có thể tích thực là 750 mℓ và độ rượu là 20. Biểu thức xác định độ rượu ethylic là  $S=\\frac{V_{ethylic acohol}}{V_{rượu ethylic}}.100$ . Ta có bảng số liệu sau:<br>Khối lượng riêng (kg/m3)\tNhiệt độ sôi (C)\tNhiệt dung riêng (J/(kg.K))\tNhiệt hóa hơi riêng (J/kg)<br>Ethylic acohol\t789\t78\t\t0,9.106<br>Nước\t997\t100\t4 200\t2,3.10<sup>6</sup><br>Nhiệt lượng cần cung cấp để hóa hơi hoàn toàn lượng rượu ethylic trong chai kể từ thời điểm nhiệt độ của rượu vừa đạt 78 C xấp xỉ bằng","difficulty":"kho","explanation":"Thể tích ethylic acohol:  $V_{ethylic acohol}=\\frac{S.V_{rượu ethylic}}{100}=\\frac{20.750.{10}^{-6}}{100}=15.{10}^{-5}$  m3.<br>Thể tích nước:  $V_{nước}=V_{rượu ethylic}-V_{ethylic acohol}=750.{10}^{-6}-15.{10}^{-5}=60.{10}^{-5}$  m3.<br>Khối lượng ethylic acohol:  $m_e=D_e.V_{ethylic acohol}=789.15.{10}^{-5}=0,11835$  kg.<br>Khối lượng nước:  $m_n=D_n.V_{nước}=997.60.{10}^{-5}=0,5982$  kg.<br>Kể từ thời điểm nhiệt độ của rượu vừa đạt 78 C, nhiệt độ cung cấp để ethylic acohol hóa hơi hoàn toàn, nước tăng nhiệt độ tới 100 C và nước hóa hơi hoàn toàn, nên ta có:<br>$Q=L_e.m_e+m_n.c_n.\\Delta T+L_n.m_n$<br>$Q=0,9.{10}^6.0,11835+0,5982.4200.\\left(100-78\\right)+2,3.{10}^6.0,5982$<br>$Q\\approx 1 537 649$  J  $\\approx 1 538$  kJ.","difficultySource":"ai"},"ex":[{"exam":293,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":0,"options":["1 538 kJ.","1 431 kJ.","162 kJ.","1 482 kJ."],"question":"Một chai rượu ethylic (hỗn hợp của ethylic acohol và nước) có thể tích thực là 750 mℓ và độ rượu là 20. Biểu thức xác định độ rượu ethylic là  $S=\\frac{V_{ethylic acohol}}{V_{rượu ethylic}}.100$ . Ta có bảng số liệu sau:<br>Khối lượng riêng (kg/m3)\tNhiệt độ sôi (C)\tNhiệt dung riêng (J/(kg.K))\tNhiệt hóa hơi riêng (J/kg)<br>Ethylic acohol\t789\t78\t\t0,9.106<br>Nước\t997\t100\t4 200\t2,3.10<sup>6</sup><br>Nhiệt lượng cần cung cấp để hóa hơi hoàn toàn lượng rượu ethylic trong chai kể từ thời điểm nhiệt độ của rượu vừa đạt 78 C xấp xỉ bằng","difficulty":"kho","explanation":"Thể tích ethylic acohol:  $V_{ethylic acohol}=\\frac{S.V_{rượu ethylic}}{100}=\\frac{20.750.{10}^{-6}}{100}=15.{10}^{-5}$  m3.<br>Thể tích nước:  $V_{nước}=V_{rượu ethylic}-V_{ethylic acohol}=750.{10}^{-6}-15.{10}^{-5}=60.{10}^{-5}$  m3.<br>Khối lượng ethylic acohol:  $m_e=D_e.V_{ethylic acohol}=789.15.{10}^{-5}=0,11835$  kg.<br>Khối lượng nước:  $m_n=D_n.V_{nước}=997.60.{10}^{-5}=0,5982$  kg.<br>Kể từ thời điểm nhiệt độ của rượu vừa đạt 78 C, nhiệt độ cung cấp để ethylic acohol hóa hơi hoàn toàn, nước tăng nhiệt độ tới 100 C và nước hóa hơi hoàn toàn, nên ta có:<br>$Q=L_e.m_e+m_n.c_n.\\Delta T+L_n.m_n$<br>$Q=0,9.{10}^6.0,11835+0,5982.4200.\\left(100-78\\right)+2,3.{10}^6.0,5982$<br>$Q\\approx 1 537 649$  J  $\\approx 1 538$  kJ.","difficultySource":"ai"}}]},{"id":589482,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":3,"options":["3,01.10<sup>23</sup>.","2,8.10<sup>25</sup>.","7,2.10<sup>25</sup>.","4,4.10<sup>25</sup>."],"question":"Biết khối lượng nguyên tử  ${}_{92}^{238}U$  là 238 amu. Số neutron có trong 119 gam  ${}_{92}^{238}U$  xấp xỉ bằng","difficulty":"de","explanation":"Số nguyên tử  ${}_{92}^{238}U$  có trong 119 gam  ${}_{92}^{238}U$  là:<br>$N=\\frac{m}{M}.N_A=\\frac{119}{238}.6,02.{10}^{23}=3,01.{10}^{23}$  nguyên tử.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Trong mỗi nguyên tử  ${}_{92}^{238}U$  có chứa  $238-92=146$  neutron.<br>Vậy số neutron có trong 119 gam  ${}_{92}^{238}U$  là  $3,01.{10}^{23}.146\\approx 4,4.{10}^{25}$ .","difficultySource":"ai"},"ex":[{"exam":293,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":3,"options":["3,01.10<sup>23</sup>.","2,8.10<sup>25</sup>.","7,2.10<sup>25</sup>.","4,4.10<sup>25</sup>."],"question":"Biết khối lượng nguyên tử  ${}_{92}^{238}U$  là 238 amu. Số neutron có trong 119 gam  ${}_{92}^{238}U$  xấp xỉ bằng","difficulty":"de","explanation":"Số nguyên tử  ${}_{92}^{238}U$  có trong 119 gam  ${}_{92}^{238}U$  là:<br>$N=\\frac{m}{M}.N_A=\\frac{119}{238}.6,02.{10}^{23}=3,01.{10}^{23}$  nguyên tử.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Trong mỗi nguyên tử  ${}_{92}^{238}U$  có chứa  $238-92=146$  neutron.<br>Vậy số neutron có trong 119 gam  ${}_{92}^{238}U$  là  $3,01.{10}^{23}.146\\approx 4,4.{10}^{25}$ .","difficultySource":"ai"}}]},{"id":590977,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":2,"options":["1,3.10<sup>−24</sup> kg.","1,8.10<sup>−24</sup> kg.","1,3.10<sup>−26</sup> kg.","1,8.10<sup>−26</sup> kg."],"question":"Bevatron là một máy gia tốc hạt. Người ta dùng máy bevatron để truyền cho hạt proton một động năng 10-9 J (tốc độ hạt rất lớn). Biết khối lượng nghỉ của hạt proton là 1,67.10<sup>−27</sup> kg. Khối lượng hạt proton khi chuyển động trong máy gia tốc xấp xỉ là","difficulty":"trung-binh","explanation":"Ta có:  $\\frac{m}{m_0}=\\frac{mc^2}{m_0c^2}=\\frac{W_đ+m_0c^2}{m_0c^2}=7,68$<br>Thay m0 = 1,67.10<sup>−27</sup> ta tính được m  $\\approx$  1,3.10<sup>−26</sup> kg.","difficultySource":"ai"},"ex":[{"exam":295,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":2,"options":["1,3.10<sup>−24</sup> kg.","1,8.10<sup>−24</sup> kg.","1,3.10<sup>−26</sup> kg.","1,8.10<sup>−26</sup> kg."],"question":"Bevatron là một máy gia tốc hạt. Người ta dùng máy bevatron để truyền cho hạt proton một động năng 10-9 J (tốc độ hạt rất lớn). Biết khối lượng nghỉ của hạt proton là 1,67.10<sup>−27</sup> kg. Khối lượng hạt proton khi chuyển động trong máy gia tốc xấp xỉ là","difficulty":"trung-binh","explanation":"Ta có:  $\\frac{m}{m_0}=\\frac{mc^2}{m_0c^2}=\\frac{W_đ+m_0c^2}{m_0c^2}=7,68$<br>Thay m0 = 1,67.10<sup>−27</sup> ta tính được m  $\\approx$  1,3.10<sup>−26</sup> kg.","difficultySource":"ai"}}]},{"id":590988,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","question":"Nhà máy điện hạt nhân Ninh Thuận dự tính có công suất điện 4000 MW sử dụng nhiên liệu 235U (25%). Mỗi phân hạch tạo ra năng lượng là 200 MeV. Biết hiệu suất nhà máy điện hạt nhân là 35%.","difficulty":"kho","statements":[{"text":"Các phân hạch là phản ứng hạt nhân toả năng lượng.","answer":true},{"text":"Công suất của lò phản ứng xấp xỉ 11429 MW.","answer":true},{"text":"Giả sử lò hoạt động ổn định với hệ số neutron là k = 1. Số neutron mỗi giây để duy trì hoạt động của lò phản ứng vào khoảng 3,57.10<sup>25</sup> hạt.","answer":false},{"text":"Khối lượng nhiên liệu để lò hoạt động liên tục trong 10 năm là 17,8 tấn.","answer":false}],"explanation":"a) đúng<br>Phản ứng phân hạch là phản ứng toả năng lượng.<br>b) đúng<br>Công suất lò phản ứng: P $=\\frac{P_{điện}}{0,35}\\approx 11429MW.$<br>c) sai<br>Số neutron sinh ra mỗi giây là:  $N=\\frac{E}{200MeV}=\\frac{P.t}{200MeV}=\\frac{11429.{10}^6.1}{200.{10}^6.1,6.{10}^{-19}}\\approx 3,57.{10}^{20} hạt$<br>d) sai<br>Khối lượng nhiên liệu lò hoạt động trong 10 năm là  $m=\\frac{N.A}{N_A}:0,25=\\frac{3,57.{10}^{20}.10.365.24.3600.238}{6,02.{10}^{23}.0,25}=178 tấn$","difficultySource":"ai"},"ex":[{"exam":295,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","question":"Nhà máy điện hạt nhân Ninh Thuận dự tính có công suất điện 4000 MW sử dụng nhiên liệu 235U (25%). Mỗi phân hạch tạo ra năng lượng là 200 MeV. Biết hiệu suất nhà máy điện hạt nhân là 35%.","difficulty":"kho","statements":[{"text":"Các phân hạch là phản ứng hạt nhân toả năng lượng.","answer":true},{"text":"Công suất của lò phản ứng xấp xỉ 11429 MW.","answer":true},{"text":"Giả sử lò hoạt động ổn định với hệ số neutron là k = 1. Số neutron mỗi giây để duy trì hoạt động của lò phản ứng vào khoảng 3,57.10<sup>25</sup> hạt.","answer":false},{"text":"Khối lượng nhiên liệu để lò hoạt động liên tục trong 10 năm là 17,8 tấn.","answer":false}],"explanation":"a) đúng<br>Phản ứng phân hạch là phản ứng toả năng lượng.<br>b) đúng<br>Công suất lò phản ứng: P $=\\frac{P_{điện}}{0,35}\\approx 11429MW.$<br>c) sai<br>Số neutron sinh ra mỗi giây là:  $N=\\frac{E}{200MeV}=\\frac{P.t}{200MeV}=\\frac{11429.{10}^6.1}{200.{10}^6.1,6.{10}^{-19}}\\approx 3,57.{10}^{20} hạt$<br>d) sai<br>Khối lượng nhiên liệu lò hoạt động trong 10 năm là  $m=\\frac{N.A}{N_A}:0,25=\\frac{3,57.{10}^{20}.10.365.24.3600.238}{6,02.{10}^{23}.0,25}=178 tấn$","difficultySource":"ai"}}]},{"id":592095,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":0,"options":["269 g","192 g","226 g","253 g"],"question":"Trong một nhiệt lượng kế bằng nhôm có khối lượng mnl = 300 g có một cục nước đá nặng mnđ(g). Nhiệt độ của nước đá và nhiệt lượng kế là t1 = −50C, Sau đó người ta cho mhn (g) hơi nước ở nhiệt độ t2 = 1000C và nhiệt lượng kế và khi đã cân bằng nhiệt thì nhiệt độ của nhiệt lượng kế là t3 = 250C. Lúc đó trong nhiệt lượng kế có 500 g nước. Cho biết nhiệt hóa hơi riêng của nước là 2,26.10<sup>3</sup> J/g, nhiệt nóng chảy của nước đá là 334 J/g, nhiệt dung riêng của nhôm, nước, nước đá lần lượt là cnl = 0,88 J/g.K, cnđ = 2,09 J/g.K và cn = 4,19 J/g.K. Giá trị của (mnđ − 2mhn) gần với giá trị nào nhất?","difficulty":"kho","explanation":"$\\left[0,3.0,88.30+m_d.2,09.5\\right]+\\left[m_d.334\\right]+\\left[\\left(m_d.4,19+0,3.0,88\\right).25\\right]=m_{hoi}.2,26.10^3+m_{hoi}.4,19.75$<br>$\\Rightarrow 7920+449,2m_d=m_{hoi}.2574,25\\left(1\\right)$<br>$m_d+m_{hoi}=500\\left(2\\right)$<br>$\\overset{\\left(1\\right);\\left(2\\right)}\\rightarrow\\left\\{\\begin{aligned}m_d=423,1 <br>m_{hoi}=77\\end{aligned}\\right.\\Rightarrow m_{da}−2m_{hoi}=269,1$","difficultySource":"ai"},"ex":[{"exam":296,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":0,"options":["269 g","192 g","226 g","253 g"],"question":"Trong một nhiệt lượng kế bằng nhôm có khối lượng mnl = 300 g có một cục nước đá nặng mnđ(g). Nhiệt độ của nước đá và nhiệt lượng kế là t1 = −50C, Sau đó người ta cho mhn (g) hơi nước ở nhiệt độ t2 = 1000C và nhiệt lượng kế và khi đã cân bằng nhiệt thì nhiệt độ của nhiệt lượng kế là t3 = 250C. Lúc đó trong nhiệt lượng kế có 500 g nước. Cho biết nhiệt hóa hơi riêng của nước là 2,26.10<sup>3</sup> J/g, nhiệt nóng chảy của nước đá là 334 J/g, nhiệt dung riêng của nhôm, nước, nước đá lần lượt là cnl = 0,88 J/g.K, cnđ = 2,09 J/g.K và cn = 4,19 J/g.K. Giá trị của (mnđ − 2mhn) gần với giá trị nào nhất?","difficulty":"kho","explanation":"$\\left[0,3.0,88.30+m_d.2,09.5\\right]+\\left[m_d.334\\right]+\\left[\\left(m_d.4,19+0,3.0,88\\right).25\\right]=m_{hoi}.2,26.10^3+m_{hoi}.4,19.75$<br>$\\Rightarrow 7920+449,2m_d=m_{hoi}.2574,25\\left(1\\right)$<br>$m_d+m_{hoi}=500\\left(2\\right)$<br>$\\overset{\\left(1\\right);\\left(2\\right)}\\rightarrow\\left\\{\\begin{aligned}m_d=423,1 <br>m_{hoi}=77\\end{aligned}\\right.\\Rightarrow m_{da}−2m_{hoi}=269,1$","difficultySource":"ai"}}]},{"id":592096,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":3,"options":["0,016 T","0,16 T","0,8 T","0,08 T"],"question":"Một đoạn dây dẫn dài 5 cm đặt trong từ trường đều vuông góc với véctơ cảm ứng từ. Dòng điện có cường độ 0,75 A qua dây dẫn thì lực từ tác dụng lên đoạn dây có độ lớn là 3.10<sup>−3</sup> N. Cảm ứng từ của từ trường có độ lớn bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đoạn dây đặt trong từ trường đều và vuông góc với véctơ cảm ứng từ, nên góc giữa dòng điện và cảm ứng từ là $\\alpha = 90^\\circ$, $\\sin\\alpha = 1$.</p><p class=\"text-base leading-relaxed my-2\">Lực từ tác dụng lên đoạn dây dẫn (định luật Ampère): $F = B\\,I\\,\\ell\\,\\sin\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra cảm ứng từ: $B = \\dfrac{F}{I\\,\\ell}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $\\ell = 5\\text{ cm} = 0{,}05\\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $B = \\dfrac{3\\cdot10^{-3}}{0{,}75\\cdot0{,}05} = \\dfrac{3\\cdot10^{-3}}{0{,}0375} = 0{,}08\\text{ T}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy cảm ứng từ có độ lớn $0{,}08\\text{ T}$, đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":296,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":3,"options":["0,016 T","0,16 T","0,8 T","0,08 T"],"question":"Một đoạn dây dẫn dài 5 cm đặt trong từ trường đều vuông góc với véctơ cảm ứng từ. Dòng điện có cường độ 0,75 A qua dây dẫn thì lực từ tác dụng lên đoạn dây có độ lớn là 3.10<sup>−3</sup> N. Cảm ứng từ của từ trường có độ lớn bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đoạn dây đặt trong từ trường đều và vuông góc với véctơ cảm ứng từ, nên góc giữa dòng điện và cảm ứng từ là $\\alpha = 90^\\circ$, $\\sin\\alpha = 1$.</p><p class=\"text-base leading-relaxed my-2\">Lực từ tác dụng lên đoạn dây dẫn (định luật Ampère): $F = B\\,I\\,\\ell\\,\\sin\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra cảm ứng từ: $B = \\dfrac{F}{I\\,\\ell}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $\\ell = 5\\text{ cm} = 0{,}05\\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $B = \\dfrac{3\\cdot10^{-3}}{0{,}75\\cdot0{,}05} = \\dfrac{3\\cdot10^{-3}}{0{,}0375} = 0{,}08\\text{ T}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy cảm ứng từ có độ lớn $0{,}08\\text{ T}$, đáp án D.</p>","difficultySource":"ai"}}]},{"id":592116,"nq":{"form":"bai_tap","type":"short_answer","topic":"Từ thông. Hiện tượng cảm ứng điện từ","answer":"5,89","question":"Cuộn dây kim loại gồm 1000 vòng được cuốn sát nhau (không chồng lên nhau) tạo thành ống dây hình<br>trụ, đường kính cuộn dây d = 10 cm, có trục song song với B của từ trường đều. Tốc độ biến thiên  $\\frac{\\Delta B}{\\Delta t}=0,2$  (T/s). Lấy e = 1,6.10<sup>−19</sup>C. Nếu nối hai đầu cuộn dây vào tụ điện có điện dung C = 6 μC thì trong khoảng thời gian từ thông biến thiên đã có X.10<sup>13</sup> electron dịch chuyển đến bản tụ. Giá trị X bằng bao nhiêu? (kết quả làm tròn đến hàng phần trăm).","difficulty":"trung-binh","explanation":"$\\left|e_{cu}\\right|=NS\\frac{\\Delta B}{\\Delta t}=1000.\\left(\\pi .0,05^2\\right).0,2=\\frac{\\pi }{2}\\left(V\\right)=U$<br>$Q=CU=6.10^{−6}.\\frac{\\pi }{2}=3\\pi .10^{−6}\\left(C\\right)$<br>$N=\\frac{Q}{1,6.10^{−19}}=5,89.10^{13}$","difficultySource":"ai"},"ex":[{"exam":296,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Từ thông. Hiện tượng cảm ứng điện từ","answer":"5,89","question":"Cuộn dây kim loại gồm 1000 vòng được cuốn sát nhau (không chồng lên nhau) tạo thành ống dây hình<br>trụ, đường kính cuộn dây d = 10 cm, có trục song song với B của từ trường đều. Tốc độ biến thiên  $\\frac{\\Delta B}{\\Delta t}=0,2$  (T/s). Lấy e = 1,6.10<sup>−19</sup>C. Nếu nối hai đầu cuộn dây vào tụ điện có điện dung C = 6 μC thì trong khoảng thời gian từ thông biến thiên đã có X.10<sup>13</sup> electron dịch chuyển đến bản tụ. Giá trị X bằng bao nhiêu? (kết quả làm tròn đến hàng phần trăm).","difficulty":"trung-binh","explanation":"$\\left|e_{cu}\\right|=NS\\frac{\\Delta B}{\\Delta t}=1000.\\left(\\pi .0,05^2\\right).0,2=\\frac{\\pi }{2}\\left(V\\right)=U$<br>$Q=CU=6.10^{−6}.\\frac{\\pi }{2}=3\\pi .10^{−6}\\left(C\\right)$<br>$N=\\frac{Q}{1,6.10^{−19}}=5,89.10^{13}$","difficultySource":"ai"}}]},{"id":593653,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":1,"options":["1,5 T.","0,6 T.","6,7.10<sup>−3</sup>T.","1,8.103T."],"question":"Một đoạn dây dẫn thẳng dài 0,5 m mang dòng điện 10 A được đặt trong một từ trường đều, vuông góc với các đường sức từ. Biết lực từ tác dụng lên dây dẫn là 3 N. Độ lớn cảm ứng từ bằng bao nhiêu?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ tác dụng lên đoạn dây dẫn thẳng đặt trong từ trường đều có độ lớn: $F = B I \\ell \\sin\\alpha$, trong đó $\\alpha$ là góc giữa dây dẫn và đường sức từ.</p><p class=\"text-base leading-relaxed my-2\">Dây dẫn vuông góc với các đường sức từ nên $\\alpha = 90^\\circ$, $\\sin\\alpha = 1$. Do đó $F = B I \\ell$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow B = \\dfrac{F}{I\\ell}$</p><p class=\"text-base leading-relaxed my-2\">Thay số với $F = 3$ N, $I = 10$ A, $\\ell = 0{,}5$ m:</p><p class=\"text-base leading-relaxed my-2\">$B = \\dfrac{3}{10 \\cdot 0{,}5} = 0{,}6$ T.</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn cảm ứng từ là $0{,}6$ T, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":298,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":1,"options":["1,5 T.","0,6 T.","6,7.10<sup>−3</sup>T.","1,8.103T."],"question":"Một đoạn dây dẫn thẳng dài 0,5 m mang dòng điện 10 A được đặt trong một từ trường đều, vuông góc với các đường sức từ. Biết lực từ tác dụng lên dây dẫn là 3 N. Độ lớn cảm ứng từ bằng bao nhiêu?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ tác dụng lên đoạn dây dẫn thẳng đặt trong từ trường đều có độ lớn: $F = B I \\ell \\sin\\alpha$, trong đó $\\alpha$ là góc giữa dây dẫn và đường sức từ.</p><p class=\"text-base leading-relaxed my-2\">Dây dẫn vuông góc với các đường sức từ nên $\\alpha = 90^\\circ$, $\\sin\\alpha = 1$. Do đó $F = B I \\ell$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow B = \\dfrac{F}{I\\ell}$</p><p class=\"text-base leading-relaxed my-2\">Thay số với $F = 3$ N, $I = 10$ A, $\\ell = 0{,}5$ m:</p><p class=\"text-base leading-relaxed my-2\">$B = \\dfrac{3}{10 \\cdot 0{,}5} = 0{,}6$ T.</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn cảm ứng từ là $0{,}6$ T, đáp án B.</p>","difficultySource":"ai"}}]},{"id":594368,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình trạng thái khí lí tưởng","answer":0,"options":["292 °C.","565 °C.","523 K.","88 °C."],"question":"Khối khí trong xilanh của một động cơ nhiệt (xem là khí lí tưởng) có áp suất là 0,8.105 Pa và nhiệt độ là 50 °C. Sau khi bị nén, thể tích của khối khí giảm 5 lần, áp suất tăng lên đến 7.10<sup>5</sup> Pa. Nhiệt độ của khối khí ở cuối quá trình nén xấp xỉ bằng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045604177-hinh-6.webp\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Nhiệt độ của khối khí ở cuối quá trình nén là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\frac{p_1.V_1}{T_1}=\\frac{p_2.V_2}{T_2}$  (phương trình trạng thái khí lí tưởng)<br>$T_2=\\frac{T_1.p_2.V_2}{p_1.V_1}=\\frac{\\left(50+273\\right).7.{10}^5.\\frac{V_1}{5}}{0,8.{10}^5.V_1}=565,25 K\\approx 292℃$ .","difficultySource":"ai"},"ex":[{"exam":299,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình trạng thái khí lí tưởng","answer":0,"options":["292 °C.","565 °C.","523 K.","88 °C."],"question":"Khối khí trong xilanh của một động cơ nhiệt (xem là khí lí tưởng) có áp suất là 0,8.105 Pa và nhiệt độ là 50 °C. Sau khi bị nén, thể tích của khối khí giảm 5 lần, áp suất tăng lên đến 7.10<sup>5</sup> Pa. Nhiệt độ của khối khí ở cuối quá trình nén xấp xỉ bằng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045604177-hinh-6.webp\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Nhiệt độ của khối khí ở cuối quá trình nén là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\frac{p_1.V_1}{T_1}=\\frac{p_2.V_2}{T_2}$  (phương trình trạng thái khí lí tưởng)<br>$T_2=\\frac{T_1.p_2.V_2}{p_1.V_1}=\\frac{\\left(50+273\\right).7.{10}^5.\\frac{V_1}{5}}{0,8.{10}^5.V_1}=565,25 K\\approx 292℃$ .","difficultySource":"ai"}}]},{"id":594373,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","answer":3,"options":["600 J.","0,1.104 J.","10 J.","6.10<sup>4</sup> J."],"question":"Một đoạn mạch điện có điện trở 5 , cường độ dòng điện xoay chiều chạy trong mạch có biểu thức  $i=\\sqrt2cos(20\\pi t+\\frac{\\pi }{6}$ ) (mA). Nhiệt lượng tỏa ra trên đoạn mạch trong khoảng thời gian 2 phút là","difficulty":"trung-binh","explanation":"Nhiệt lượng tỏa ra trên đoạn mạch trong khoảng thời gian 2 phút là:<br>$Q=I^2Rt=\\frac{{I_0}^2}{2}Rt=\\frac{{\\left(\\sqrt2.{10}^{-3}\\right)}^2}{2}.5.2.60=6.{10}^{-4}$  J.","difficultySource":"ai"},"ex":[{"exam":299,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","answer":3,"options":["600 J.","0,1.104 J.","10 J.","6.10<sup>4</sup> J."],"question":"Một đoạn mạch điện có điện trở 5 , cường độ dòng điện xoay chiều chạy trong mạch có biểu thức  $i=\\sqrt2cos(20\\pi t+\\frac{\\pi }{6}$ ) (mA). Nhiệt lượng tỏa ra trên đoạn mạch trong khoảng thời gian 2 phút là","difficulty":"trung-binh","explanation":"Nhiệt lượng tỏa ra trên đoạn mạch trong khoảng thời gian 2 phút là:<br>$Q=I^2Rt=\\frac{{I_0}^2}{2}Rt=\\frac{{\\left(\\sqrt2.{10}^{-3}\\right)}^2}{2}.5.2.60=6.{10}^{-4}$  J.","difficultySource":"ai"}}]},{"id":594374,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":1,"options":["2,63.10<sup>24</sup> MeV.","2,63.10<sup>27</sup> MeV.","2,63.1024 J.","2,63.1027 J."],"question":"Bom nhiệt hạch dùng phản ứng:  ${}_1^2D$  +  ${}_1^3T$    ${}_2^4{He}$  +  ${}_0^1n$ . Biết khối lượng của các nguyên tử  ${}_1^2D$ ,  ${}_1^3T$ ,  ${}_2^4{He}$  và  ${}_0^1n$  lần lượt là 2,0141 u; 3,0160 u; 4,0026 u và 1,0087 u. Lấy 1 uc2 = 931,5 MeV. Năng lượng toả ra của quá trình phản ứng hạt nhân được xác định bởi biểu thức E = ( $m_{tt}$  –  $m_{sp}$ ) $c^2$  với  $m_{tt}$  và  $m_{sp}$  lần lượt là tổng khối lượng của các hạt trước và sau phản ứng. Nếu có 1 kg helium được tạo thành do vụ nổ của bom nhiệt hạch thì năng lượng tỏa ra xấp xỉ bằng","difficulty":"kho","explanation":"Năng lượng tỏa ra khi phản ứng tạo ra 1 nguyên tử  ${}_2^4{He}$  là<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Delta E=\\left(m_{tt}-m_{sp}\\right)c^2=\\left(2,0141+3,0160-4,0026-1,0087\\right)uc^2$<br>$\\Delta E=0,0188.931,5 MeV=17,5122 MeV$ .<br>Năng lượng tỏa ra khi phản ứng tạo ra 1 kg helium là<br>$E=N.\\Delta E=\\frac{m}{M}.N_A.\\Delta E=\\frac{1.{10}^3}{4,0026}.6,02.{10}^{23}.17,5122 MeV\\approx 2,63.{10}^{27} MeV$ .","difficultySource":"ai"},"ex":[{"exam":299,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":1,"options":["2,63.10<sup>24</sup> MeV.","2,63.10<sup>27</sup> MeV.","2,63.1024 J.","2,63.1027 J."],"question":"Bom nhiệt hạch dùng phản ứng:  ${}_1^2D$  +  ${}_1^3T$    ${}_2^4{He}$  +  ${}_0^1n$ . Biết khối lượng của các nguyên tử  ${}_1^2D$ ,  ${}_1^3T$ ,  ${}_2^4{He}$  và  ${}_0^1n$  lần lượt là 2,0141 u; 3,0160 u; 4,0026 u và 1,0087 u. Lấy 1 uc2 = 931,5 MeV. Năng lượng toả ra của quá trình phản ứng hạt nhân được xác định bởi biểu thức E = ( $m_{tt}$  –  $m_{sp}$ ) $c^2$  với  $m_{tt}$  và  $m_{sp}$  lần lượt là tổng khối lượng của các hạt trước và sau phản ứng. Nếu có 1 kg helium được tạo thành do vụ nổ của bom nhiệt hạch thì năng lượng tỏa ra xấp xỉ bằng","difficulty":"kho","explanation":"Năng lượng tỏa ra khi phản ứng tạo ra 1 nguyên tử  ${}_2^4{He}$  là<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Delta E=\\left(m_{tt}-m_{sp}\\right)c^2=\\left(2,0141+3,0160-4,0026-1,0087\\right)uc^2$<br>$\\Delta E=0,0188.931,5 MeV=17,5122 MeV$ .<br>Năng lượng tỏa ra khi phản ứng tạo ra 1 kg helium là<br>$E=N.\\Delta E=\\frac{m}{M}.N_A.\\Delta E=\\frac{1.{10}^3}{4,0026}.6,02.{10}^{23}.17,5122 MeV\\approx 2,63.{10}^{27} MeV$ .","difficultySource":"ai"}}]},{"id":594375,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":3,"options":["1,39.10<sup>12</sup> hạt.","1,43.10<sup>19</sup> hạt.","5,96.10<sup>17</sup> hạt.","5,15.10<sup>22</sup> hạt."],"question":"Trong việc điều trị bệnh ung thư bằng phương pháp xạ trị hiện nay, người ta thường sử dụng máy gia tốc hạt trong việc tạo ra các hạt mang năng lượng cao để bắn phá các tế bào ung thư. Tuy nhiên, trước khi máy gia tốc hạt ra đời thì việc điều trị ung thư trong các bệnh viện trước đây lại sử dụng một nguồn phát ra tia gamma như đồng vị phóng xạ  ${}_{27}^{60}{Co}$  (có chu kì bán rã là 5,27 năm, mỗi năm xem như có 365 ngày). Các tia gamma phát ra từ quá trình phóng xạ của  ${}_{27}^{60}{Co}$  được sử dụng để tiêu diệt tế bào ung thư. Số lượng hạt nhân  ${}_{27}^{60}{Co}$  chứa trong một nguồn phóng xạ có độ phóng xạ là 5 800 Ci tại bệnh viện xấp xỉ bằng","difficulty":"kho","explanation":"Số lượng hạt nhân  ${}_{27}^{60}{Co}$  chứa trong nguồn phóng xạ tại thời điểm đang xét là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H_t=.N_t=\\frac{\\ln\\left(2\\right)}{T}.N_t$    $N_t=\\frac{T}{\\ln\\left(2\\right)}.H_t=\\frac{5,27.365.24.3600}{ln2}.5800.3,7.{10}^{10}\\approx 5,15.{10}^{22}$  hạt.","difficultySource":"ai"},"ex":[{"exam":299,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":3,"options":["1,39.10<sup>12</sup> hạt.","1,43.10<sup>19</sup> hạt.","5,96.10<sup>17</sup> hạt.","5,15.10<sup>22</sup> hạt."],"question":"Trong việc điều trị bệnh ung thư bằng phương pháp xạ trị hiện nay, người ta thường sử dụng máy gia tốc hạt trong việc tạo ra các hạt mang năng lượng cao để bắn phá các tế bào ung thư. Tuy nhiên, trước khi máy gia tốc hạt ra đời thì việc điều trị ung thư trong các bệnh viện trước đây lại sử dụng một nguồn phát ra tia gamma như đồng vị phóng xạ  ${}_{27}^{60}{Co}$  (có chu kì bán rã là 5,27 năm, mỗi năm xem như có 365 ngày). Các tia gamma phát ra từ quá trình phóng xạ của  ${}_{27}^{60}{Co}$  được sử dụng để tiêu diệt tế bào ung thư. Số lượng hạt nhân  ${}_{27}^{60}{Co}$  chứa trong một nguồn phóng xạ có độ phóng xạ là 5 800 Ci tại bệnh viện xấp xỉ bằng","difficulty":"kho","explanation":"Số lượng hạt nhân  ${}_{27}^{60}{Co}$  chứa trong nguồn phóng xạ tại thời điểm đang xét là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H_t=.N_t=\\frac{\\ln\\left(2\\right)}{T}.N_t$    $N_t=\\frac{T}{\\ln\\left(2\\right)}.H_t=\\frac{5,27.365.24.3600}{ln2}.5800.3,7.{10}^{10}\\approx 5,15.{10}^{22}$  hạt.","difficultySource":"ai"}}]},{"id":594381,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"1,45","question":"Một bình kín có thể tích thực là 0,2 m3 chứa một lượng khí lí tưởng ở nhiệt độ 27 °C và áp suất 3.10<sup>5</sup> Pa. Số phân tử khí chứa trong bình là x.10<sup>25</sup> phân tử. Giá trị của x là bao nhiêu (làm tròn kết quả đến hàng phần trăm)?","difficulty":"de","explanation":"Số mol của khối khí chứa trong bình là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$p.V=n.R.T$    $n=\\frac{p.V}{R.T}$  (mol)<br>Số phân tử khí chứa trong bình là:<br>$N=n.N_A=\\frac{p.V}{R.T}.N_A=\\frac{3.{10}^5.0,2}{8,31.\\left(27+273\\right)}.6,02.{10}^{23}\\approx 1,45.{10}^{25}$  phân tử.<br>Vậy x là 1,45.","difficultySource":"ai"},"ex":[{"exam":299,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"1,45","question":"Một bình kín có thể tích thực là 0,2 m3 chứa một lượng khí lí tưởng ở nhiệt độ 27 °C và áp suất 3.10<sup>5</sup> Pa. Số phân tử khí chứa trong bình là x.10<sup>25</sup> phân tử. Giá trị của x là bao nhiêu (làm tròn kết quả đến hàng phần trăm)?","difficulty":"de","explanation":"Số mol của khối khí chứa trong bình là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$p.V=n.R.T$    $n=\\frac{p.V}{R.T}$  (mol)<br>Số phân tử khí chứa trong bình là:<br>$N=n.N_A=\\frac{p.V}{R.T}.N_A=\\frac{3.{10}^5.0,2}{8,31.\\left(27+273\\right)}.6,02.{10}^{23}\\approx 1,45.{10}^{25}$  phân tử.<br>Vậy x là 1,45.","difficultySource":"ai"}}]},{"id":594385,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"12","question":"Tại một thời điểm, mẫu chất phóng xạ A có chu kì bán rã là 2 ngày và có 6,4.10<sup>11</sup> hạt nhân nguyên tử trong mẫu. Mẫu chất phóng xạ B có chu kì bán rã là 3 ngày và có 16.1010 hạt nhân nguyên tử trong mẫu. Sau bao nhiêu ngày nữa thì số hạt nhân nguyên tử chưa phóng xạ của hai mẫu đó bằng nhau?","difficulty":"kho","explanation":"Sau khoảng thời gian t (ngày) nữa, hai mẫu chất phóng xạ có số hạt nhân còn lại như nhau.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Ta có:<br>$N_{t_A}=N_{t_B}$    $N_{0A}.2^{-\\frac{t}{T_A}}=N_{0B}.2^{-\\frac{t}{T_B}}$    $\\frac{N_{0B}}{N_{0A}}=\\frac{2^{-\\frac{t}{T_A}}}{2^{-\\frac{t}{T_B}}}=2^{-\\frac{t}{T_A}+\\frac{t}{T_B}}$<br>$t=\\frac{{log}_2\\left(\\frac{N_{0B}}{N_{0A}}\\right)}{-\\frac{1}{T_A}+\\frac{1}{T_B}}=\\frac{{log}_2\\left(\\frac{16.{10}^{10}}{6,4.{10}^{11}}\\right)}{-\\frac{1}{2}+\\frac{1}{3}}=12$  ngày.<br>Vậy, sau 12 ngày nữa thì hai mẫu chất phóng xạ có số hạt nhân còn lại bằng nhau.","difficultySource":"ai"},"ex":[{"exam":299,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"12","question":"Tại một thời điểm, mẫu chất phóng xạ A có chu kì bán rã là 2 ngày và có 6,4.10<sup>11</sup> hạt nhân nguyên tử trong mẫu. Mẫu chất phóng xạ B có chu kì bán rã là 3 ngày và có 16.1010 hạt nhân nguyên tử trong mẫu. Sau bao nhiêu ngày nữa thì số hạt nhân nguyên tử chưa phóng xạ của hai mẫu đó bằng nhau?","difficulty":"kho","explanation":"Sau khoảng thời gian t (ngày) nữa, hai mẫu chất phóng xạ có số hạt nhân còn lại như nhau.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Ta có:<br>$N_{t_A}=N_{t_B}$    $N_{0A}.2^{-\\frac{t}{T_A}}=N_{0B}.2^{-\\frac{t}{T_B}}$    $\\frac{N_{0B}}{N_{0A}}=\\frac{2^{-\\frac{t}{T_A}}}{2^{-\\frac{t}{T_B}}}=2^{-\\frac{t}{T_A}+\\frac{t}{T_B}}$<br>$t=\\frac{{log}_2\\left(\\frac{N_{0B}}{N_{0A}}\\right)}{-\\frac{1}{T_A}+\\frac{1}{T_B}}=\\frac{{log}_2\\left(\\frac{16.{10}^{10}}{6,4.{10}^{11}}\\right)}{-\\frac{1}{2}+\\frac{1}{3}}=12$  ngày.<br>Vậy, sau 12 ngày nữa thì hai mẫu chất phóng xạ có số hạt nhân còn lại bằng nhau.","difficultySource":"ai"}}]},{"id":595378,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Để đúc các vật bằng thép, người ta thường phải nấu chảy thép trong lò sử dụng nhiên liệu đốt là than đá với hiệu suất 60%. Trong một lần đúc, người ta đưa thép có khối lượng m (kg) ở nhiệt độ 27 oC vào trong lò. Để nấu chảy hoàn toàn lượng thép trên, người ta đã đốt cháy hết 200 kg than đá. Biết năng suất tỏa nhiệt của than đá là 29.106 J/kg; nhiệt độ nóng chảy, nhiệt nóng chảy riêng và nhiệt dung riêng ở thể rắn của thép lần lượt là 1 400 C, 83,7.10<sup>3</sup> J/kg và 460 J/(kg.K).","difficulty":"kho","statements":[{"text":"Nhiệt lượng tỏa ra khi đốt cháy hoàn toàn 200 kg than đá là 5,8.10<sup>9</sup> J.","answer":true},{"text":"Nhiệt lượng do than đá đã cung cấp cho khối thép để nấu chảy hoàn toàn m (kg) thép là 2,32.10<sup>9</sup> J.","answer":false},{"text":"Nhiệt lượng cần cung cấp để nấu chảy hoàn toàn m (kg) thép là 715280m (J).","answer":true},{"text":"Khối lượng của khối thép đã cho là  $m\\approx 4865$  kg.","answer":true}],"explanation":"a) đúng<br>Nhiệt lượng tỏa ra khi đốt cháy hoàn toàn 200 kg than đá là:<br>$Q_t=q.m=29.{10}^6.200=5,8.{10}^9$  J.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Nhiệt lượng do than đá đã cung cấp cho khối thép để nấu chảy hoàn toàn m (kg) thép là:<br>$Q_c=60%.Q_t=60%.5,8.{10}^9=3,48.{10}^9$  J.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Nhiệt lượng cần cung cấp để nấu chảy hoàn toàn m (kg) thép là:<br>$Q_n=m.c.\\Delta T+.m=m.460.\\left(1400-27\\right)+83,7.{10}^3.m=715280m$  (J).<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Khối lượng của khối thép đã cho là:<br>$Q_n=Q_c$    $715280m=3,48.{10}^9$    $m\\approx 4865$  kg.","difficultySource":"ai"},"ex":[{"exam":300,"idx":16,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Để đúc các vật bằng thép, người ta thường phải nấu chảy thép trong lò sử dụng nhiên liệu đốt là than đá với hiệu suất 60%. Trong một lần đúc, người ta đưa thép có khối lượng m (kg) ở nhiệt độ 27 oC vào trong lò. Để nấu chảy hoàn toàn lượng thép trên, người ta đã đốt cháy hết 200 kg than đá. Biết năng suất tỏa nhiệt của than đá là 29.106 J/kg; nhiệt độ nóng chảy, nhiệt nóng chảy riêng và nhiệt dung riêng ở thể rắn của thép lần lượt là 1 400 C, 83,7.10<sup>3</sup> J/kg và 460 J/(kg.K).","difficulty":"kho","statements":[{"text":"Nhiệt lượng tỏa ra khi đốt cháy hoàn toàn 200 kg than đá là 5,8.10<sup>9</sup> J.","answer":true},{"text":"Nhiệt lượng do than đá đã cung cấp cho khối thép để nấu chảy hoàn toàn m (kg) thép là 2,32.10<sup>9</sup> J.","answer":false},{"text":"Nhiệt lượng cần cung cấp để nấu chảy hoàn toàn m (kg) thép là 715280m (J).","answer":true},{"text":"Khối lượng của khối thép đã cho là  $m\\approx 4865$  kg.","answer":true}],"explanation":"a) đúng<br>Nhiệt lượng tỏa ra khi đốt cháy hoàn toàn 200 kg than đá là:<br>$Q_t=q.m=29.{10}^6.200=5,8.{10}^9$  J.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Nhiệt lượng do than đá đã cung cấp cho khối thép để nấu chảy hoàn toàn m (kg) thép là:<br>$Q_c=60%.Q_t=60%.5,8.{10}^9=3,48.{10}^9$  J.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Nhiệt lượng cần cung cấp để nấu chảy hoàn toàn m (kg) thép là:<br>$Q_n=m.c.\\Delta T+.m=m.460.\\left(1400-27\\right)+83,7.{10}^3.m=715280m$  (J).<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Khối lượng của khối thép đã cho là:<br>$Q_n=Q_c$    $715280m=3,48.{10}^9$    $m\\approx 4865$  kg.","difficultySource":"ai"}}]},{"id":595379,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Hình bên là ngôi nhà giả chiến do Quân đội nhân dân Việt Nam sản xuất. Các cột trụ và thanh đỡ của ngôi nhà được làm bằng các ống cao su rỗng nối thông với nhau tạo thành. Để dựng nhà thì ta cần bơm khí vào để làm căng cứng các ống cao su. Tổng thể tích của các ống cao su là 1,4 m3. Người ta dùng máy bơm có công suất bơm là 1 lít/s để bơm không khí vào. Xem nhiệt độ của khối khí bơm vào thay đổi không đáng kể; nhiệt độ khối khí trong các ống luôn bằng nhiệt độ ngoài trời và bỏ qua sự dãn nở vì nhiệt của các ống cao su. Biết không khí được bơm vào có áp suất 105 Pa ở nhiệt độ 27 C và ban đầu trong các ống chưa có khí. Để ngôi nhà được vững chắc thì áp suất khối khí trong các ống cao su phải là 6.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045616194-hinh-13.webp\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Lượng khí được bơm vào trong mỗi giây có số mol xấp xỉ bằng 0,04 mol.","answer":true},{"text":"Lượng khí đã bơm vào cho đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 8,4 m3.","answer":true},{"text":"Thời gian bơm khí kể từ thời điểm bắt đầu bơm đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 140 phút.","answer":true},{"text":"Khi nhiệt độ ngoài trời tăng đến 37 C thì áp suất khối khí trong các ống cao su là 6,2.10<sup>5</sup> Pa.","answer":true}],"explanation":"a) đúng<br>Lượng khí bơm vào trong mỗi giây là 1 lít. Khi đó, số mol của lượng khí bơm vào trong mỗi giây là:<br>$pV=nRT$  (phương trình Clapeyron)   $n=\\frac{pV}{RT}=\\frac{{10}^5.1.{10}^{-3}}{8,31.\\left(27+273\\right)}=\\frac{100}{2493}\\approx 0,04$  mol.<br>b) đúng<br>Do xem nhiệt độ của khối khí bơm vào thay đổi không đáng kể và nhiệt độ khối khí trong các ống luôn bằng nhiệt độ ngoài trời nên, ta có:<br>$p_1.V_1=p_2.V_2$    ${10}^5.V_1=6.{10}^5.1,4$<br>$V_1=8,4$  m3.<br>Vậy, lượng khí đã bơm vào cho đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 8,4 m3.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Thời gian bơm khí kể từ thời điểm bắt đầu bơm đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là:<br>$\\frac{8,4.{10}^3}{1}=8 400 s=140$  phút.<br>d) đúng<br>Khi nhiệt độ ngoài trời tăng đến 37 C thì nhiệt độ khối khí trong các ống cao su cũng 37 C.<br>Do bỏ qua sự dãn nở vì nhiệt của các ống cao su nên thể tích các ống cao su được bảo toàn. Khi đó, ta có:<br>$\\frac{p_2}{T_2}=\\frac{p_3}{T_3}$    $\\frac{6.{10}^5}{27+273}=\\frac{p_3}{37+273}$    $p_3=6,2.{10}^5$  Pa.<br>Vậy, khi nhiệt độ ngoài trời tăng đến 37 C thì áp suất khối khí trong các ống cao su là 6,2.10<sup>5</sup> Pa.","difficultySource":"ai"},"ex":[{"exam":300,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Hình bên là ngôi nhà giả chiến do Quân đội nhân dân Việt Nam sản xuất. Các cột trụ và thanh đỡ của ngôi nhà được làm bằng các ống cao su rỗng nối thông với nhau tạo thành. Để dựng nhà thì ta cần bơm khí vào để làm căng cứng các ống cao su. Tổng thể tích của các ống cao su là 1,4 m3. Người ta dùng máy bơm có công suất bơm là 1 lít/s để bơm không khí vào. Xem nhiệt độ của khối khí bơm vào thay đổi không đáng kể; nhiệt độ khối khí trong các ống luôn bằng nhiệt độ ngoài trời và bỏ qua sự dãn nở vì nhiệt của các ống cao su. Biết không khí được bơm vào có áp suất 105 Pa ở nhiệt độ 27 C và ban đầu trong các ống chưa có khí. Để ngôi nhà được vững chắc thì áp suất khối khí trong các ống cao su phải là 6.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045616194-hinh-13.webp\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Lượng khí được bơm vào trong mỗi giây có số mol xấp xỉ bằng 0,04 mol.","answer":true},{"text":"Lượng khí đã bơm vào cho đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 8,4 m3.","answer":true},{"text":"Thời gian bơm khí kể từ thời điểm bắt đầu bơm đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 140 phút.","answer":true},{"text":"Khi nhiệt độ ngoài trời tăng đến 37 C thì áp suất khối khí trong các ống cao su là 6,2.10<sup>5</sup> Pa.","answer":true}],"explanation":"a) đúng<br>Lượng khí bơm vào trong mỗi giây là 1 lít. Khi đó, số mol của lượng khí bơm vào trong mỗi giây là:<br>$pV=nRT$  (phương trình Clapeyron)   $n=\\frac{pV}{RT}=\\frac{{10}^5.1.{10}^{-3}}{8,31.\\left(27+273\\right)}=\\frac{100}{2493}\\approx 0,04$  mol.<br>b) đúng<br>Do xem nhiệt độ của khối khí bơm vào thay đổi không đáng kể và nhiệt độ khối khí trong các ống luôn bằng nhiệt độ ngoài trời nên, ta có:<br>$p_1.V_1=p_2.V_2$    ${10}^5.V_1=6.{10}^5.1,4$<br>$V_1=8,4$  m3.<br>Vậy, lượng khí đã bơm vào cho đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 8,4 m3.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Thời gian bơm khí kể từ thời điểm bắt đầu bơm đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là:<br>$\\frac{8,4.{10}^3}{1}=8 400 s=140$  phút.<br>d) đúng<br>Khi nhiệt độ ngoài trời tăng đến 37 C thì nhiệt độ khối khí trong các ống cao su cũng 37 C.<br>Do bỏ qua sự dãn nở vì nhiệt của các ống cao su nên thể tích các ống cao su được bảo toàn. Khi đó, ta có:<br>$\\frac{p_2}{T_2}=\\frac{p_3}{T_3}$    $\\frac{6.{10}^5}{27+273}=\\frac{p_3}{37+273}$    $p_3=6,2.{10}^5$  Pa.<br>Vậy, khi nhiệt độ ngoài trời tăng đến 37 C thì áp suất khối khí trong các ống cao su là 6,2.10<sup>5</sup> Pa.","difficultySource":"ai"}}]},{"id":596122,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["2,2.10<sup>29</sup> MeV .","6,8.10<sup>28</sup> MeV .","2,2.10<sup>28</sup> MeV.","6,8.10<sup>29</sup> MeV."],"question":"Một quả bom sử dụng năng lượng từ các phản ứng nhiệt hạch để nén nguồn nhiên liệu nhằm tăng sức công phá lên hàng chục, hàng trăm lần. Nhiên liệu tổng hợp cho phản ứng nhiệt hạch này là hạt nhân Đoteri (12H ), diễn ra theo phương trình: $5{}_1^2H\\rightarrow {}_2^3He+{}_2^4He+{}_1^1H+2n$ . Lấy khối lượng các hạt  ${}_1^1H;_1^2H;_2^3He;_2^4He$  và notron lần lượt là 1,0079u; 2,0141u; 3,0160u; 4,0026u và 1,0087u. Cho 1uc2 = 931,5MeV, số A-vô-ga-rô là NA = 6,02.10<sup>23</sup>mol-1. Quả bom đó có 150kg Đoteri tham gia thực hiện phản ứng tổng hợp,năng lượng tỏa ra từ quả bom là","difficulty":"trung-binh","explanation":"Nhận xét: cứ 5 đơteri tham gia phản ứng thì sinh ra 1 năng lượng là E<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Trong 1 phản ứng năng lượng tỏa ra là:<br>$\\begin{aligned}\\end{aligned}E=\\left(m_t−m_s\\right).c^2=24,7779\\left(MeV\\right)Website: thukhoadaihoc.vn$<br>$Q=\\frac{1}{5}.\\frac{m}{A}.N_A.E=2,2.10^{29}\\left(MeV\\right)$","difficultySource":"ai"},"ex":[{"exam":301,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["2,2.10<sup>29</sup> MeV .","6,8.10<sup>28</sup> MeV .","2,2.10<sup>28</sup> MeV.","6,8.10<sup>29</sup> MeV."],"question":"Một quả bom sử dụng năng lượng từ các phản ứng nhiệt hạch để nén nguồn nhiên liệu nhằm tăng sức công phá lên hàng chục, hàng trăm lần. Nhiên liệu tổng hợp cho phản ứng nhiệt hạch này là hạt nhân Đoteri (12H ), diễn ra theo phương trình: $5{}_1^2H\\rightarrow {}_2^3He+{}_2^4He+{}_1^1H+2n$ . Lấy khối lượng các hạt  ${}_1^1H;_1^2H;_2^3He;_2^4He$  và notron lần lượt là 1,0079u; 2,0141u; 3,0160u; 4,0026u và 1,0087u. Cho 1uc2 = 931,5MeV, số A-vô-ga-rô là NA = 6,02.10<sup>23</sup>mol-1. Quả bom đó có 150kg Đoteri tham gia thực hiện phản ứng tổng hợp,năng lượng tỏa ra từ quả bom là","difficulty":"trung-binh","explanation":"Nhận xét: cứ 5 đơteri tham gia phản ứng thì sinh ra 1 năng lượng là E<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Trong 1 phản ứng năng lượng tỏa ra là:<br>$\\begin{aligned}\\end{aligned}E=\\left(m_t−m_s\\right).c^2=24,7779\\left(MeV\\right)Website: thukhoadaihoc.vn$<br>$Q=\\frac{1}{5}.\\frac{m}{A}.N_A.E=2,2.10^{29}\\left(MeV\\right)$","difficultySource":"ai"}}]},{"id":596125,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính nhiệt lượng theo nhiệt dung riêng","question":"Một máy nước nóng hoạt động bằng năng lượng Mặt Trời có hiệu  suất chuyển đổi 25%;cường độ bức xạ Mặt Trời lên bộ thu nhiệt là 1000W/m2; diện tích bộ thu là 4,2m2. Cho nhiệt dung riêng của nước là 4200J/kgK.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045629105-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Công suất bức xạ chiếu lên bộ thu nhiệt là 4200W.","answer":true},{"text":"Trong 1h ,năng lượng mặt trời chiếu lên bộ thu nhiệt là 14,4MJ.","answer":false},{"text":"Trong 1h ,phần năng lượng chuyển thành nhiệt năng là 3,78MJ.","answer":true},{"text":"Nếu hệ thống đó ,làm nóng 30kg nước thì trong thời gian 1h nhiệt độ nước tăng thêm 28,60C.","answer":false}],"explanation":"a) đúng<br>P = I.S = 1000.4,2 = 4200W.<br>b) sai<br>A = P.t = 4200.60.60 = 15,12.10<sup>6</sup> = 15,12 MJ .<br>c) đúng<br>Q = H.A = 0,25.15,12 = 3,78MJ .<br>d) sai<br>$Q=mc\\Delta t\\Rightarrow \\Delta t=30^0C$","difficultySource":"ai"},"ex":[{"exam":301,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Tính nhiệt lượng theo nhiệt dung riêng","question":"Một máy nước nóng hoạt động bằng năng lượng Mặt Trời có hiệu  suất chuyển đổi 25%;cường độ bức xạ Mặt Trời lên bộ thu nhiệt là 1000W/m2; diện tích bộ thu là 4,2m2. Cho nhiệt dung riêng của nước là 4200J/kgK.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045629105-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Công suất bức xạ chiếu lên bộ thu nhiệt là 4200W.","answer":true},{"text":"Trong 1h ,năng lượng mặt trời chiếu lên bộ thu nhiệt là 14,4MJ.","answer":false},{"text":"Trong 1h ,phần năng lượng chuyển thành nhiệt năng là 3,78MJ.","answer":true},{"text":"Nếu hệ thống đó ,làm nóng 30kg nước thì trong thời gian 1h nhiệt độ nước tăng thêm 28,60C.","answer":false}],"explanation":"a) đúng<br>P = I.S = 1000.4,2 = 4200W.<br>b) sai<br>A = P.t = 4200.60.60 = 15,12.10<sup>6</sup> = 15,12 MJ .<br>c) đúng<br>Q = H.A = 0,25.15,12 = 3,78MJ .<br>d) sai<br>$Q=mc\\Delta t\\Rightarrow \\Delta t=30^0C$","difficultySource":"ai"}}]},{"id":596130,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình trạng thái khí lí tưởng","answer":"5,9","question":"Khi người đó hít sâu, giả sử không khí trong phổi có 1,4.10<sup>23</sup> phân tử. Dung tích phổi khi đó là bao nhiêu lít (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Ta có:  $pV=nRT\\Rightarrow V=\\frac{nRT}{P}=5,9082$  (lít)<br>Sử dụng các thông tin sau cho Câu 3 và Câu 4: Hai hình dưới là cấu tạo đơn giản và nguyên tắc hoạt động của pháo điện từ đang được triển khai sử dụng trong chiến tranh quân sự. Hai thành kim loại nằm song song nằm ngang ,một thanh kim loại MN đặt trên hai thành ray,vuông góc với các thanh ray.Khi nối hai đầu A và B của các thanh ray với một nguồn điện không đổi có hiệu điện thế lớn,lực điện tử sẽ đẩy MN chuyển động nhanh về phía trước. Cho rằng cường độ dòng điện qua các thanh ray là I = 1000000A, khoảng cách giữa các thanh ray là 40cm. Cảm ứng từ tổng hợp do dòng điện cường độ I trong các đoạn ray AM, BN gây ra tại trung điểm C của MN giống các cảm ứng từ gây ra tại V bởi một dòng điện thẳng dài vô hạn ở hai đầu ,có cường độ I đi qua và đặt tại vị trí ray AM. Cho rằng MN chuyển động không vận tốc đầu trên một quãng đường 1,6m dọc theo thanh ray và không rời ray. Khối lượng thanh ray MN là 2kg.<br>Sử dụng các thông tin sau cho Câu 3 và Câu 4: Hai hình dưới là cấu tạo đơn giản và nguyên tắc hoạt động của pháo điện từ đang được triển khai sử dụng trong chiến tranh quân sự. Hai thành kim loại nằm song song nằm ngang ,một thanh kim loại MN đặt trên hai thành ray,vuông góc với các thanh ray.Khi nối hai đầu A và B của các thanh ray với một nguồn điện không đổi có hiệu điện thế lớn,lực điện tử sẽ đẩy MN chuyển động nhanh về phía trước. Cho rằng cường độ dòng điện qua các thanh ray là I = 1000000A, khoảng cách giữa các thanh ray là 40cm. Cảm ứng từ tổng hợp do dòng điện cường độ I trong các đoạn ray AM, BN gây ra tại trung điểm C của MN giống các cảm ứng từ gây ra tại V bởi một dòng điện thẳng dài vô hạn ở hai đầu ,có cường độ I đi qua và đặt tại vị trí ray AM. Cho rằng MN chuyển động không vận tốc đầu trên một quãng đường 1,6m dọc theo thanh ray và không rời ray. Khối lượng thanh ray MN là 2kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045630014-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />\t<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224383988-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:227px;height:auto\" />","difficultySource":"ai"},"ex":[{"exam":301,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình trạng thái khí lí tưởng","answer":"5,9","question":"Khi người đó hít sâu, giả sử không khí trong phổi có 1,4.10<sup>23</sup> phân tử. Dung tích phổi khi đó là bao nhiêu lít (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Ta có:  $pV=nRT\\Rightarrow V=\\frac{nRT}{P}=5,9082$  (lít)<br>Sử dụng các thông tin sau cho Câu 3 và Câu 4: Hai hình dưới là cấu tạo đơn giản và nguyên tắc hoạt động của pháo điện từ đang được triển khai sử dụng trong chiến tranh quân sự. Hai thành kim loại nằm song song nằm ngang ,một thanh kim loại MN đặt trên hai thành ray,vuông góc với các thanh ray.Khi nối hai đầu A và B của các thanh ray với một nguồn điện không đổi có hiệu điện thế lớn,lực điện tử sẽ đẩy MN chuyển động nhanh về phía trước. Cho rằng cường độ dòng điện qua các thanh ray là I = 1000000A, khoảng cách giữa các thanh ray là 40cm. Cảm ứng từ tổng hợp do dòng điện cường độ I trong các đoạn ray AM, BN gây ra tại trung điểm C của MN giống các cảm ứng từ gây ra tại V bởi một dòng điện thẳng dài vô hạn ở hai đầu ,có cường độ I đi qua và đặt tại vị trí ray AM. Cho rằng MN chuyển động không vận tốc đầu trên một quãng đường 1,6m dọc theo thanh ray và không rời ray. Khối lượng thanh ray MN là 2kg.<br>Sử dụng các thông tin sau cho Câu 3 và Câu 4: Hai hình dưới là cấu tạo đơn giản và nguyên tắc hoạt động của pháo điện từ đang được triển khai sử dụng trong chiến tranh quân sự. Hai thành kim loại nằm song song nằm ngang ,một thanh kim loại MN đặt trên hai thành ray,vuông góc với các thanh ray.Khi nối hai đầu A và B của các thanh ray với một nguồn điện không đổi có hiệu điện thế lớn,lực điện tử sẽ đẩy MN chuyển động nhanh về phía trước. Cho rằng cường độ dòng điện qua các thanh ray là I = 1000000A, khoảng cách giữa các thanh ray là 40cm. Cảm ứng từ tổng hợp do dòng điện cường độ I trong các đoạn ray AM, BN gây ra tại trung điểm C của MN giống các cảm ứng từ gây ra tại V bởi một dòng điện thẳng dài vô hạn ở hai đầu ,có cường độ I đi qua và đặt tại vị trí ray AM. Cho rằng MN chuyển động không vận tốc đầu trên một quãng đường 1,6m dọc theo thanh ray và không rời ray. Khối lượng thanh ray MN là 2kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045630014-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />\t<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224383988-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:227px;height:auto\" />","difficultySource":"ai"}}]},{"id":597211,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"1,45","question":"Một bình có dung tích 20 lít chứa 4,8.10<sup>−3</sup> kg khí helium ở 18oC. Khối lượng mol của helium là  $4,0 g/mol$ . Áp suất khí helium trong bình là b.10<sup>5</sup> Pa. Giá trị của b bằng bao nhiêu? (Kết quả phép tính được thay số một lần và làm tròn đến hai chữ số thập phân).","difficulty":"trung-binh","explanation":"Phương pháp:<br>Áp dụng phương trình Clapeyron.<br>Cách giải:<br>Áp dụng phương trình Clapeyron.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$pV=nRT=\\frac{m}{M}RT$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow p.20.10^{−3}=\\frac{4,8}{4}.8,31.\\left(18+273\\right) Website: thukhoadaihoc.vn$<br>$\\Rightarrow p\\approx 1,45.10^5\\left(Pa\\right)$","difficultySource":"ai"},"ex":[{"exam":303,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"1,45","question":"Một bình có dung tích 20 lít chứa 4,8.10<sup>−3</sup> kg khí helium ở 18oC. Khối lượng mol của helium là  $4,0 g/mol$ . Áp suất khí helium trong bình là b.10<sup>5</sup> Pa. Giá trị của b bằng bao nhiêu? (Kết quả phép tính được thay số một lần và làm tròn đến hai chữ số thập phân).","difficulty":"trung-binh","explanation":"Phương pháp:<br>Áp dụng phương trình Clapeyron.<br>Cách giải:<br>Áp dụng phương trình Clapeyron.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$pV=nRT=\\frac{m}{M}RT$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow p.20.10^{−3}=\\frac{4,8}{4}.8,31.\\left(18+273\\right) Website: thukhoadaihoc.vn$<br>$\\Rightarrow p\\approx 1,45.10^5\\left(Pa\\right)$","difficultySource":"ai"}}]},{"id":598936,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":0,"options":["4,3946.10<sup>24</sup> hạt.","2,7692.10<sup>24</sup> hạt.","3,01.10<sup>22</sup> hạt.","7,1638.10<sup>24</sup> hạt."],"question":"Số hạt neutron có trong 11,9 gam nguyên tử  ${}_{92}^{238}U$  là bao nhiêu? Biết khối lượng mol của  ${}_{92}^{238}U$  là 238 g/mol.","difficulty":"trung-binh","explanation":"Điện áp cực đại của dòng điện này là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$U_0=U.\\sqrt2=220.\\sqrt2\\approx 311$  V.","difficultySource":"ai"},"ex":[{"exam":305,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":0,"options":["4,3946.10<sup>24</sup> hạt.","2,7692.10<sup>24</sup> hạt.","3,01.10<sup>22</sup> hạt.","7,1638.10<sup>24</sup> hạt."],"question":"Số hạt neutron có trong 11,9 gam nguyên tử  ${}_{92}^{238}U$  là bao nhiêu? Biết khối lượng mol của  ${}_{92}^{238}U$  là 238 g/mol.","difficulty":"trung-binh","explanation":"Điện áp cực đại của dòng điện này là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$U_0=U.\\sqrt2=220.\\sqrt2\\approx 311$  V.","difficultySource":"ai"}}]},{"id":598937,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","answer":2,"options":["5,85 triệu năm.","0,65 triệu năm.","1,95 triệu năm.","2,82 triệu năm."],"question":"Năng lượng của Mặt Trời và các ngôi sao trong vũ trụ đều có nguồn gốc từ các phản ứng nhiệt hạch, bắt đầu từ việc đốt cháy hydrogen để tạo thành helium (được gọi là chu trình proton – proton). Xét một ngôi sao đã đốt cháy hoàn toàn hydrogen thành helium và coi rằng các hạt nhân helium tạo thành đều tham gia vào quá trình ba – alpha theo phương trình: 3. ${}_2^4{He}$    ${}_6^{12}C$  + 7,275 MeV. Nếu khối lượng của ngôi sao vào thời điểm đó là 4.10<sup>30</sup> kg (khi tất cả hạt nhân trong ngôi sao đều là helium) và công suất tỏa nhiệt của ngôi sao là 3,8.10<sup>30</sup> W thì sau bao nhiêu triệu năm toàn bộ hạt nhân  ${}_2^4{He}$  sẽ chuyển hóa hoàn toàn thành  ${}_6^{12}C$ ? Lấy khối lượng nguyên tử  ${}_2^4{He}$  bằng 4 amu và một năm có 365 ngày.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045665553-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Số lượng hạt nhân  ${}_2^4{He}$  trong ngôi sao là:  $N=\\frac{m}{M}.N_A=\\frac{4.{10}^{30}.{10}^3}{4}.6,02.{10}^{23}=6,02.{10}^{56}$  hạt.<br>Vì một phản ứng nhiệt hạch cần sử dụng 3 hạt nhân  ${}_2^4{He}$  nên tổng năng lượng tỏa ra của ngôi sao trong quá trình ba  $–$  alpha là:<br>$Q=\\frac{6,02. {10}^{56}.7,275.{10}^6.1,6.{10}^{-19}}{3}=2,33576.{10}^{44}$  J.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Thời gian để toàn bộ hạt nhân  ${}_2^4{He}$  chuyển hóa hoàn toàn thành  ${}_6^{12}C$  là:<br>$t=\\frac{Q}{P}=\\frac{2,33576.{10}^{44}}{3,8.{10}^{30}}\\approx 6,15.{10}^{13} s\\approx 1,95$  triệu năm.","difficultySource":"ai"},"ex":[{"exam":305,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","answer":2,"options":["5,85 triệu năm.","0,65 triệu năm.","1,95 triệu năm.","2,82 triệu năm."],"question":"Năng lượng của Mặt Trời và các ngôi sao trong vũ trụ đều có nguồn gốc từ các phản ứng nhiệt hạch, bắt đầu từ việc đốt cháy hydrogen để tạo thành helium (được gọi là chu trình proton – proton). Xét một ngôi sao đã đốt cháy hoàn toàn hydrogen thành helium và coi rằng các hạt nhân helium tạo thành đều tham gia vào quá trình ba – alpha theo phương trình: 3. ${}_2^4{He}$    ${}_6^{12}C$  + 7,275 MeV. Nếu khối lượng của ngôi sao vào thời điểm đó là 4.10<sup>30</sup> kg (khi tất cả hạt nhân trong ngôi sao đều là helium) và công suất tỏa nhiệt của ngôi sao là 3,8.10<sup>30</sup> W thì sau bao nhiêu triệu năm toàn bộ hạt nhân  ${}_2^4{He}$  sẽ chuyển hóa hoàn toàn thành  ${}_6^{12}C$ ? Lấy khối lượng nguyên tử  ${}_2^4{He}$  bằng 4 amu và một năm có 365 ngày.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045665553-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Số lượng hạt nhân  ${}_2^4{He}$  trong ngôi sao là:  $N=\\frac{m}{M}.N_A=\\frac{4.{10}^{30}.{10}^3}{4}.6,02.{10}^{23}=6,02.{10}^{56}$  hạt.<br>Vì một phản ứng nhiệt hạch cần sử dụng 3 hạt nhân  ${}_2^4{He}$  nên tổng năng lượng tỏa ra của ngôi sao trong quá trình ba  $–$  alpha là:<br>$Q=\\frac{6,02. {10}^{56}.7,275.{10}^6.1,6.{10}^{-19}}{3}=2,33576.{10}^{44}$  J.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Thời gian để toàn bộ hạt nhân  ${}_2^4{He}$  chuyển hóa hoàn toàn thành  ${}_6^{12}C$  là:<br>$t=\\frac{Q}{P}=\\frac{2,33576.{10}^{44}}{3,8.{10}^{30}}\\approx 6,15.{10}^{13} s\\approx 1,95$  triệu năm.","difficultySource":"ai"}}]},{"id":598939,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Một ấm điện khi hoạt động bình thường có điện trở 100  và cường độ dòng điện qua ấm khi đó là 2,5 A. Người ta dùng ấm điện này để đun 1,5 lít nước có nhiệt độ ban đầu là 25 C thì thời gian đun sôi nước là 15 phút. Biết nhiệt dung riêng, khối lượng riêng, nhiệt hóa hơi riêng của nước và nhiệt nóng chảy riêng của nước đá lần lượt là 4200 J/(kg.K), 997 kg/m3, 2,26.10<sup>6</sup> J/kg và 334.103 J/kg. Công suất của ấm điện luôn không đổi. Bỏ qua sự bay hơi của nước trong quá trình đun.","difficulty":"kho","statements":[{"text":"Nhiệt lượng mà ấm điện tỏa ra trong 2 phút là 7,5.10<sup>4</sup> J.","answer":true},{"text":"Hiệu suất của ấm điện xấp xỉ bằng 83,75%.","answer":true},{"text":"Nếu hiệu suất của ấm điện luôn không đổi thì tiếp tục đun khoảng 180 phút nữa (kể từ thời điểm nước bắt đầu sôi) nước trong ấm điện sẽ hóa hơi hoàn toàn.","answer":false},{"text":"Tại thời điểm nước bắt đầu sôi, người ta ngắt điện của ấm và thả vào ấm một lượng nước đá ở 0 C và có khối lượng bằng khối lượng nước trong ấm. Nếu bỏ qua sự trao đổi nhiệt với môi trường thì nhiệt độ của hỗn hợp khi xảy ra sự cân bằng nhiệt là 50 C.","answer":false}],"explanation":"a) đúng<br>Nhiệt lượng mà ấm điện tỏa ra trong 2 phút là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=I^2Rt_1={2,5}^2.100.2.60=7,5.{10}^4$  J.<br>b) đúng<br>Hiệu suất của ấm điện là:<br>$H=\\frac{Q_{thu}}{Q_{tỏa}}.100%=\\frac{m.c.\\Delta T}{I^2Rt_2}.100%=\\frac{D.V.c.\\Delta T}{I^2Rt_2}.100%=\\frac{997.1,5.{10}^{-3}.4200.\\left(100-25\\right)}{{2,5}^2.100.15.60}.100%\\approx 83,75%$ .<br>c) sai<br>Xét quá trình nước bắt đầu sôi đến khi hóa hơi hoàn toàn. Do hiệu suất và công suất của ấm điện không đổi nên ta có:<br>$H=\\frac{Q_{thu}}{Q_{tỏa}}.100%=\\frac{Lm}{I^2Rt_3}.100%$<br>Suy ra:  $\\frac{m.c.\\Delta T}{I^2Rt_2}=\\frac{Lm}{I^2Rt_3}$    $t_3=\\frac{L.t_2}{c.\\Delta T}=\\frac{2,26.{10}^6.15}{4200.\\left(100-25\\right)}\\approx 108$  phút.<br>Vậy nếu tiếp tục đun khoảng 108 phút nữa (kể từ thời điểm nước bắt đầu sôi) thì nước trong ấm điện sẽ hóa hơi hoàn toàn.<br>d) sai<br>Do bỏ qua sự trao đổi nhiệt với môi trường nên ta có:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q_{tỏa}=Q_{thu}$    $mc\\left(100-t_{cb}\\right)=m+mc\\left(t_{cb}-0\\right)$<br>$4200.\\left(100-t_{cb}\\right)=334.{10}^3+4200.t_{cb}$<br>$t_{cb}\\approx 10 ℃$ .<br>Vậy nhiệt độ của hỗn hợp khi có sự cân bằng nhiệt xảy ra là 10 C.","difficultySource":"ai"},"ex":[{"exam":305,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Một ấm điện khi hoạt động bình thường có điện trở 100  và cường độ dòng điện qua ấm khi đó là 2,5 A. Người ta dùng ấm điện này để đun 1,5 lít nước có nhiệt độ ban đầu là 25 C thì thời gian đun sôi nước là 15 phút. Biết nhiệt dung riêng, khối lượng riêng, nhiệt hóa hơi riêng của nước và nhiệt nóng chảy riêng của nước đá lần lượt là 4200 J/(kg.K), 997 kg/m3, 2,26.10<sup>6</sup> J/kg và 334.103 J/kg. Công suất của ấm điện luôn không đổi. Bỏ qua sự bay hơi của nước trong quá trình đun.","difficulty":"kho","statements":[{"text":"Nhiệt lượng mà ấm điện tỏa ra trong 2 phút là 7,5.10<sup>4</sup> J.","answer":true},{"text":"Hiệu suất của ấm điện xấp xỉ bằng 83,75%.","answer":true},{"text":"Nếu hiệu suất của ấm điện luôn không đổi thì tiếp tục đun khoảng 180 phút nữa (kể từ thời điểm nước bắt đầu sôi) nước trong ấm điện sẽ hóa hơi hoàn toàn.","answer":false},{"text":"Tại thời điểm nước bắt đầu sôi, người ta ngắt điện của ấm và thả vào ấm một lượng nước đá ở 0 C và có khối lượng bằng khối lượng nước trong ấm. Nếu bỏ qua sự trao đổi nhiệt với môi trường thì nhiệt độ của hỗn hợp khi xảy ra sự cân bằng nhiệt là 50 C.","answer":false}],"explanation":"a) đúng<br>Nhiệt lượng mà ấm điện tỏa ra trong 2 phút là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=I^2Rt_1={2,5}^2.100.2.60=7,5.{10}^4$  J.<br>b) đúng<br>Hiệu suất của ấm điện là:<br>$H=\\frac{Q_{thu}}{Q_{tỏa}}.100%=\\frac{m.c.\\Delta T}{I^2Rt_2}.100%=\\frac{D.V.c.\\Delta T}{I^2Rt_2}.100%=\\frac{997.1,5.{10}^{-3}.4200.\\left(100-25\\right)}{{2,5}^2.100.15.60}.100%\\approx 83,75%$ .<br>c) sai<br>Xét quá trình nước bắt đầu sôi đến khi hóa hơi hoàn toàn. Do hiệu suất và công suất của ấm điện không đổi nên ta có:<br>$H=\\frac{Q_{thu}}{Q_{tỏa}}.100%=\\frac{Lm}{I^2Rt_3}.100%$<br>Suy ra:  $\\frac{m.c.\\Delta T}{I^2Rt_2}=\\frac{Lm}{I^2Rt_3}$    $t_3=\\frac{L.t_2}{c.\\Delta T}=\\frac{2,26.{10}^6.15}{4200.\\left(100-25\\right)}\\approx 108$  phút.<br>Vậy nếu tiếp tục đun khoảng 108 phút nữa (kể từ thời điểm nước bắt đầu sôi) thì nước trong ấm điện sẽ hóa hơi hoàn toàn.<br>d) sai<br>Do bỏ qua sự trao đổi nhiệt với môi trường nên ta có:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q_{tỏa}=Q_{thu}$    $mc\\left(100-t_{cb}\\right)=m+mc\\left(t_{cb}-0\\right)$<br>$4200.\\left(100-t_{cb}\\right)=334.{10}^3+4200.t_{cb}$<br>$t_{cb}\\approx 10 ℃$ .<br>Vậy nhiệt độ của hỗn hợp khi có sự cân bằng nhiệt xảy ra là 10 C.","difficultySource":"ai"}}]},{"id":599175,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":2,"options":["0,512 eV.","8,20.10‒14 MeV.","0,512 MeV.","8,20.10‒14 eV."],"question":"Khối lượng của mỗi electron là 9,1.10‒31 kg. Biết 1 eV = 1,6.10‒19 J; tốc độ ánh sáng trong chân không là c = 3.10<sup>8</sup> m/s. Năng lượng nghỉ của mỗi electron bằng","difficulty":"de","explanation":"$E_0=m_0.c^2=9,1.10^{−31}.{\\left(3.10^8\\right)}^2\\left(J\\right)=0,512\\left(MeV\\right)$","difficultySource":"ai"},"ex":[{"exam":306,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":2,"options":["0,512 eV.","8,20.10‒14 MeV.","0,512 MeV.","8,20.10‒14 eV."],"question":"Khối lượng của mỗi electron là 9,1.10‒31 kg. Biết 1 eV = 1,6.10‒19 J; tốc độ ánh sáng trong chân không là c = 3.10<sup>8</sup> m/s. Năng lượng nghỉ của mỗi electron bằng","difficulty":"de","explanation":"$E_0=m_0.c^2=9,1.10^{−31}.{\\left(3.10^8\\right)}^2\\left(J\\right)=0,512\\left(MeV\\right)$","difficultySource":"ai"}}]},{"id":599178,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":1,"options":["25,00C","30,50C","65,00C","67,50C"],"question":"Thả 12 viên nước đá vào một cốc cách nhiệt chứa m (g) nước nóng 80,0°C thì nhiệt độ cân bằng của nước là 20,00C. Nhiệt dung riêng của nước là 4180 J/kg.K, của nước đá 2090 J/kg.K và nhiệt nóng chảy riêng của nước đá là 3,33.10<sup>5</sup> J/kg. Các viên đá có khối lượng bằng nhau và có nhiệt độ ‒10,00C. Nếu thả 9 viên nước đá vào cốc nước nói trên thì nhiệt độ cân bằng của nước trong cốc xấp xỉ","difficulty":"kho","explanation":"$Q_{toa}=Q_{thu}\\Leftrightarrow m.4180.60=12m_0.2090.10+12m_0.330000+12m_0.4180.20$<br>$\\Rightarrow m=20,933m_0$<br>$m.4180.\\left(80−t_{cb}\\right)=9m_0.2090.10+9m_0.333000+9m_0.4180.t_{cb}$<br>$\\Rightarrow t_{cb}=30,5\\left({}^0C\\right)$","difficultySource":"ai"},"ex":[{"exam":306,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":1,"options":["25,00C","30,50C","65,00C","67,50C"],"question":"Thả 12 viên nước đá vào một cốc cách nhiệt chứa m (g) nước nóng 80,0°C thì nhiệt độ cân bằng của nước là 20,00C. Nhiệt dung riêng của nước là 4180 J/kg.K, của nước đá 2090 J/kg.K và nhiệt nóng chảy riêng của nước đá là 3,33.10<sup>5</sup> J/kg. Các viên đá có khối lượng bằng nhau và có nhiệt độ ‒10,00C. Nếu thả 9 viên nước đá vào cốc nước nói trên thì nhiệt độ cân bằng của nước trong cốc xấp xỉ","difficulty":"kho","explanation":"$Q_{toa}=Q_{thu}\\Leftrightarrow m.4180.60=12m_0.2090.10+12m_0.330000+12m_0.4180.20$<br>$\\Rightarrow m=20,933m_0$<br>$m.4180.\\left(80−t_{cb}\\right)=9m_0.2090.10+9m_0.333000+9m_0.4180.t_{cb}$<br>$\\Rightarrow t_{cb}=30,5\\left({}^0C\\right)$","difficultySource":"ai"}}]},{"id":599180,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":2,"options":["2,4.10<sup>4</sup> tấn.","7,0.10<sup>4</sup> kg.","7,0.10<sup>4</sup> tấn.","2,4.10<sup>4</sup> kg."],"question":"Một nhà máy nhiệt điện sử dụng hơi nước để làm quay tua bin, mỗi giờ nhà máy sản xuất ra 6,5.10<sup>5</sup> kWh điện năng. Biết nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> J/kg và 35% năng lượng để làm nước hóa hơi ở nhiệt độ sôi chuyển thành điện năng. Khối lượng nước đã hóa hơi để tạo ra điện năng của nhà máy này trong 24 giờ xấp xỉ","difficulty":"trung-binh","explanation":"$6,5.10^5.10^3.60.60=35%.m.2,3.10^6\\Rightarrow m=2906832$<br>$24m=69763675\\approx 7.10^7\\left(kg\\right)\\approx 7.10^4.10^3\\left(kg\\right)$","difficultySource":"ai"},"ex":[{"exam":306,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":2,"options":["2,4.10<sup>4</sup> tấn.","7,0.10<sup>4</sup> kg.","7,0.10<sup>4</sup> tấn.","2,4.10<sup>4</sup> kg."],"question":"Một nhà máy nhiệt điện sử dụng hơi nước để làm quay tua bin, mỗi giờ nhà máy sản xuất ra 6,5.10<sup>5</sup> kWh điện năng. Biết nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> J/kg và 35% năng lượng để làm nước hóa hơi ở nhiệt độ sôi chuyển thành điện năng. Khối lượng nước đã hóa hơi để tạo ra điện năng của nhà máy này trong 24 giờ xấp xỉ","difficulty":"trung-binh","explanation":"$6,5.10^5.10^3.60.60=35%.m.2,3.10^6\\Rightarrow m=2906832$<br>$24m=69763675\\approx 7.10^7\\left(kg\\right)\\approx 7.10^4.10^3\\left(kg\\right)$","difficultySource":"ai"}}]},{"id":599182,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Một lượng khí lí tưởng được chứa trong bình kín có thể tích không đổi. Vào đầu buổi sáng, khí trong bình có áp suất bằng áp suất khí quyển p1 = 105 Pa, nhiệt độ t1 = 140C. Tới giữa trưa, khí trong bình có áp suất p2, nhiệt độ t2 = 280C. Nắp bình bị bật ra khi áp suất khí trong bình là 2.10<sup>5</sup> Pa và khí thoát ra ngoài.","difficulty":"trung-binh","statements":[{"text":"Khối lượng riêng của khí trong bình giảm dần khi nhiệt độ tăng từ 140C tới 280C.","answer":false},{"text":"Áp suất của khí trong bình tăng dần khi nhiệt độ tăng từ 140C tới 280C.","answer":true},{"text":"Tỉ số áp suất p2/p1 là 2.","answer":false},{"text":"Khi nhiệt độ của khí trong bình bằng 3010C thì khí trong bình bắt đầu bị thoát ra ngoài.","answer":true}],"explanation":"a) sai<br>$pV=nRT\\Rightarrow p.V=\\frac{m}{M}.R.T\\Rightarrow pM=D.R.T$<br>$T↑\\Rightarrow$  D không đổi (khí chưa thoát ra ngoài  $\\frac{m}{V}$  không đổi)<br>b) đúng<br>$pM=D.R.T$<br>$T↑\\Rightarrow p↑$<br>c) sai<br>$\\frac{p_2}{p_1}=\\frac{T_2}{T_1}=\\frac{28+273}{14+273}=1,048$<br>d) đúng<br>$\\left(14+273\\right).2−273=301^0C$","difficultySource":"ai"},"ex":[{"exam":306,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Một lượng khí lí tưởng được chứa trong bình kín có thể tích không đổi. Vào đầu buổi sáng, khí trong bình có áp suất bằng áp suất khí quyển p1 = 105 Pa, nhiệt độ t1 = 140C. Tới giữa trưa, khí trong bình có áp suất p2, nhiệt độ t2 = 280C. Nắp bình bị bật ra khi áp suất khí trong bình là 2.10<sup>5</sup> Pa và khí thoát ra ngoài.","difficulty":"trung-binh","statements":[{"text":"Khối lượng riêng của khí trong bình giảm dần khi nhiệt độ tăng từ 140C tới 280C.","answer":false},{"text":"Áp suất của khí trong bình tăng dần khi nhiệt độ tăng từ 140C tới 280C.","answer":true},{"text":"Tỉ số áp suất p2/p1 là 2.","answer":false},{"text":"Khi nhiệt độ của khí trong bình bằng 3010C thì khí trong bình bắt đầu bị thoát ra ngoài.","answer":true}],"explanation":"a) sai<br>$pV=nRT\\Rightarrow p.V=\\frac{m}{M}.R.T\\Rightarrow pM=D.R.T$<br>$T↑\\Rightarrow$  D không đổi (khí chưa thoát ra ngoài  $\\frac{m}{V}$  không đổi)<br>b) đúng<br>$pM=D.R.T$<br>$T↑\\Rightarrow p↑$<br>c) sai<br>$\\frac{p_2}{p_1}=\\frac{T_2}{T_1}=\\frac{28+273}{14+273}=1,048$<br>d) đúng<br>$\\left(14+273\\right).2−273=301^0C$","difficultySource":"ai"}}]},{"id":600333,"nq":{"form":"bai_tap","type":"short_answer","topic":"Từ trường của nam châm và của dòng điện","answer":"4","question":"Cho hai dây dẫn thẳng, song song, cách nhau 15 cm, mang dòng điện cùng chiều, có cường độ lần lượt là I1 = 5 (A), I2 = 8 (A). Cho biết cảm ứng từ do dòng điện thẳng cường độ I (A) gây ra tại điểm cách nó khoảng r (m) được tính theo biểu thức B = 2.10<sup>−7</sup>.  $\\frac{I}{r}$ (T). Cảm ứng từ tổng hợp do hai dòng điện I1, I2 gây ra tại vị trí cách I1 5 cm và cách I2 10 cm là bao nhiêu µT?","difficulty":"trung-binh","explanation":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045684528-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$B=\\left|B_1−B_2\\right|=2.10^{−7}.\\left|\\frac{5}{0,05}−\\frac{8}{0,1}\\right|=4.10^{−6}\\left(T\\right)=4\\left(mT\\right)$","difficultySource":"ai"},"ex":[{"exam":307,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Từ trường của nam châm và của dòng điện","answer":"4","question":"Cho hai dây dẫn thẳng, song song, cách nhau 15 cm, mang dòng điện cùng chiều, có cường độ lần lượt là I1 = 5 (A), I2 = 8 (A). Cho biết cảm ứng từ do dòng điện thẳng cường độ I (A) gây ra tại điểm cách nó khoảng r (m) được tính theo biểu thức B = 2.10<sup>−7</sup>.  $\\frac{I}{r}$ (T). Cảm ứng từ tổng hợp do hai dòng điện I1, I2 gây ra tại vị trí cách I1 5 cm và cách I2 10 cm là bao nhiêu µT?","difficulty":"trung-binh","explanation":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045684528-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$B=\\left|B_1−B_2\\right|=2.10^{−7}.\\left|\\frac{5}{0,05}−\\frac{8}{0,1}\\right|=4.10^{−6}\\left(T\\right)=4\\left(mT\\right)$","difficultySource":"ai"}}]},{"id":600337,"nq":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"2,2","question":"Biết nước có khối lượng mol 18 g/mol và khối lượng riêng 1 g/cm3. Một giọt sương hình cầu đường kính 5 mm có chứa N.10<sup>21</sup> phân tử nước. Giá trị của N bằng bao nhiêu? (làm tròn đến 1 chữ số sau dấu phẩy thập phân)","difficulty":"trung-binh","explanation":"$r=2,5\\left(mm\\right)=0,25\\left(cm\\right)$<br>$N=n.N_A=\\frac{m}{\\mu }N_A=\\frac{\\delta .\\frac{4}{3}\\pi r^3}{\\mu }.N_A$<br>$\\Leftrightarrow N=\\frac{1.\\frac{4}{3}\\pi .0,25^3}{18}.6,023.10^{23}\\approx 2,2.10^{21}$","difficultySource":"ai"},"ex":[{"exam":307,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"2,2","question":"Biết nước có khối lượng mol 18 g/mol và khối lượng riêng 1 g/cm3. Một giọt sương hình cầu đường kính 5 mm có chứa N.10<sup>21</sup> phân tử nước. Giá trị của N bằng bao nhiêu? (làm tròn đến 1 chữ số sau dấu phẩy thập phân)","difficulty":"trung-binh","explanation":"$r=2,5\\left(mm\\right)=0,25\\left(cm\\right)$<br>$N=n.N_A=\\frac{m}{\\mu }N_A=\\frac{\\delta .\\frac{4}{3}\\pi r^3}{\\mu }.N_A$<br>$\\Leftrightarrow N=\\frac{1.\\frac{4}{3}\\pi .0,25^3}{18}.6,023.10^{23}\\approx 2,2.10^{21}$","difficultySource":"ai"}}]},{"id":600486,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["13, 8.10<sup>3</sup> J.","9,2.10<sup>3</sup> J.","32,2.10<sup>3</sup> J.","23,0.10<sup>3</sup> J."],"question":"Một bình nhôm khối lượng 0,5 kg ở nhiệt độ 200C. Tính nhiệt lượng cần cung cấp để nó tăng lên 500C. Biết nhiệt dung của nhôm là 0,92. 103 J/kg.K.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần cung cấp để một vật tăng nhiệt độ được tính theo công thức: $Q = m\\cdot c\\cdot \\Delta t$, trong đó $m$ là khối lượng, $c$ là nhiệt dung riêng và $\\Delta t = t_2 - t_1$ là độ tăng nhiệt độ.</p><p class=\"text-base leading-relaxed my-2\">Dữ liệu: $m = 0{,}5\\ \\text{kg}$; $c = 0{,}92\\cdot 10^3\\ \\text{J/(kg.K)}$; $\\Delta t = 50^\\circ\\text{C} - 20^\\circ\\text{C} = 30^\\circ\\text{C}$ (độ tăng nhiệt độ bằng độ tăng theo thang Kelvin).</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 0{,}5\\cdot 0{,}92\\cdot 10^3\\cdot 30 = 13\\,800\\ \\text{J} = 13{,}8\\cdot 10^3\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy nhiệt lượng cần cung cấp là $13{,}8\\cdot 10^3\\ \\text{J}$, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":308,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["13, 8.10<sup>3</sup> J.","9,2.10<sup>3</sup> J.","32,2.10<sup>3</sup> J.","23,0.10<sup>3</sup> J."],"question":"Một bình nhôm khối lượng 0,5 kg ở nhiệt độ 200C. Tính nhiệt lượng cần cung cấp để nó tăng lên 500C. Biết nhiệt dung của nhôm là 0,92. 103 J/kg.K.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần cung cấp để một vật tăng nhiệt độ được tính theo công thức: $Q = m\\cdot c\\cdot \\Delta t$, trong đó $m$ là khối lượng, $c$ là nhiệt dung riêng và $\\Delta t = t_2 - t_1$ là độ tăng nhiệt độ.</p><p class=\"text-base leading-relaxed my-2\">Dữ liệu: $m = 0{,}5\\ \\text{kg}$; $c = 0{,}92\\cdot 10^3\\ \\text{J/(kg.K)}$; $\\Delta t = 50^\\circ\\text{C} - 20^\\circ\\text{C} = 30^\\circ\\text{C}$ (độ tăng nhiệt độ bằng độ tăng theo thang Kelvin).</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 0{,}5\\cdot 0{,}92\\cdot 10^3\\cdot 30 = 13\\,800\\ \\text{J} = 13{,}8\\cdot 10^3\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy nhiệt lượng cần cung cấp là $13{,}8\\cdot 10^3\\ \\text{J}$, đáp án A.</p>","difficultySource":"ai"}}]},{"id":600500,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":2,"options":["2,99. 10<sup>−20</sup> J.","1,28. 10<sup>−21</sup> J.","2,99. 10<sup>−18</sup> J.","3,35. 10<sup>−20</sup> J."],"question":"Một bình chứa 1 mol khí Neon, xảy ra quá trình như hình vẽ. Từ trạng thái 1 qua trạng thái 2 là đẳng nhiệt. Động năng trung bình của các phân tử khí Neon ở trạng thái 3 bằng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045689542-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"(1) qua (2) là đẳng nhiệt  $\\Rightarrow p_1V_1=p_2V_2\\Rightarrow 6.10^5V_1=3.10^5.8\\Rightarrow V_1=V_3=4m^3$<br>$\\mu_3=\\frac{N}{V_3}=\\frac{nN_A}{V_3}=\\frac{6,02.10^{23}}{4}=1,505.10^{23}m^{−3}$<br>$W_d=\\frac{3}{2}kT_3=\\frac{3p_3}{2\\mu_3}=\\frac{3.3.10^5}{2.1,505.10^{23}}\\approx 2,99.10^{−18}J$","difficultySource":"ai"},"ex":[{"exam":308,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":2,"options":["2,99. 10<sup>−20</sup> J.","1,28. 10<sup>−21</sup> J.","2,99. 10<sup>−18</sup> J.","3,35. 10<sup>−20</sup> J."],"question":"Một bình chứa 1 mol khí Neon, xảy ra quá trình như hình vẽ. Từ trạng thái 1 qua trạng thái 2 là đẳng nhiệt. Động năng trung bình của các phân tử khí Neon ở trạng thái 3 bằng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045689542-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"(1) qua (2) là đẳng nhiệt  $\\Rightarrow p_1V_1=p_2V_2\\Rightarrow 6.10^5V_1=3.10^5.8\\Rightarrow V_1=V_3=4m^3$<br>$\\mu_3=\\frac{N}{V_3}=\\frac{nN_A}{V_3}=\\frac{6,02.10^{23}}{4}=1,505.10^{23}m^{−3}$<br>$W_d=\\frac{3}{2}kT_3=\\frac{3p_3}{2\\mu_3}=\\frac{3.3.10^5}{2.1,505.10^{23}}\\approx 2,99.10^{−18}J$","difficultySource":"ai"}}]},{"id":600503,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng ΔU = A + Q","question":"Hình bên là một máy nén khí pit-tông Puma có dung tích của bình chứa khí là 90 L; không khí được nạp vào bình với lưu lượng 160 L/phút và khi đạt áp suất tới hạn là 8.10<sup>5</sup> Pa thì rơ-le sẽ ngắt động cơ điện.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045689865-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Rơ-le ngắt động cơ điện khi thể tích của khí bên trong bình tăng đạt ngưỡng tới hạn.","answer":false},{"text":"Trong không khí có chứa một lượng hơi nước. Nếu không khí được nén ở áp suất cao thì sau một thời gian sử dụng có thể sẽ có một lượng nước tích tụ trong bình chứa khí.","answer":true},{"text":"Nếu máy nén khí hoạt động rất nhanh làm cho khối khí bị nén không kịp trao đổi nhiệt với môi trường thì có thể coi gần như toàn bộ công do ngoại lực thực hiện để nén khí đã làm tăng nội năng của khối khí.","answer":true},{"text":"Coi nhiệt lượng tỏa ra môi trường trong thời gian nén khí là không đáng kể và coi không khí nạp vào bình như khí lí tưởng. Ban đầu trong bình chứa không khí ở áp suất khí quyển là 105 Pa và có nhiệt độ là 270C. Sau thời gian nén khí là 3,5 phút thì rơ-le sẽ ngắt động cơ điện. Khi đó nhiệt độ của khí nén trong bình chứa khí là 610C (làm tròn kết quả đến chữ số hàng đơn vị).","answer":false}],"explanation":"a) sai<br>Rơ-le ngắt khi áp suất đạt ngưỡng 8.10<sup>5</sup> Pa.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Nén khí làm tăng áp suất nên hơi nước có thể ngưng tụ<br>c) đúng<br>Không trao đổi nhiệt  $\\Rightarrow Q=0\\Rightarrow \\Delta U=A$<br>d) sai<br>$\\frac{pV}{T}=const\\Rightarrow \\frac{10^5.\\left(90+160.3,5\\right)}{27+273}=\\frac{8.10^5.90}{T}\\Rightarrow T\\approx 323K=59^0C$","difficultySource":"ai"},"ex":[{"exam":308,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng ΔU = A + Q","question":"Hình bên là một máy nén khí pit-tông Puma có dung tích của bình chứa khí là 90 L; không khí được nạp vào bình với lưu lượng 160 L/phút và khi đạt áp suất tới hạn là 8.10<sup>5</sup> Pa thì rơ-le sẽ ngắt động cơ điện.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045689865-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Rơ-le ngắt động cơ điện khi thể tích của khí bên trong bình tăng đạt ngưỡng tới hạn.","answer":false},{"text":"Trong không khí có chứa một lượng hơi nước. Nếu không khí được nén ở áp suất cao thì sau một thời gian sử dụng có thể sẽ có một lượng nước tích tụ trong bình chứa khí.","answer":true},{"text":"Nếu máy nén khí hoạt động rất nhanh làm cho khối khí bị nén không kịp trao đổi nhiệt với môi trường thì có thể coi gần như toàn bộ công do ngoại lực thực hiện để nén khí đã làm tăng nội năng của khối khí.","answer":true},{"text":"Coi nhiệt lượng tỏa ra môi trường trong thời gian nén khí là không đáng kể và coi không khí nạp vào bình như khí lí tưởng. Ban đầu trong bình chứa không khí ở áp suất khí quyển là 105 Pa và có nhiệt độ là 270C. Sau thời gian nén khí là 3,5 phút thì rơ-le sẽ ngắt động cơ điện. Khi đó nhiệt độ của khí nén trong bình chứa khí là 610C (làm tròn kết quả đến chữ số hàng đơn vị).","answer":false}],"explanation":"a) sai<br>Rơ-le ngắt khi áp suất đạt ngưỡng 8.10<sup>5</sup> Pa.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Nén khí làm tăng áp suất nên hơi nước có thể ngưng tụ<br>c) đúng<br>Không trao đổi nhiệt  $\\Rightarrow Q=0\\Rightarrow \\Delta U=A$<br>d) sai<br>$\\frac{pV}{T}=const\\Rightarrow \\frac{10^5.\\left(90+160.3,5\\right)}{27+273}=\\frac{8.10^5.90}{T}\\Rightarrow T\\approx 323K=59^0C$","difficultySource":"ai"}}]},{"id":600507,"nq":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ áp suất với động năng phân tử","answer":"2,1","question":"Một bình chứa khí Neon có khối lượng riêng là 1,8 kg/m3 và giá trị trung bình của bình phương tốc độ của các phân tử khí là 3,5.10<sup>5</sup> m2/s2. Giá trị áp suất của khí trong bình là x.10<sup>5</sup> N/m2 bằng bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng phương trình cơ bản của thuyết động học phân tử chất khí: áp suất khí tác dụng lên thành bình được xác định bởi khối lượng riêng và trung bình bình phương tốc độ của các phân tử.</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: $p = \\dfrac{1}{3}\\rho \\overline{v^2}$</p><p class=\"text-base leading-relaxed my-2\">Thay số với $\\rho = 1{,}8$ kg/m³ và $\\overline{v^2} = 3{,}5\\cdot 10^5$ m²/s²:</p><p class=\"text-base leading-relaxed my-2\">$p = \\dfrac{1}{3}\\cdot 1{,}8\\cdot 3{,}5\\cdot 10^5 = 2{,}1\\cdot 10^5$ N/m²</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow x = 2{,}1$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: áp suất của khí trong bình là $2{,}1\\cdot 10^5$ N/m², tức $x = 2{,}1$.</p>","difficultySource":"ai"},"ex":[{"exam":308,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ áp suất với động năng phân tử","answer":"2,1","question":"Một bình chứa khí Neon có khối lượng riêng là 1,8 kg/m3 và giá trị trung bình của bình phương tốc độ của các phân tử khí là 3,5.10<sup>5</sup> m2/s2. Giá trị áp suất của khí trong bình là x.10<sup>5</sup> N/m2 bằng bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng phương trình cơ bản của thuyết động học phân tử chất khí: áp suất khí tác dụng lên thành bình được xác định bởi khối lượng riêng và trung bình bình phương tốc độ của các phân tử.</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: $p = \\dfrac{1}{3}\\rho \\overline{v^2}$</p><p class=\"text-base leading-relaxed my-2\">Thay số với $\\rho = 1{,}8$ kg/m³ và $\\overline{v^2} = 3{,}5\\cdot 10^5$ m²/s²:</p><p class=\"text-base leading-relaxed my-2\">$p = \\dfrac{1}{3}\\cdot 1{,}8\\cdot 3{,}5\\cdot 10^5 = 2{,}1\\cdot 10^5$ N/m²</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow x = 2{,}1$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: áp suất của khí trong bình là $2{,}1\\cdot 10^5$ N/m², tức $x = 2{,}1$.</p>","difficultySource":"ai"}}]},{"id":600955,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng ΔU = A + Q","question":"Một lượng khí chứa trong một xilanh có piston di chuyển được. Ở trạng thái ban đầu, chất khí chiếm thể tích V và có áp suất 2.10<sup>5</sup> N/m². Khối khí nhận một nhiệt lượng 100 J giãn nở đẩy piston di chuyển làm thể tích khí tăng thêm 10 cm³. Coi rằng áp suất chất khí trong xi lanh không đổi khi piston di chuyển.","difficulty":"kho","statements":[{"text":"Lượng khí bên trong xilanh nhận nhiệt và sinh công làm biến đổi nội năng.","answer":true},{"text":"Công mà khối khí thực hiện có độ lớn bằng 20.105J.","answer":false},{"text":"Theo quy ước, khối khí nhận nhiệt và sinh công nên A > 0; Q > 0.","answer":false},{"text":"Độ biến thiên nội năng của khối khí ΔU = 98 J.","answer":true}],"explanation":"a) đúng<br>Khối khí nhận nhiệt lượng 100J → sinh công làm di chuyển piston<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>$\\left|A\\right|=\\left|p.\\Delta V\\right|=2.10^5.10.10^{−6}2\\left(J\\right)$<br>c) sai<br>Theo nguyên lý nhiệt động lực học: Nhận nhiệt  $Q>0$ , sinh công  $A<0$<br>d) đúng<br>$\\Delta U=Q+A=100+\\left(−2\\right)=98\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":309,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng ΔU = A + Q","question":"Một lượng khí chứa trong một xilanh có piston di chuyển được. Ở trạng thái ban đầu, chất khí chiếm thể tích V và có áp suất 2.10<sup>5</sup> N/m². Khối khí nhận một nhiệt lượng 100 J giãn nở đẩy piston di chuyển làm thể tích khí tăng thêm 10 cm³. Coi rằng áp suất chất khí trong xi lanh không đổi khi piston di chuyển.","difficulty":"kho","statements":[{"text":"Lượng khí bên trong xilanh nhận nhiệt và sinh công làm biến đổi nội năng.","answer":true},{"text":"Công mà khối khí thực hiện có độ lớn bằng 20.105J.","answer":false},{"text":"Theo quy ước, khối khí nhận nhiệt và sinh công nên A > 0; Q > 0.","answer":false},{"text":"Độ biến thiên nội năng của khối khí ΔU = 98 J.","answer":true}],"explanation":"a) đúng<br>Khối khí nhận nhiệt lượng 100J → sinh công làm di chuyển piston<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>$\\left|A\\right|=\\left|p.\\Delta V\\right|=2.10^5.10.10^{−6}2\\left(J\\right)$<br>c) sai<br>Theo nguyên lý nhiệt động lực học: Nhận nhiệt  $Q>0$ , sinh công  $A<0$<br>d) đúng<br>$\\Delta U=Q+A=100+\\left(−2\\right)=98\\left(J\\right)$","difficultySource":"ai"}}]},{"id":600956,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một học sinh dùng bơm tay để bơm không khí vào một quả bóng cao su có dung tích là 3 lít, với áp suất không khí ban đầu trong bóng bằng áp suất khí quyển là 105 N/m². Mỗi lần bơm, độ dịch chuyển của piston là 42 cm, tiết diện piston là 11cm². Biết trong quá trình bơm nhiệt độ không thay đổi.","difficulty":"kho","statements":[{"text":"Sau khi bơm thể tích khí được đưa vào bóng giảm tỉ lệ thuận với áp suất.","answer":false},{"text":"Thể tích khí được đưa vào bóng sau mỗi lần bơm là 462cm³.","answer":true},{"text":"Sau 10 lần bơm, áp suất khí trong quả bóng là 2,45.10<sup>5</sup> Pa.","answer":false},{"text":"Để áp suất khí trong quả bóng là 5.10<sup>5</sup> N/m². Số lần bơm xấp xỉ 26 lần.","answer":true}],"explanation":"a) sai<br>Ban đầu bên trong đã có không khí ở thể tích là 3 lít và áp suất 105 N/m2<br>Thể tích khí đưa vào sau mỗi lần bơm: Lấy độ dịch chuyển của piston x tiệt diện piston.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Chỉ cho piston dịch chuyển 1 đoạn không đổi (thể tích cứ thế nhân vào)<br>$V_0=42.11=462cm^3=4,62.10^{−4}m^3$<br>b) đúng<br>Tính ở câu a)<br>c) sai<br>$\\begin{aligned}\\end{aligned}p_1V_1=p_2V_2\\Rightarrow 10^5.\\left(3.10^{−3}+10.4,62.10^{−4}\\right)=p_2.3.10^{−3}\\Rightarrow p_2=2,54.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>$p_3V_3=p_4.V_4\\Rightarrow 10^5.\\left(3.10^{−3}+n.4,62.10^{−4}\\right)=5.10^5.\\left(3.10^{−3}\\right)$<br>$\\Rightarrow n=25,974\\Rightarrow$  26 lanaf","difficultySource":"ai"},"ex":[{"exam":309,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một học sinh dùng bơm tay để bơm không khí vào một quả bóng cao su có dung tích là 3 lít, với áp suất không khí ban đầu trong bóng bằng áp suất khí quyển là 105 N/m². Mỗi lần bơm, độ dịch chuyển của piston là 42 cm, tiết diện piston là 11cm². Biết trong quá trình bơm nhiệt độ không thay đổi.","difficulty":"kho","statements":[{"text":"Sau khi bơm thể tích khí được đưa vào bóng giảm tỉ lệ thuận với áp suất.","answer":false},{"text":"Thể tích khí được đưa vào bóng sau mỗi lần bơm là 462cm³.","answer":true},{"text":"Sau 10 lần bơm, áp suất khí trong quả bóng là 2,45.10<sup>5</sup> Pa.","answer":false},{"text":"Để áp suất khí trong quả bóng là 5.10<sup>5</sup> N/m². Số lần bơm xấp xỉ 26 lần.","answer":true}],"explanation":"a) sai<br>Ban đầu bên trong đã có không khí ở thể tích là 3 lít và áp suất 105 N/m2<br>Thể tích khí đưa vào sau mỗi lần bơm: Lấy độ dịch chuyển của piston x tiệt diện piston.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Chỉ cho piston dịch chuyển 1 đoạn không đổi (thể tích cứ thế nhân vào)<br>$V_0=42.11=462cm^3=4,62.10^{−4}m^3$<br>b) đúng<br>Tính ở câu a)<br>c) sai<br>$\\begin{aligned}\\end{aligned}p_1V_1=p_2V_2\\Rightarrow 10^5.\\left(3.10^{−3}+10.4,62.10^{−4}\\right)=p_2.3.10^{−3}\\Rightarrow p_2=2,54.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>$p_3V_3=p_4.V_4\\Rightarrow 10^5.\\left(3.10^{−3}+n.4,62.10^{−4}\\right)=5.10^5.\\left(3.10^{−3}\\right)$<br>$\\Rightarrow n=25,974\\Rightarrow$  26 lanaf","difficultySource":"ai"}}]},{"id":600964,"nq":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"1","question":"Một bình kín chứa 3,01.10<sup>23</sup> phân tử khí Hydrogen. Khối lượng khí Hydrogen trong bình là bao nhiêu gam? Lấy số Avogadro NA = 6,02.10<sup>23</sup> mol-1. (Kết quả được lấy đến phần nguyên).","difficulty":"de","explanation":"Số mol:  $n=\\frac{3,01.10^{23}}{6,02.10^{23}}=0,5\\left(mol\\right)$  H2<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Khối lượng:  $m=n.2=1\\left(gam\\right)$","difficultySource":"ai"},"ex":[{"exam":309,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"1","question":"Một bình kín chứa 3,01.10<sup>23</sup> phân tử khí Hydrogen. Khối lượng khí Hydrogen trong bình là bao nhiêu gam? Lấy số Avogadro NA = 6,02.10<sup>23</sup> mol-1. (Kết quả được lấy đến phần nguyên).","difficulty":"de","explanation":"Số mol:  $n=\\frac{3,01.10^{23}}{6,02.10^{23}}=0,5\\left(mol\\right)$  H2<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Khối lượng:  $m=n.2=1\\left(gam\\right)$","difficultySource":"ai"}}]},{"id":601176,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":2,"options":["7,4.10<sup>7</sup>.","3,7.10<sup>10</sup>.","1,5.10<sup>8</sup>.","3,7.10<sup>7</sup>."],"question":"Năm 1910, một đơn vị đo phóng xạ được là Curie (kí hiệu là Ci) được đưa ra. Biết 1 Ci là số phân rã trong mỗi giây của 1,00 g radium  ${}_{88}^{226}Ra$  có chu kỳ bán rã là 1580 năm. Số phân rã của một mẫu radium  ${}_{88}^{226}Ra$ với độ phóng xạ 2 mCi trong 2 giây xấp xỉ","difficulty":"kho","explanation":"$1Ci=37.10^9(Bq)\\Rightarrow 2mCi=2.37.10^{−3}.10^9\\left(Bq\\right)=74.10^6\\left(Bq\\right)$<br>$\\Rightarrow$  Trong 2(s)  $=2.74.10^6=1,5.10^8$<br>$N=\\frac{m}{M}.N_A=\\frac{1}{226}.6,02.10^{23}=2,66.10^{21}$<br>$H=N.\\frac{ln2}{T}=2,66.10^{21}.\\frac{ln2}{1580.365.24.60.60}=3,7.10^{10}\\left(Bq\\right)$","difficultySource":"ai"},"ex":[{"exam":310,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":2,"options":["7,4.10<sup>7</sup>.","3,7.10<sup>10</sup>.","1,5.10<sup>8</sup>.","3,7.10<sup>7</sup>."],"question":"Năm 1910, một đơn vị đo phóng xạ được là Curie (kí hiệu là Ci) được đưa ra. Biết 1 Ci là số phân rã trong mỗi giây của 1,00 g radium  ${}_{88}^{226}Ra$  có chu kỳ bán rã là 1580 năm. Số phân rã của một mẫu radium  ${}_{88}^{226}Ra$ với độ phóng xạ 2 mCi trong 2 giây xấp xỉ","difficulty":"kho","explanation":"$1Ci=37.10^9(Bq)\\Rightarrow 2mCi=2.37.10^{−3}.10^9\\left(Bq\\right)=74.10^6\\left(Bq\\right)$<br>$\\Rightarrow$  Trong 2(s)  $=2.74.10^6=1,5.10^8$<br>$N=\\frac{m}{M}.N_A=\\frac{1}{226}.6,02.10^{23}=2,66.10^{21}$<br>$H=N.\\frac{ln2}{T}=2,66.10^{21}.\\frac{ln2}{1580.365.24.60.60}=3,7.10^{10}\\left(Bq\\right)$","difficultySource":"ai"}}]},{"id":601180,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":3,"options":["3,1.10<sup>9</sup> Hz.","3,1.10<sup>15</sup> Hz.","3,2.10<sup>11</sup> Hz.","3,2.10<sup>14</sup> Hz."],"question":"Một chiếc điều khiển từ xa của quạt trần sử dụng LED hồng ngoại để phát ra sóng điện từ có bước sóng 940 nm để gửi tới bộ thu sóng gắn trong quạt. Tốc độ truyền hồng ngoại trong không khí là c = 3.10<sup>8</sup> m/s. Tần số của tia hồng ngoại của điều khiển xấp xỉ","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng hồng ngoại là sóng điện từ, lan truyền trong không khí với tốc độ $c$ và liên hệ với tần số $f$, bước sóng $\\lambda$ theo công thức: $c = \\lambda f$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra tần số: $f = \\dfrac{c}{\\lambda}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $\\lambda = 940\\ \\text{nm} = 940.10^{-9}\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $f = \\dfrac{3.10^{8}}{940.10^{-9}} \\approx 3,2.10^{14}\\ \\text{Hz}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tần số của tia hồng ngoại xấp xỉ $3,2.10^{14}\\ \\text{Hz}$, chọn đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":310,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":3,"options":["3,1.10<sup>9</sup> Hz.","3,1.10<sup>15</sup> Hz.","3,2.10<sup>11</sup> Hz.","3,2.10<sup>14</sup> Hz."],"question":"Một chiếc điều khiển từ xa của quạt trần sử dụng LED hồng ngoại để phát ra sóng điện từ có bước sóng 940 nm để gửi tới bộ thu sóng gắn trong quạt. Tốc độ truyền hồng ngoại trong không khí là c = 3.10<sup>8</sup> m/s. Tần số của tia hồng ngoại của điều khiển xấp xỉ","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng hồng ngoại là sóng điện từ, lan truyền trong không khí với tốc độ $c$ và liên hệ với tần số $f$, bước sóng $\\lambda$ theo công thức: $c = \\lambda f$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra tần số: $f = \\dfrac{c}{\\lambda}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $\\lambda = 940\\ \\text{nm} = 940.10^{-9}\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $f = \\dfrac{3.10^{8}}{940.10^{-9}} \\approx 3,2.10^{14}\\ \\text{Hz}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tần số của tia hồng ngoại xấp xỉ $3,2.10^{14}\\ \\text{Hz}$, chọn đáp án D.</p>","difficultySource":"ai"}}]},{"id":601185,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","question":"Xét phản ứng nhiệt hạch có phương trình  ${}_1^2H+{}_1^3H\\rightarrow {}_2^4He+{}_0^1n+17,6 MeV$  .","difficulty":"trung-binh","statements":[{"text":"Phản ứng hạt nhân trên là phản ứng tỏa năng lượng.","answer":true},{"text":"Phản ứng trên tuân theo định luật bảo toàn khối lượng.","answer":false},{"text":"Điện tích của hạt  ${}_0^1n$  là +1,6.10<sup>−19</sup>C","answer":false},{"text":"Lực tương tác điện giữa hai hạt nhân  ${}_1^2H$  và hạt nhân  ${}_1^3H$  là lực đẩy.","answer":true}],"explanation":"a) đúng<br>${}_1^2H+{}_1^3H\\rightarrow {}_2^4He+{}_0^1n+17,6 MeV$<br>$\\Rightarrow$  Đây là phản ứng nhiệt hạch<br>b) sai<br>Các phản ứng hạt nhân không tuân theo định luật bảo toàn khối lượng<br>Chỉ tuân theo định luật bảo toàn năng lượng toàn phần.<br>Trong phản ứng hạt nhân nó có sự biến đổi từ khối lượng sang năng lượng thông qua  $Q=\\left(m_t−m_s\\right)c^2$<br>c) sai<br>Hạt  ${}_0^1n$ không mang điện<br>d) đúng<br>Lực tương tác điện giữa hai hạt nhân  ${}_1^2H$  và hạt nhân  ${}_1^3H$  là lực đẩy.<br>Vì  ${}_1^2H$ ;  ${}_1^3H$  mang điện tích dương","difficultySource":"ai"},"ex":[{"exam":310,"idx":19,"el":{"form":"ly_thuyet","type":"true_false","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","question":"Xét phản ứng nhiệt hạch có phương trình  ${}_1^2H+{}_1^3H\\rightarrow {}_2^4He+{}_0^1n+17,6 MeV$  .","difficulty":"trung-binh","statements":[{"text":"Phản ứng hạt nhân trên là phản ứng tỏa năng lượng.","answer":true},{"text":"Phản ứng trên tuân theo định luật bảo toàn khối lượng.","answer":false},{"text":"Điện tích của hạt  ${}_0^1n$  là +1,6.10<sup>−19</sup>C","answer":false},{"text":"Lực tương tác điện giữa hai hạt nhân  ${}_1^2H$  và hạt nhân  ${}_1^3H$  là lực đẩy.","answer":true}],"explanation":"a) đúng<br>${}_1^2H+{}_1^3H\\rightarrow {}_2^4He+{}_0^1n+17,6 MeV$<br>$\\Rightarrow$  Đây là phản ứng nhiệt hạch<br>b) sai<br>Các phản ứng hạt nhân không tuân theo định luật bảo toàn khối lượng<br>Chỉ tuân theo định luật bảo toàn năng lượng toàn phần.<br>Trong phản ứng hạt nhân nó có sự biến đổi từ khối lượng sang năng lượng thông qua  $Q=\\left(m_t−m_s\\right)c^2$<br>c) sai<br>Hạt  ${}_0^1n$ không mang điện<br>d) đúng<br>Lực tương tác điện giữa hai hạt nhân  ${}_1^2H$  và hạt nhân  ${}_1^3H$  là lực đẩy.<br>Vì  ${}_1^2H$ ;  ${}_1^3H$  mang điện tích dương","difficultySource":"ai"}}]},{"id":601187,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Chuối là một trong các loại trái cây được đánh giá cao về mặt dinh dưỡng. Trong chuối có chứa potassium (Kali-K) giúp ngăn ngừa tình trạng chuột rút do mất cân bằng điện giải. Chính vì tác dụng này nên các vận động viên tennis thường ăn chuối trong giờ nghỉ giữa các set thi đấu. Potassium trong chuối tồn tại ở ba đồng vị ${}_{19}^{39}K;_{19}^{40}K;_{19}^{41}K$ . Trong đó:  ${}_{19}^{39}K$ và  ${}_{19}^{41}K$  là những đồng vị bền;  ${}_{19}^{40}K$  là đồng vị phóng xạ với chu kì bán rã 1,28.10<sup>9</sup> năm.","difficulty":"trung-binh","statements":[{"text":"Các đồng vị của potassium đều có 19 proton.","answer":true},{"text":"Các đồng vị của potassium đều có 21 neutron.","answer":false},{"text":"Hằng số phóng xạ của đồng vị 4019K là 1,48.10<sup>−12</sup> s-1","answer":false},{"text":"Lấy số Avogadro NA = 6,02.10<sup>23</sup> hạt/mol; khối lượng mol của potassium  ${}_{19}^{40}K$  là 40 g/mol. Độ phóng xạ của 59 µg potassium µ là 15 Bq. (làm tròn kết quả đến chữ số hàng đơn vị).","answer":true}],"explanation":"a) đúng<br>${}_{19}^{39}K;_{19}^{40}K;_{19}^{41}K\\Rightarrow 19 proton$ (Có chung điện tích)<br>b) sai<br>Các đồng vị khác nhau về số neutron, số khối khác nhau<br>c) sai<br>$\\lambda =\\frac{ln2}{1,28.10^9.365.24.60.60}=1,714.10^{−17}\\left(s^{−1}\\right)$<br>d) đúng<br>$H=N\\lambda =\\frac{m}{M}N_A\\lambda =\\left(\\frac{59.10^{−6}}{40}.6,02.10^{23}\\right).1,714.10^{−17}=15,247\\left(Bq\\right)$","difficultySource":"ai"},"ex":[{"exam":310,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Chuối là một trong các loại trái cây được đánh giá cao về mặt dinh dưỡng. Trong chuối có chứa potassium (Kali-K) giúp ngăn ngừa tình trạng chuột rút do mất cân bằng điện giải. Chính vì tác dụng này nên các vận động viên tennis thường ăn chuối trong giờ nghỉ giữa các set thi đấu. Potassium trong chuối tồn tại ở ba đồng vị ${}_{19}^{39}K;_{19}^{40}K;_{19}^{41}K$ . Trong đó:  ${}_{19}^{39}K$ và  ${}_{19}^{41}K$  là những đồng vị bền;  ${}_{19}^{40}K$  là đồng vị phóng xạ với chu kì bán rã 1,28.10<sup>9</sup> năm.","difficulty":"trung-binh","statements":[{"text":"Các đồng vị của potassium đều có 19 proton.","answer":true},{"text":"Các đồng vị của potassium đều có 21 neutron.","answer":false},{"text":"Hằng số phóng xạ của đồng vị 4019K là 1,48.10<sup>−12</sup> s-1","answer":false},{"text":"Lấy số Avogadro NA = 6,02.10<sup>23</sup> hạt/mol; khối lượng mol của potassium  ${}_{19}^{40}K$  là 40 g/mol. Độ phóng xạ của 59 µg potassium µ là 15 Bq. (làm tròn kết quả đến chữ số hàng đơn vị).","answer":true}],"explanation":"a) đúng<br>${}_{19}^{39}K;_{19}^{40}K;_{19}^{41}K\\Rightarrow 19 proton$ (Có chung điện tích)<br>b) sai<br>Các đồng vị khác nhau về số neutron, số khối khác nhau<br>c) sai<br>$\\lambda =\\frac{ln2}{1,28.10^9.365.24.60.60}=1,714.10^{−17}\\left(s^{−1}\\right)$<br>d) đúng<br>$H=N\\lambda =\\frac{m}{M}N_A\\lambda =\\left(\\frac{59.10^{−6}}{40}.6,02.10^{23}\\right).1,714.10^{−17}=15,247\\left(Bq\\right)$","difficultySource":"ai"}}]}]$j$::jsonb) loop
    h := public.question_content_hash(r->'nq');
    if exists (select 1 from public.question_bank where content_hash = h and id <> (r->>'id')::bigint) then raise notice 'TRUNG %', r->>'id'; continue; end if;
    update public.question_bank set question = r->'nq', content_hash = h, updated_at = now() where id = (r->>'id')::bigint;
    for e in select * from jsonb_array_elements(r->'ex') loop
      update public.exams set questions = jsonb_set(questions, array[e->>'idx'], e->'el') where id = (e->>'exam')::bigint;
    end loop;
  end loop;
end $do$;
alter table public.exams enable trigger trg_exams_sync_bank;
commit;
